window.QALAB_BUNDLE = {"manifest":{"generatedAt":"2026-08-15T03:21:54.013Z","tracks":[{"id":"track-1-fundamentals","title":"트랙 1. QA 기본기","shortTitle":"1. QA 기본기","summary":"채용공고 공통 요구사항. 테스트 계획·전략, TC 설계 기법, 결함 리포트, 릴리즈 판단, 품질 지표까지 QA의 뼈대를 세운다.","outcomes":["요구사항을 받아 테스트 전략 문서와 테스트 계획을 스스로 작성할 수 있다","동등분할·경계값·상태전이·페어와이즈·결정테이블을 상황에 맞게 골라 쓸 수 있다","개발자가 되묻지 않는 결함 리포트를 쓸 수 있다","품질 지표를 근거로 배포 Go/No-Go 의견을 낼 수 있다"],"lessons":[{"id":"t1-l01","title":"테스트 계획과 테스트 전략 문서","summary":"전략과 계획의 차이를 구분하고, 리스크 기반으로 테스트 범위를 정하는 문서를 직접 작성한다.","minutes":20,"tags":["테스트계획","테스트전략","리스크기반테스팅"],"order":1,"path":"track-1-fundamentals/01-test-planning.md"},{"id":"t1-l02","title":"TC 설계 기법 (1) 동등분할과 경계값 분석","summary":"무한한 입력을 유한한 테스트로 줄이는 두 기본 기법. 경계에서 결함이 나오는 이유를 코드 수준에서 이해한다.","minutes":18,"tags":["테스트설계","동등분할","경계값분석","TC"],"order":2,"path":"track-1-fundamentals/02-tc-design-partitioning.md"},{"id":"t1-l03","title":"TC 설계 기법 (2) 상태전이와 결정테이블","summary":"입력 하나만 보면 놓치는 결함을 잡는 두 기법. 순서가 중요한 기능과 조건이 얽힌 기능을 각각 표로 정리한다.","minutes":20,"tags":["테스트설계","상태전이","결정테이블","TC"],"order":3,"path":"track-1-fundamentals/03-tc-design-state-decision.md"},{"id":"t1-l04","title":"TC 설계 기법 (3) 페어와이즈와 조합 폭발 다루기","summary":"조합이 수천 개로 폭발할 때 무엇을 버릴지 근거 있게 정하는 법. PICT로 실제 케이스를 줄여본다.","minutes":18,"tags":["테스트설계","페어와이즈","조합테스트","PICT"],"order":4,"path":"track-1-fundamentals/04-tc-design-pairwise.md"},{"id":"t1-l05","title":"테스트 유형 — 기능·회귀·통합·탐색적","summary":"네 가지 테스트를 언제 어느 깊이로 돌릴지 판단한다. 특히 회귀 범위 산정과 탐색적 테스트의 기록법을 익힌다.","minutes":20,"tags":["기능테스트","회귀테스트","통합테스트","탐색적테스트"],"order":5,"path":"track-1-fundamentals/05-test-types.md"},{"id":"t1-l06","title":"결함 리포트 작성법","summary":"개발자가 되묻지 않는 리포트를 쓴다. 재현 경로, 실제/기대 결과 분리, 심각도와 우선순위 구분까지.","minutes":18,"tags":["결함리포트","버그리포트","심각도","우선순위"],"order":6,"path":"track-1-fundamentals/06-defect-report.md"},{"id":"t1-l07","title":"릴리즈 품질 검증과 Go/No-Go 판단","summary":"배포 전후에 무엇을 확인하고, 어떤 근거로 나가도 된다고 말할 것인가. 롤백 기준까지 미리 정한다.","minutes":20,"tags":["릴리즈","GoNoGo","리스크판단","롤백","모니터링"],"order":7,"path":"track-1-fundamentals/07-release-go-nogo.md"},{"id":"t1-l08","title":"품질 지표 — 커버리지, 결함 밀도, 실패율, 결함 탈출률","summary":"숫자로 품질을 말하는 법. 그리고 지표가 목표가 되는 순간 어떻게 망가지는지까지 함께 배운다.","minutes":20,"tags":["품질지표","커버리지","결함밀도","결함탈출률","DDP"],"order":8,"path":"track-1-fundamentals/08-quality-metrics.md"}]},{"id":"track-2-tools","title":"트랙 2. 도구 실무","shortTitle":"2. 도구 실무","summary":"Jira·Confluence 협업, Postman·Swagger API 테스트, SQL 데이터 정합성 검증, Datadog·Grafana 로그 분석.","outcomes":["API 명세만 보고 Postman 컬렉션을 구성하고 응답을 검증할 수 있다","SQL 로 데이터 정합성을 직접 확인할 수 있다","로그와 대시보드를 읽고 장애 원인의 범위를 좁힐 수 있다"],"lessons":[{"id":"t2-l01","title":"이슈관리와 협업 — Jira · Confluence · Notion · Slack","summary":"티켓 하나가 어떤 흐름을 타는지, JQL로 내 일을 어떻게 찾는지, 그리고 QA가 협업 도구에서 실제로 하는 일.","minutes":18,"tags":["Jira","Confluence","Notion","Slack","JQL","협업"],"order":1,"path":"track-2-tools/01-issue-tracking-collaboration.md"},{"id":"t2-l02","title":"API 테스트 (1) — HTTP 기초와 Postman 응답 검증","summary":"화면 없이 서버를 직접 두드려 본다. 상태코드·헤더·바디를 무엇을 기준으로 검증할지 정하고 Postman 테스트 스크립트로 옮긴다.","minutes":20,"tags":["API테스트","Postman","HTTP","상태코드","Insomnia"],"order":2,"path":"track-2-tools/02-api-testing-postman.md"},{"id":"t2-l03","title":"API 테스트 (2) — Swagger 읽기와 컬렉션 러너·CI 연동","summary":"OpenAPI 명세를 TC의 근거로 삼는 법. 그리고 컬렉션을 Newman으로 CI에서 자동 실행해 리포트를 받는다.","minutes":20,"tags":["Swagger","OpenAPI","Newman","컬렉션러너","CI"],"order":3,"path":"track-2-tools/03-api-testing-swagger-runner.md"},{"id":"t2-l04","title":"SQL (1) — QA를 위한 조회와 JOIN 읽기","summary":"화면 뒤에 실제로 저장된 값을 확인한다. SELECT·WHERE·JOIN을 '검증 도구'로 쓰는 법과 MySQL/MSSQL 차이.","minutes":20,"tags":["SQL","MySQL","MSSQL","DBeaver","데이터검증"],"order":4,"path":"track-2-tools/04-sql-basics-for-qa.md"},{"id":"t2-l05","title":"SQL (2) — 데이터 정합성 검증 쿼리 패턴","summary":"화면으로는 절대 안 보이는 결함을 찾는 6가지 쿼리 패턴. 그리고 테스트 데이터를 안전하게 만드는 법.","minutes":20,"tags":["SQL","데이터정합성","테스트데이터","검증쿼리"],"order":5,"path":"track-2-tools/05-sql-integrity-patterns.md"},{"id":"t2-l06","title":"로그·모니터링 기반 원인 분석 — Datadog · Grafana","summary":"안 돼요\"에서 \"이 요청이 이 시각에 이 이유로 실패했습니다\"까지. 로그를 읽고 대시보드에서 이상을 찾는 법.","minutes":20,"tags":["로그","모니터링","Datadog","Grafana","옵저버빌리티","TraceID"],"order":6,"path":"track-2-tools/06-logs-monitoring.md"}]},{"id":"track-3-automation","title":"트랙 3. 테스트 자동화","shortTitle":"3. 테스트 자동화","summary":"Playwright 를 중심으로 웹·모바일 자동화, 페이지 오브젝트, 플래키 테스트 격리, CI/CD 연동, 그리고 무엇을 자동화하지 않을지 판단하는 기준.","outcomes":["Playwright 로 안정적인 E2E 테스트를 작성하고 CI 에서 돌릴 수 있다","플래키 테스트의 원인을 분류하고 격리할 수 있다","자동화 대상과 수동 유지 대상을 비용 기준으로 나눌 수 있다"],"lessons":[]},{"id":"track-4-ai-qa","title":"트랙 4. AI 활용 QA","shortTitle":"4. AI 활용 QA","summary":"2026년 신규 표준 요구사항. AI 기반 TC 생성, Agentic Testing 4단계, 셀프힐링, 자연어 기반 테스트 파이프라인.","outcomes":["요구사항·PR diff 를 입력으로 테스트를 생성·우선순위화하는 흐름을 설계할 수 있다","에이전트가 탐색·실패분석·자가복구까지 수행하는 구조를 이해하고 실습할 수 있다","셀렉터가 깨졌을 때 자동 보정되는 셀프힐링 로직을 구현할 수 있다"],"lessons":[]},{"id":"track-5-performance","title":"트랙 5. 성능·부하 테스트","shortTitle":"5. 성능 테스트","summary":"k6 로 부하·스트레스·스파이크·내구성 테스트를 구분해 설계하고, p95/p99·에러율·처리량으로 결과를 해석한다.","outcomes":["k6 시나리오를 작성하고 임계치(threshold)를 설정할 수 있다","평균이 아닌 p95/p99 로 성능을 판단할 수 있다"],"lessons":[]},{"id":"track-6-dev-crosscheck","title":"트랙 6. 교차검증을 위한 개발 지식","shortTitle":"6. 개발 교차검증","summary":"AI가 만든 코드와 분석이 맞는지 내가 직접 검증하기 위한 개발 지식. 암기가 아니라 '읽고 판단하기' 관점으로 배운다.","outcomes":["HTTP·인증·비동기 처리를 이해하고 API 동작을 스스로 검증할 수 있다","JS/Python 코드와 PR diff 를 읽고 무엇을 테스트해야 하는지 판단할 수 있다","AI 산출물의 환각과 가짜 통과를 체크리스트로 걸러낼 수 있다"],"lessons":[]}]},"lessons":{"t1-l01":"---\nid: t1-l01\ntitle: 테스트 계획과 테스트 전략 문서\nsummary: 전략과 계획의 차이를 구분하고, 리스크 기반으로 테스트 범위를 정하는 문서를 직접 작성한다.\nminutes: 20\norder: 1\ntags: [테스트계획, 테스트전략, 리스크기반테스팅]\n---\n\n## 개념 설명\n\n### 전략(Strategy)과 계획(Plan)은 다른 문서다\n\n면접에서 자주 걸러지는 지점이다. 두 단어를 섞어 쓰면 \"문서 작성 경험이 없다\"고 읽힌다.\n\n| | 테스트 전략 | 테스트 계획 |\n|---|---|---|\n| 범위 | 조직·제품 전반 | 특정 릴리즈·프로젝트 |\n| 수명 | 오래 유지 (분기~연 단위) | 릴리즈마다 새로 씀 |\n| 답하는 질문 | **어떻게** 테스트하는가 | **이번에 무엇을** 언제 누가 |\n| 예시 내용 | 자동화 대상 기준, 환경 정책, 결함 등급 정의, 릴리즈 기준 | 이번 스프린트 대상 기능, 일정, 담당자, 리스크, 진입/종료 조건 |\n\n전략은 \"우리 팀은 결제 도메인은 항상 회귀 자동화를 돌린다\"이고,\n계획은 \"이번 3.2.0 릴리즈에서는 쿠폰 기능이 추가되므로 결제 회귀 + 쿠폰 신규 TC 42건을 4/8까지 수행한다\"이다.\n\n### 계획의 핵심은 '리스크 기반'이다\n\n시간은 항상 부족하다. 그래서 계획의 본질은 **무엇을 테스트할지가 아니라, 무엇을 테스트하지 않을지 정하고 그 근거를 남기는 것**이다.\n\n리스크 점수를 이렇게 매긴다.\n\n```\n리스크 = 발생 가능성(1~5) × 영향도(1~5)\n```\n\n- **발생 가능성**을 올리는 요인: 이번에 코드가 많이 바뀐 영역, 과거 결함이 잦았던 영역, 복잡한 조건 분기, 새로 합류한 개발자가 만진 영역, 외부 연동\n- **영향도**를 올리는 요인: 돈이 오가는가, 데이터가 유실되는가, 전체 사용자가 막히는가, 법·규제 이슈인가, 되돌릴 수 있는가\n\n점수가 높은 순으로 테스트 깊이를 차등 배분한다. 결제 실패(5×5=25)와 프로필 사진 썸네일 깨짐(3×1=3)에 같은 시간을 쓰면 안 된다.\n\n### 진입 조건과 종료 조건\n\n이 두 가지가 없는 계획서는 \"언제 끝나는지 아무도 모르는 계획\"이다.\n\n**진입 조건 (Entry Criteria)** — 이게 충족돼야 테스트를 시작한다\n- 빌드가 테스트 환경에 배포되어 있고 스모크 테스트를 통과했다\n- 기능 명세가 확정되었다 (또는 변경분이 공유되었다)\n- 테스트 데이터와 계정이 준비되었다\n\n**종료 조건 (Exit Criteria)** — 이게 충족되면 테스트를 끝낸다\n- 계획한 TC 실행률 100%, 통과율 95% 이상\n- Blocker/Critical 결함 0건, Major 결함은 모두 원인 파악 및 릴리즈 판단 완료\n- 회귀 자동화 스위트 통과\n\n숫자를 적는 것이 중요하다. \"충분히 테스트되면\"은 조건이 아니다.\n\n### 테스트 계획서 최소 목차\n\n실무에서 A4 2~3장이면 충분하다. 길면 아무도 안 읽는다.\n\n```text\n1. 대상과 범위        - 이번 릴리즈에 포함되는 기능 / 명시적으로 제외하는 기능\n2. 리스크 분석        - 영역별 리스크 점수와 그에 따른 테스트 깊이\n3. 테스트 유형과 수준  - 기능/통합/회귀/탐색적/성능 중 무엇을 어디까지\n4. 환경과 데이터      - 서버 환경, 단말, 계정, 테스트 데이터 준비 방법\n5. 일정과 담당        - 누가 언제 무엇을\n6. 진입/종료 조건     - 숫자로\n7. 리스크와 대응      - 일정 지연 시 무엇을 먼저 버릴 것인가\n```\n\n7번이 실제로 가장 유용하다. 일정이 밀렸을 때 즉흥적으로 자르지 않고, 미리 합의된 우선순위대로 자를 수 있게 해준다.\n\n## 왜 채용시장이 요구하는가\n\nQA 채용공고의 \"테스트 계획 수립 및 테스트 전략 문서 작성 경험\"은 사실상\n**\"당신은 시키는 대로 TC를 실행하는 사람인가, 아니면 무엇을 테스트할지 스스로 결정하는 사람인가\"**를 묻는 항목이다.\n\n- **주니어와 시니어를 가르는 기준**이라서 묻는다. TC 실행은 신입도 하고 이제는 AI도 한다. 범위를 정하고 근거를 대는 판단은 대체되지 않는다.\n- **AI 시대에 오히려 비중이 커졌다.** AI가 TC를 100건 뽑아주는 상황에서 QA의 일은 \"그중 어떤 30건이 이번 릴리즈에 진짜 필요한가\"를 고르는 것이다. 이 판단의 근거가 리스크 기반 계획이다.\n- **개발·기획과 협상하는 언어**다. \"시간이 부족합니다\" 대신 \"결제 회귀를 빼면 25점짜리 리스크가 열립니다. 대신 프로필 영역 3점짜리를 빼겠습니다\"라고 말할 수 있어야 한다.\n\n면접에서는 보통 이렇게 나온다. *\"릴리즈 3일 전인데 큰 기능이 하나 추가됐습니다. 어떻게 하시겠어요?\"*\n정답은 야근이 아니라 **리스크 재평가 + 범위 재조정 + 판단 근거 공유**다.\n\n## 실습 과제\n\n### 과제 1 — 실제 서비스로 테스트 계획서 쓰기 (15분)\n\n본인이 자주 쓰는 앱이나 웹서비스를 하나 고른다 (배달앱, 은행앱, 쇼핑몰 등).\n그 서비스에 **\"쿠폰 자동 적용\"** 기능이 새로 추가된다고 가정하고, 위 7항목 목차로 A4 1장짜리 계획서를 작성한다.\n\n반드시 포함할 것:\n- 리스크 표에 최소 5개 영역, 각각 점수와 근거\n- **명시적으로 테스트하지 않을 항목 3개와 그 이유**\n- 종료 조건을 숫자로\n\n### 과제 2 — 종료 조건 뒤집어 보기 (5분)\n\n작성한 종료 조건을 보고 스스로 물어본다.\n\n> \"이 조건을 다 만족했는데도 운영에서 큰 장애가 났다면, 무엇이 빠져 있었던 걸까?\"\n\n떠오른 항목을 종료 조건에 한 줄 추가한다. 이 사고 훈련이 결함 탈출률을 줄인다.\n\n### 과제 3 — AI에게 시키고 검증하기 (선택, 10분)\n\n이 페이지 하단의 **AI 실습 도우미**에서 `요구사항 → 테스트 케이스 초안`을 열고, 과제 1의 쿠폰 기능 요구사항을 입력한다.\n결과를 받은 뒤 **직접 채점**한다.\n\n- AI가 리스크 우선순위를 매겼는가, 아니면 모든 항목을 평평하게 나열했는가?\n- \"확인이 필요한 질문\"에 실제로 애매한 부분이 들어갔는가?\n- 내가 쓴 계획서에는 있는데 AI가 놓친 항목은 무엇인가?\n\n대체로 AI는 **범위를 좁히는 판단**을 못 한다. 그게 지금 당신이 학습하는 이유다.\n\n## 자가 체크리스트\n\n- [ ] 테스트 전략과 테스트 계획의 차이를 한 문장씩으로 설명할 수 있다\n- [ ] 리스크 = 발생 가능성 × 영향도 로 영역별 점수를 매길 수 있다\n- [ ] 발생 가능성을 높이는 요인 3가지, 영향도를 높이는 요인 3가지를 댈 수 있다\n- [ ] 진입 조건과 종료 조건을 각각 숫자가 들어간 형태로 쓸 수 있다\n- [ ] 테스트하지 않을 항목을 근거와 함께 명시할 수 있다\n- [ ] 일정이 축소됐을 때 무엇부터 자를지 미리 정해둘 수 있다\n- [ ] \"3일 남았는데 기능이 추가됐다\" 질문에 리스크 언어로 답할 수 있다\n- [ ] 테스트 계획서 7개 항목을 보지 않고 나열할 수 있다\n\n## 참고 링크\n\n- [ISTQB Foundation Level 실러버스 (한국어)](https://www.kstqb.org/) — 테스트 계획·모니터링 챕터. 용어의 표준 정의를 확인할 때\n- [ISO/IEC/IEEE 29119-3 테스트 문서 표준 개요](https://www.iso.org/standard/79429.html) — 실무에서 이대로 다 쓰지는 않지만 목차 참고용\n- [Google Testing Blog](https://testing.googleblog.com/) — 대규모 조직의 테스트 전략 사례\n- [Ministry of Testing — Test Strategy](https://www.ministryoftesting.com/) — 커뮤니티 사례와 템플릿\n","t1-l02":"---\nid: t1-l02\ntitle: TC 설계 기법 (1) 동등분할과 경계값 분석\nsummary: 무한한 입력을 유한한 테스트로 줄이는 두 기본 기법. 경계에서 결함이 나오는 이유를 코드 수준에서 이해한다.\nminutes: 18\norder: 2\ntags: [테스트설계, 동등분할, 경계값분석, TC]\n---\n\n## 개념 설명\n\n### 왜 기법이 필요한가\n\n\"나이 입력 필드\"를 테스트한다고 하자. 입력 가능한 값은 사실상 무한하다.\n아무 값이나 20개 넣어보는 것과, 기법으로 6개를 고르는 것 중 **후자가 결함을 더 많이 찾는다.**\n테스트 설계 기법은 요령이 아니라 **커버리지를 근거로 설명할 수 있게 만드는 도구**다.\n\n### 동등분할 (Equivalence Partitioning)\n\n같은 방식으로 처리될 입력들을 하나의 그룹으로 묶고, **그룹당 대표값 하나만 테스트**한다.\n\n> 요구사항: 나이는 19세 이상 65세 이하만 가입할 수 있다.\n\n| 파티션 | 종류 | 대표값 |\n|---|---|---|\n| 19 미만 | 비유효 | 15 |\n| 19 ~ 65 | 유효 | 30 |\n| 65 초과 | 비유효 | 70 |\n| 숫자가 아님 | 비유효 | `\"abc\"` |\n| 비어 있음 | 비유효 | `\"\"` |\n\n핵심 규칙 두 가지가 있다.\n\n1. **유효 파티션은 한 번에 여러 개를 조합해도 된다.** (통과하는 케이스는 묶어서 확인)\n2. **비유효 파티션은 반드시 한 번에 하나씩 테스트한다.** 두 개를 동시에 위반하면 어느 쪽 검증 로직이 동작한 건지 알 수 없다. 앞선 검증에 가려져 뒤쪽 검증의 버그를 놓치는 현상을 **결함 마스킹(fault masking)** 이라고 한다.\n\n초보가 가장 많이 하는 실수가 2번이다. \"나이 -5, 이메일 형식 오류\"를 한 케이스에 넣으면 안 된다.\n\n### 경계값 분석 (Boundary Value Analysis)\n\n**결함은 파티션 한가운데가 아니라 경계에서 나온다.** 이유는 코드를 보면 자명하다.\n\n```javascript\n// 요구사항: 19세 이상 65세 이하 가입 가능\nfunction canSignUp(age) {\n  return age > 19 && age < 65;   // 버그: >= 와 <= 여야 한다\n}\n```\n\n이 코드는 나이 30을 넣으면 정상 통과한다. **19와 65를 넣어야만 드러난다.**\n`>` 와 `>=`, `<` 와 `<=`, `i < n` 과 `i <= n` 을 헷갈리는 것은 경력과 무관하게 계속 발생한다. 그래서 경계는 항상 본다.\n\n경계값은 두 방식이 있다.\n\n**2-value (경계 ± 1)** — 실무에서 가장 흔하다.\n\n```text\n19세 이상 65세 이하  →  18, 19  /  65, 66\n```\n\n**3-value (경계 앞·경계·경계 뒤)** — 리스크가 큰 영역에서 쓴다.\n\n```text\n19세 이상 65세 이하  →  18, 19, 20  /  64, 65, 66\n```\n\n### 놓치기 쉬운 경계들\n\n숫자 범위만 경계가 아니다. 실무 결함의 상당수가 여기서 나온다.\n\n| 대상 | 경계 후보 |\n|---|---|\n| 문자열 길이 | 0자, 1자, 최대값, 최대값+1 |\n| 목록·페이징 | 0건, 1건, 한 페이지 정확히 채움, +1건 |\n| 날짜 | 월말, 윤년 2/29, 연말연시, 자정 직전·직후 |\n| 시간대 | UTC 자정, 서머타임 전환, KST 09:00 경계 |\n| 금액 | 0원, 최소 결제 금액, 무료 배송 기준선, 최대 한도 |\n| 파일 | 0바이트, 최대 크기, 최대 크기 + 1바이트 |\n| 권한·수량 | 재고 0개, 마지막 1개, 동시 구매 |\n\n특히 **\"정확히 기준선에 걸친 값\"** 이 위험하다. 무료 배송 기준이 30,000원일 때 정확히 30,000원을 주문하면 무료인가 아닌가? 요구사항에 안 적혀 있다면 그건 결함이 아니라 **명세 결함**이고, 개발이 시작되기 전에 물어보는 것이 QA의 일이다.\n\n### 두 기법은 항상 세트로 쓴다\n\n동등분할로 **어디를 볼지** 정하고, 경계값으로 **그 안 어디를 찌를지** 정한다.\n\n> 요구사항: 주문 금액 30,000원 이상이면 배송비 무료, 미만이면 3,000원.\n\n| TC | 입력 | 기법 | 기대 결과 |\n|---|---|---|---|\n| 1 | 29,999 | 경계 −1 | 배송비 3,000원 |\n| 2 | 30,000 | 경계 | 배송비 0원 |\n| 3 | 30,001 | 경계 +1 | 배송비 0원 |\n| 4 | 15,000 | 유효 파티션 대표 | 배송비 3,000원 |\n| 5 | 0 | 경계 (하한) | 주문 불가 |\n| 6 | −1000 | 비유효 | 입력 거부 |\n\n6건이면 이 요구사항은 충분히 덮인다. 무작정 20건 만드는 것보다 낫고, **각 케이스가 왜 존재하는지 설명할 수 있다.** 이 \"설명 가능성\"이 리뷰와 면접에서 결정적이다.\n\n## 왜 채용시장이 요구하는가\n\n- 거의 모든 QA 채용공고에 \"테스트 케이스 설계 기법 이해\"가 들어간다. **면접에서 실제로 손으로 풀린다.** \"이 입력 필드의 TC를 만들어 보세요\"는 단골 문제다.\n- **AI가 만든 TC를 평가하려면 기준이 있어야 한다.** AI에게 TC를 시키면 대체로 유효 케이스는 잘 만들고 경계와 비유효 조합을 빠뜨린다. 기법을 모르면 \"빠졌다\"는 사실 자체를 알아채지 못한다.\n- 자동화 테스트를 짤 때도 같다. 파라미터라이즈 테스트에 넣을 데이터셋을 고르는 근거가 바로 이 두 기법이다.\n\n실제로 AI에게 \"나이 입력 TC 만들어줘\"를 시켜보면 대부분 **19와 65 자체를 빼먹거나**, 넣더라도 `>=` 와 `>` 중 어느 쪽이 맞는지 요구사항에서 확인하지 않고 넘어간다. 그 확인이 사람의 몫이다.\n\n## 실습 과제\n\n### 과제 1 — 비밀번호 규칙 TC 설계 (10분)\n\n> 비밀번호는 8자 이상 20자 이하이며, 영문 대문자·소문자·숫자·특수문자 중 3종류 이상을 포함해야 한다. 공백은 허용하지 않는다.\n\n동등분할 표와 경계값을 적용해 TC를 설계한다. 목표는 **12건 이내**.\n\n체크 포인트:\n- 길이 경계 4개(7, 8, 20, 21)를 넣었는가\n- \"3종류 이상\"의 경계인 **정확히 3종류**와 **2종류**를 구분했는가\n- 공백이 문자열 중간·앞뒤에 있는 경우를 나눴는가\n- 비유효 케이스를 한 번에 하나씩만 위반시켰는가\n\n### 과제 2 — 실습 랩에서 찾아보기 (10분)\n\n실습 랩의 **결함이 숨겨진 샘플 앱** → 로그인 화면에서 위 기법대로 입력해 본다.\n경계값에서만 드러나는 결함이 심어져 있다. 무엇을 찾았고 어떤 기법이 그것을 잡아냈는지 메모에 적는다.\n\n### 과제 3 — AI TC 채점하기 (10분)\n\nAI 실습 도우미에서 과제 1의 요구사항을 그대로 입력해 TC를 생성시킨 뒤, **내가 만든 표와 대조해 채점표를 만든다.**\n\n| 항목 | 내 TC | AI TC |\n|---|---|---|\n| 길이 경계 4개 포함 | | |\n| 종류 수 경계 포함 | | |\n| 비유효 1개씩 분리 | | |\n| 불필요한 중복 케이스 | | |\n| 요구사항에 없는 내용 창작 | | |\n\n마지막 행이 핵심이다. AI는 \"최대 3회 시도 제한\" 같은 **요구사항에 없는 규칙을 자주 지어낸다.** 이것이 환각이고, 그대로 TC로 넘기면 개발자와 싸우게 된다.\n\n## 자가 체크리스트\n\n- [ ] 동등분할의 정의와 목적을 한 문장으로 설명할 수 있다\n- [ ] 비유효 파티션을 한 번에 하나씩만 테스트해야 하는 이유(결함 마스킹)를 설명할 수 있다\n- [ ] 경계값 분석의 2-value 방식과 3-value 방식을 구분해 적용할 수 있다\n- [ ] 경계에서 결함이 나오는 이유를 코드(`>` vs `>=`) 수준에서 설명할 수 있다\n- [ ] 숫자 범위 외의 경계(문자열 길이, 목록 0건, 날짜, 금액 기준선)를 5가지 이상 나열할 수 있다\n- [ ] 요구사항에 경계 처리가 명시되지 않았을 때 명세 결함으로 제기할 수 있다\n- [ ] 하나의 요구사항에 대해 근거를 설명할 수 있는 TC 표를 만들 수 있다\n- [ ] AI가 만든 TC에서 빠진 경계와 창작된 요구사항을 찾아낼 수 있다\n\n## 참고 링크\n\n- [ISTQB Foundation — Test Techniques](https://www.istqb.org/certifications/certified-tester-foundation-level) — 블랙박스 기법의 표준 정의\n- [Software Testing Help — Boundary Value Analysis and Equivalence Partitioning](https://www.softwaretestinghelp.com/what-is-boundary-value-analysis-and-equivalence-partitioning/) — 예제가 풍부하다\n- [Microsoft PICT (페어와이즈 도구)](https://github.com/microsoft/pict) — 다음 레슨에서 다룰 조합 테스트 도구\n","t1-l03":"---\nid: t1-l03\ntitle: TC 설계 기법 (2) 상태전이와 결정테이블\nsummary: 입력 하나만 보면 놓치는 결함을 잡는 두 기법. 순서가 중요한 기능과 조건이 얽힌 기능을 각각 표로 정리한다.\nminutes: 20\norder: 3\ntags: [테스트설계, 상태전이, 결정테이블, TC]\n---\n\n## 개념 설명\n\n앞 레슨의 동등분할·경계값은 **입력 하나**를 보는 기법이다. 그런데 실무 결함의 상당수는 입력 하나만 봐서는 안 보인다.\n\n- \"로그아웃 상태에서 결제 버튼을 누르면?\" → **이전에 무슨 일이 있었는가**가 중요하다 → 상태전이\n- \"VIP 회원이 쿠폰과 포인트를 동시에 쓰면서 5만원 미만을 주문하면?\" → **조건들의 조합**이 중요하다 → 결정테이블\n\n### 상태전이 테스트 (State Transition Testing)\n\n시스템이 여러 **상태**를 오가고, 같은 동작이라도 현재 상태에 따라 결과가 달라질 때 쓴다.\n\n주문 상태를 예로 들자.\n\n```text\n[결제대기] --결제완료--> [결제완료] --발송--> [배송중] --수령--> [배송완료]\n     |                       |                                      |\n   취소                     취소                                  반품신청\n     v                       v                                      v\n  [주문취소]              [결제취소]                            [반품접수]\n```\n\n여기서 만드는 표가 **상태전이표**다.\n\n| 현재 상태 | 이벤트 | 다음 상태 | 비고 |\n|---|---|---|---|\n| 결제대기 | 결제완료 | 결제완료 | 정상 |\n| 결제대기 | 취소 | 주문취소 | 정상 |\n| 결제완료 | 발송 | 배송중 | 정상 |\n| 결제완료 | 취소 | 결제취소 | 환불 처리 동반 |\n| 배송중 | 취소 | **불가** | ← 여기가 핵심 |\n| 배송완료 | 결제완료 | **불가** | ← 여기도 |\n\n**이 기법의 진짜 가치는 \"정상 경로\"가 아니라 \"불가 전이\"에 있다.** 개발자는 정상 흐름은 반드시 구현한다. 버그는 항상 *\"일어나면 안 되는 전이가 실제로는 막혀 있지 않은 곳\"* 에서 나온다.\n\n현실에서 이런 식으로 터진다.\n\n- 배송중인데 취소 API를 직접 호출하면 취소가 된다 (UI 버튼만 숨겨놓고 서버 검증을 안 함)\n- 결제 완료 응답이 늦어 사용자가 결제 버튼을 두 번 누르면 **두 번 결제된다** (같은 상태에서 같은 이벤트가 중복 발생)\n- 뒤로가기로 이전 화면에 돌아가 다시 제출하면 이미 끝난 전이가 또 일어난다\n\n그래서 상태전이 TC를 만들 때 최소한 이 세 가지는 반드시 넣는다.\n\n1. **모든 정상 전이 1회씩** (0-switch 커버리지)\n2. **불가 전이 시도** — UI로 막혀 있어도 **API를 직접 호출해서** 확인해야 진짜 검증이다\n3. **중복 이벤트** — 같은 버튼 연타, 새로고침 후 재제출, 뒤로가기 후 재제출\n\n### 결정테이블 (Decision Table)\n\n여러 조건이 **동시에** 결과에 영향을 줄 때 쓴다. 조건과 결과를 표로 만들어 빠뜨리는 조합이 없게 한다.\n\n> 요구사항: 배송비는 3,000원이다. 주문 금액이 30,000원 이상이면 무료. VIP 회원은 금액과 무관하게 무료. 단, 도서산간 지역은 무료 대상이라도 추가 배송비 3,000원을 받는다.\n\n조건이 3개(금액, 등급, 지역)이므로 조합은 2×2×2 = 8가지다.\n\n| 조건 \\\\ 규칙 | R1 | R2 | R3 | R4 | R5 | R6 | R7 | R8 |\n|---|---|---|---|---|---|---|---|---|\n| 30,000원 이상 | Y | Y | Y | Y | N | N | N | N |\n| VIP 회원 | Y | Y | N | N | Y | Y | N | N |\n| 도서산간 | Y | N | Y | N | Y | N | Y | N |\n| **배송비** | 3,000 | 0 | 3,000 | 0 | 3,000 | 0 | 6,000 | 3,000 |\n\n표를 다 채우고 나면 세 가지가 보인다.\n\n1. **R7이 이상하다.** 일반 회원 + 3만원 미만 + 도서산간 = 기본 3,000 + 추가 3,000 = 6,000원이 맞는가? 요구사항에는 \"무료 대상이라도 추가 3,000원\"이라고만 적혀 있어 **유료 배송인 경우에 추가금이 붙는지가 명시돼 있지 않다.** → 이건 결함이 아니라 **명세 결함**이고, 개발 전에 물어봐야 한다.\n2. **R1과 R3이 같은 결과다.** 도서산간이면 등급이 무의미해진다 → 로직 단순화 여지\n3. 조합 8개를 다 적었기 때문에 **\"이건 생각 못 했네\"가 사라진다.** 이게 결정테이블의 목적이다.\n\n조건이 늘면 조합은 2ⁿ으로 폭증한다. 조건 6개면 64가지다. 그럴 때는 다음 레슨의 **페어와이즈**로 줄이거나, 결과가 같은 규칙들을 묶어(`—` = 무관) 압축한다.\n\n| 조건 | R1 | R2 | R3 |\n|---|---|---|---|\n| 도서산간 | Y | N | N |\n| 무료 대상(30,000↑ 또는 VIP) | — | Y | N |\n| **배송비** | 기본 + 3,000 | 0 | 3,000 |\n\n8줄이 3줄이 됐다. 실무에서는 이렇게 압축한 표를 쓰되, **압축 전 전체 표를 한 번은 그려봐야** 빠진 조합을 발견할 수 있다.\n\n### 두 기법을 언제 고르는가\n\n| 상황 | 기법 |\n|---|---|\n| 순서·이력이 결과를 바꾼다 (주문, 결제, 로그인 세션, 승인 워크플로) | 상태전이 |\n| 여러 조건이 동시에 결과를 정한다 (요금 계산, 권한, 할인, 노출 조건) | 결정테이블 |\n| 둘 다 해당된다 (예: 등급별로 취소 가능 상태가 다름) | 상태전이표의 각 칸 안에 결정테이블 |\n\n## 왜 채용시장이 요구하는가\n\n- **면접 실기 단골**이다. \"주문 취소 기능의 TC를 설계해 보세요\"는 상태전이를 쓰는지 보는 문제고, \"할인 정책 TC를 만들어 보세요\"는 결정테이블을 쓰는지 보는 문제다. 기법 이름을 말하지 않고 나열식으로 답하면 바로 티가 난다.\n- **명세 결함을 잡아내는 도구**라서 값이 크다. 위 R7처럼 표를 채우다 보면 \"요구사항에 이 경우가 없는데요?\"가 자동으로 나온다. **개발 전에 발견한 결함이 가장 싸다.** QA를 테스터가 아니라 품질 엔지니어로 보게 만드는 지점이다.\n- **AI 생성 TC의 가장 큰 구멍이 여기다.** AI에게 할인 정책 TC를 시키면 대체로 조건을 하나씩 따로 테스트하는 케이스를 만들고, **조합을 빠뜨린다.** 상태전이는 더 심해서 \"불가 전이\"를 거의 만들지 않는다. 표를 그릴 줄 알아야 무엇이 빠졌는지 보인다.\n\n## 실습 과제\n\n### 과제 1 — 로그인 상태전이표 (12분)\n\n아래 요구사항으로 상태전이표를 작성한다.\n\n> 로그인은 이메일·비밀번호로 한다. 비밀번호를 5회 연속 틀리면 계정이 10분간 잠긴다. 잠금 중에는 올바른 비밀번호를 넣어도 로그인되지 않는다. 10분이 지나면 자동 해제된다. 로그인 성공 시 실패 횟수는 초기화된다.\n\n상태: `미인증` / `실패누적(1~4회)` / `잠금` / `인증됨`\n\n반드시 포함할 것:\n- **불가 전이 3개 이상** (예: 잠금 상태에서 올바른 비밀번호)\n- **경계**: 4회 실패 후 성공 / 5회째 실패 / 잠금 후 9분 59초 / 10분 1초\n- **중복 이벤트**: 로그인 버튼 연타\n\n### 과제 2 — 결정테이블 채우고 명세 결함 찾기 (12분)\n\n> 무료 반품 조건: 수령 후 7일 이내이고, 상품을 개봉하지 않았으며, 단순 변심이 아닌 경우 무료. 단순 변심이면 반품비 5,000원. 상품 하자면 개봉했어도 무료.\n\n조건 4개(7일 이내 / 개봉 여부 / 단순 변심 / 하자)로 전체 조합 표를 그린다.\n\n목표는 TC를 만드는 게 아니라 **\"요구사항만으로는 결과를 정할 수 없는 조합\"을 찾아내는 것**이다. 최소 2개는 나온다. 찾았으면 기획자에게 보낼 질문 문장으로 정리해 메모에 적는다.\n\n### 과제 3 — AI에게 시키고 표로 채점 (10분)\n\nAI 실습 도우미에서 과제 1의 로그인 요구사항으로 TC를 생성시킨 뒤, **내 상태전이표와 대조**한다.\n\n| 확인 항목 | AI |\n|---|---|\n| 불가 전이를 테스트했는가 | |\n| API 직접 호출로 검증하라고 했는가 | |\n| 잠금 시간 경계(9:59 / 10:01)를 넣었는가 | |\n| 로그인 성공 시 카운터 초기화를 확인했는가 | |\n| 요구사항에 없는 규칙을 지어냈는가 | |\n\n경험상 마지막 두 항목에서 갈린다. AI는 \"카운터 초기화\"처럼 **명시돼 있지만 눈에 안 띄는 문장**을 자주 흘린다.\n\n## 자가 체크리스트\n\n- [ ] 상태전이 기법을 언제 쓰는지, 결정테이블을 언제 쓰는지 구분해 설명할 수 있다\n- [ ] 상태전이표에서 가장 결함이 많이 나오는 칸이 \"불가 전이\"인 이유를 설명할 수 있다\n- [ ] UI로 막힌 불가 전이를 API 직접 호출로 검증해야 하는 이유를 설명할 수 있다\n- [ ] 중복 이벤트(연타·재제출·뒤로가기)를 상태전이 TC에 포함시킬 수 있다\n- [ ] 조건 n개짜리 결정테이블의 전체 조합 수가 2ⁿ임을 알고 표를 끝까지 채울 수 있다\n- [ ] 결정테이블을 채우다 발견한 빈칸을 명세 결함으로 제기할 수 있다\n- [ ] `—`(무관) 표기로 규칙을 압축하되, 압축 전 전체 표를 먼저 그려야 하는 이유를 안다\n- [ ] AI가 만든 TC에서 빠진 조합과 빠진 불가 전이를 찾아낼 수 있다\n\n## 참고 링크\n\n- [ISTQB Foundation — State Transition Testing](https://www.istqb.org/certifications/certified-tester-foundation-level) — 0-switch / 1-switch 커버리지의 표준 정의\n- [Decision Table Testing 개요 (Software Testing Help)](https://www.softwaretestinghelp.com/decision-table-testing/) — 압축 규칙 예제\n- [Martin Fowler — State Machine](https://martinfowler.com/bliki/) — 개발자가 상태를 어떻게 구현하는지 이해하면 어디가 깨지는지 보인다\n","t1-l04":"---\nid: t1-l04\ntitle: TC 설계 기법 (3) 페어와이즈와 조합 폭발 다루기\nsummary: 조합이 수천 개로 폭발할 때 무엇을 버릴지 근거 있게 정하는 법. PICT로 실제 케이스를 줄여본다.\nminutes: 18\norder: 4\ntags: [테스트설계, 페어와이즈, 조합테스트, PICT]\n---\n\n## 개념 설명\n\n### 조합은 금방 폭발한다\n\n쇼핑몰 결제 화면 하나를 생각해 보자.\n\n| 변수 | 값 | 개수 |\n|---|---|---|\n| 결제수단 | 카드 / 계좌이체 / 간편결제 / 포인트전액 | 4 |\n| 회원등급 | 일반 / VIP / 휴면 | 3 |\n| 쿠폰 | 없음 / 정액 / 정률 | 3 |\n| 배송지 | 국내 / 도서산간 | 2 |\n| 기기 | PC / 모바일웹 / 앱 | 3 |\n\n전체 조합은 4 × 3 × 3 × 2 × 3 = **216가지**다. 변수 하나만 더 늘어도 수백 개가 된다. 다 못 한다.\n\n여기서 초보와 경력자가 갈린다.\n\n- 초보: \"다 못 하니까 적당히 20개쯤 골라서 하겠습니다\" → **근거가 없다.** 무엇이 빠졌는지 설명할 수 없다\n- 경력자: \"페어와이즈로 줄이면 20개 남습니다. 대신 결제수단×쿠폰 3-way 조합은 리스크가 커서 별도로 9개 더 넣겠습니다\" → **버린 것과 남긴 것에 근거가 있다**\n\n### 페어와이즈의 근거\n\n경험적으로 **결함의 대부분은 변수 1개 또는 2개의 조합에서 발생한다.** 변수 4개, 5개가 동시에 특정 값이어야만 터지는 결함은 훨씬 드물다.\n\n그래서 이런 전략을 쓴다.\n\n> **모든 조합**을 만들지 말고, **모든 \"두 변수 값 쌍\"이 최소 한 번씩 등장**하도록 케이스를 고른다.\n\n위 예에서 `결제수단=간편결제 & 쿠폰=정률` 이라는 쌍이 어떤 케이스에든 한 번은 들어가면 된다. 그 케이스에 회원등급이 무엇이었는지는 상관하지 않는다.\n\n이렇게 하면 216가지가 **20개 안팎**으로 줄어든다. 그러면서 모든 2개 조합은 다 덮는다.\n\n```text\n전체 조합 (all-combinations)  216개  — 커버리지 100%, 현실성 0%\n페어와이즈 (2-way)             ~20개  — 2변수 조합 100%, 3변수 이상은 일부\n단일 값만 훑기 (each-choice)    4개   — 각 값 1회씩만, 조합 결함 거의 못 잡음\n```\n\n### 손으로 만들지 말고 도구를 쓴다\n\n페어와이즈 조합표를 손으로 짜는 것은 시간 낭비이고 실수가 난다. 무료 도구를 쓴다.\n\n**Microsoft PICT** — 가장 널리 쓰이고 무료다. 입력 파일이 단순하다.\n\n```text\n결제수단: 카드, 계좌이체, 간편결제, 포인트전액\n회원등급: 일반, VIP, 휴면\n쿠폰: 없음, 정액, 정률\n배송지: 국내, 도서산간\n기기: PC, 모바일웹, 앱\n```\n\n```bash\npict model.txt > cases.tsv\n```\n\n**제약조건(constraint)이 진짜 실무 기능이다.** 현실에는 불가능한 조합이 있다.\n\n```text\n# 휴면 회원은 쿠폰을 쓸 수 없다\nIF [회원등급] = \"휴면\" THEN [쿠폰] = \"없음\";\n\n# 포인트 전액 결제에는 쿠폰을 중복 적용할 수 없다\nIF [결제수단] = \"포인트전액\" THEN [쿠폰] = \"없음\";\n\n# 앱에서는 계좌이체를 지원하지 않는다\nIF [기기] = \"앱\" THEN [결제수단] <> \"계좌이체\";\n```\n\n제약을 넣지 않으면 **애초에 발생할 수 없는 케이스를 테스트하느라 시간을 버린다.** 실행해 보고 \"이건 원래 안 되는 건데요\"라는 답을 듣는 TC가 그것이다.\n\n반대로 **제약조건을 적는 과정 자체가 요구사항 검증**이다. \"휴면 회원이 쿠폰을 쓰면 어떻게 되나요?\"를 기획자에게 물어야 제약을 적을 수 있기 때문이다.\n\n### 페어와이즈로 부족한 경우\n\n무조건 2-way가 정답은 아니다. 다음은 조합을 더 채워야 한다.\n\n- **돈이 걸린 핵심 조합** — 결제수단 × 쿠폰 × 금액은 3-way로 올린다 (`pict model.txt /o:3`)\n- **과거에 결함이 났던 조합** — 장애 이력에 있던 조합은 무조건 명시적으로 포함시킨다\n- **비즈니스상 가장 흔한 경로** — 실제 사용자의 80%가 지나는 조합은 페어와이즈 결과에 없더라도 따로 넣는다\n\nPICT는 특정 케이스를 반드시 포함시키는 시드(seed) 기능을 지원한다. 위 세 가지를 시드로 고정하고 나머지를 페어와이즈로 채우는 것이 실무적으로 가장 균형이 좋다.\n\n### 자동화와의 관계\n\n페어와이즈 결과표는 그대로 **자동화 테스트의 데이터셋**이 된다.\n\n```javascript\n// Playwright — 조합표를 그대로 파라미터라이즈 테스트로\nconst cases = [\n  { 결제수단: '카드',     회원등급: '일반', 쿠폰: '정률', 배송지: '도서산간', 기기: 'PC' },\n  { 결제수단: '간편결제', 회원등급: 'VIP',  쿠폰: '없음', 배송지: '국내',     기기: '앱' },\n  // ... PICT 출력 20건\n];\n\nfor (const c of cases) {\n  test(`결제 ${c.결제수단}/${c.회원등급}/${c.쿠폰}/${c.배송지}/${c.기기}`, async ({ page }) => {\n    // ...\n  });\n}\n```\n\n테스트 이름에 조합을 그대로 넣는 것이 중요하다. CI에서 실패했을 때 **어떤 조합이 깨졌는지 로그를 안 봐도 알 수 있다.**\n\n## 왜 채용시장이 요구하는가\n\n- 채용공고의 \"테스트 케이스 설계 기법\" 목록에 페어와이즈가 들어가 있으면, **조합 폭발을 겪어본 규모의 서비스**라는 뜻이다. 이 기법을 아는 것 자체가 필터를 통과하는 조건이 된다.\n- **\"시간이 없어서 못 했다\"를 \"이 근거로 줄였다\"로 바꾸는 기술**이다. 앞선 레슨의 리스크 기반 계획과 짝을 이룬다. 조합을 줄인 근거를 문서로 남길 수 있는 사람은 릴리즈 회의에서 발언권이 생긴다.\n- **AI 시대에 특히 중요해졌다.** AI에게 \"가능한 모든 조합의 TC를 만들어줘\"라고 하면 정말 200개를 만들어 준다. 그리고 그 200개는 아무도 실행하지 않는다. **줄이는 판단이 사람의 일**이고, 그 판단 기준이 페어와이즈와 리스크다.\n\n## 실습 과제\n\n### 과제 1 — PICT 모델 작성하고 돌려보기 (15분)\n\nPICT는 무료다. macOS/Linux에서는 소스 빌드, Windows는 바이너리를 받는다.\n설치가 번거로우면 웹 기반 페어와이즈 생성기를 써도 되고, 아래 과제는 **모델 파일을 작성하는 것 자체가 핵심**이라 도구 없이 표만 그려도 된다.\n\n본인이 자주 쓰는 서비스의 **검색 필터 화면**을 하나 골라 모델을 만든다. (예: 숙소 예약의 지역·인원·날짜·가격대·편의시설·정렬)\n\n반드시 포함할 것:\n- 변수 5개 이상, 각 변수의 값 2~4개\n- **제약조건 3개 이상** — 그리고 각 제약을 왜 넣었는지 한 줄 근거\n- 전체 조합 수와 페어와이즈 후 케이스 수를 비교해 적기\n\n### 과제 2 — 제약조건에서 질문 뽑기 (7분)\n\n과제 1에서 제약조건을 적다 보면 **\"이 조합은 되는 건가?\"** 하고 확신이 안 서는 게 반드시 나온다.\n그것들을 모아 기획자에게 보낼 질문 목록으로 정리한다.\n\n> 예) \"인원 10명 이상 + 원룸 타입\" 조합이 검색 결과에 나와야 하나요, 아니면 결과 0건이 정상인가요?\n\n이 목록이 **개발 전에 잡는 결함**이다.\n\n### 과제 3 — AI에게 조합을 줄이게 시키기 (10분)\n\nAI 실습 도우미에 과제 1의 변수 목록을 그대로 주고 이렇게 요청한다.\n\n> 이 변수들로 페어와이즈(2-way) 조합표를 만들어라. 전체 조합 수와 줄인 후 케이스 수를 먼저 계산해서 밝히고, 모든 2변수 쌍이 커버되는지 검증 방법도 함께 제시하라.\n\n그리고 **직접 검증한다.**\n\n- AI가 만든 표에서 무작위로 2변수 쌍 5개를 골라 실제로 표에 존재하는지 확인\n- 케이스 수가 이론값(가장 값이 많은 두 변수의 곱 이상)보다 적으면 **커버가 안 된 것이다**\n- 제약조건을 위반하는 케이스가 섞여 있지 않은지 확인\n\n**AI는 페어와이즈 조합표를 자주 틀린다.** 그럴듯한 표를 만들지만 실제로는 빠진 쌍이 있다. 이 검증 습관이 트랙 6의 핵심이다.\n\n## 자가 체크리스트\n\n- [ ] 변수와 값의 개수만 보고 전체 조합 수를 계산할 수 있다\n- [ ] 페어와이즈가 성립하는 경험적 근거(결함 대부분이 1~2개 변수에서 발생)를 설명할 수 있다\n- [ ] 페어와이즈로 덮이지 않는 것이 무엇인지(3-way 이상 조합) 명확히 말할 수 있다\n- [ ] PICT 모델 파일 문법으로 변수와 제약조건을 작성할 수 있다\n- [ ] 제약조건을 적는 과정에서 명세의 빈칸을 발견해 질문으로 만들 수 있다\n- [ ] 페어와이즈 결과에 반드시 추가해야 할 3가지(핵심 3-way, 장애 이력 조합, 최다 사용 경로)를 안다\n- [ ] 조합표를 자동화 테스트의 파라미터라이즈 데이터셋으로 전환할 수 있다\n- [ ] AI가 만든 페어와이즈 표에서 빠진 쌍을 직접 검증할 수 있다\n\n## 참고 링크\n\n- [Microsoft PICT (GitHub)](https://github.com/microsoft/pict) — 무료 조합 생성 도구. `doc/pict.md` 에 제약조건 문법이 정리돼 있다\n- [Pairwise Testing 공식 사이트](https://www.pairwise.org/) — 조합 테스트 이론과 도구 목록\n- [NIST — Combinatorial Testing](https://csrc.nist.gov/projects/automated-combinatorial-testing-for-software) — \"결함의 대부분이 1~2개 변수에서 발생한다\"는 주장의 실증 연구\n","t1-l05":"---\nid: t1-l05\ntitle: 테스트 유형 — 기능·회귀·통합·탐색적\nsummary: 네 가지 테스트를 언제 어느 깊이로 돌릴지 판단한다. 특히 회귀 범위 산정과 탐색적 테스트의 기록법을 익힌다.\nminutes: 20\norder: 5\ntags: [기능테스트, 회귀테스트, 통합테스트, 탐색적테스트]\n---\n\n## 개념 설명\n\n테스트 유형을 외우는 건 의미 없다. 실무에서 필요한 건 **\"이번 릴리즈에 이 네 가지를 각각 어느 깊이로 돌릴 것인가\"** 를 정하는 판단이다.\n\n### 기능 테스트 (Functional Test)\n\n이번에 만든 기능이 명세대로 동작하는지 본다. 앞 레슨들의 TC 설계 기법이 그대로 적용되는 영역이다.\n\n주의할 점 하나. **기능 테스트는 \"이 기능이 되는가\"만 보는 게 아니라 \"되면 안 되는 것이 안 되는가\"도 본다.**\n\n| 관점 | 예시 |\n|---|---|\n| 긍정 (positive) | 올바른 쿠폰 코드를 넣으면 할인이 적용된다 |\n| 부정 (negative) | 만료된 쿠폰, 남의 쿠폰, 이미 쓴 쿠폰은 거부된다 |\n| 권한 | 다른 사용자의 주문번호로 조회하면 막힌다 |\n| 데이터 | 할인 적용 후 DB의 최종 결제금액이 화면과 일치한다 |\n\n마지막 행이 자주 빠진다. 화면에 9,000원이라고 떠도 DB에 10,000원이 저장됐다면 결함이다. **화면만 보는 테스트는 절반짜리다.** (트랙 2의 SQL 검증으로 이어진다)\n\n### 회귀 테스트 (Regression Test)\n\n**\"이번에 건드린 것 때문에, 원래 잘 되던 게 깨지지 않았는가\"** 를 본다. QA 시간의 가장 큰 덩어리를 잡아먹는 영역이고, 그래서 자동화 1순위다.\n\n가장 어려운 건 **범위 산정**이다. 전부 돌리면 시간이 없고, 적게 돌리면 사고가 난다. 판단 기준은 이렇다.\n\n| 근거 | 방법 |\n|---|---|\n| **코드 변경 범위** | PR diff에서 어떤 모듈이 바뀌었는지 본다. 공통 모듈(인증, 결제, 공통 컴포넌트)이 바뀌었으면 범위를 크게 잡는다 |\n| **의존 관계** | 바뀐 모듈을 호출하는 곳을 역추적한다. 개발자에게 \"이거 어디서 쓰나요\"를 묻는 게 가장 빠르다 |\n| **과거 결함 이력** | 같은 영역에서 결함이 반복됐다면 그 영역은 항상 포함 |\n| **비즈니스 임팩트** | 결제·로그인·주문은 변경이 없어도 매 릴리즈 스모크 수준으로는 돌린다 |\n\n여기서 나오는 실무 개념 두 가지.\n\n- **스모크 테스트(Smoke Test)** — 빌드가 테스트할 가치가 있는지 5~10분 만에 확인하는 최소 세트. 로그인 되나, 메인 뜨나, 주문 한 건 되나. **깨졌으면 QA를 시작하지 않고 빌드를 반려한다.** 이걸 안 하면 반나절 테스트하고 나서 \"빌드가 잘못 올라갔었다\"는 말을 듣게 된다\n- **새니티 테스트(Sanity Test)** — 특정 결함을 수정한 뒤, 그 부분과 주변만 좁고 깊게 확인하는 것\n\n**\"PR diff를 읽고 회귀 범위를 정한다\"** 는 2026년 QA 채용의 핵심 역량이고, 트랙 4의 Agentic Testing이 자동화하려는 바로 그 판단이다. 그래서 트랙 6에서 diff 읽는 법을 따로 배운다.\n\n### 통합 테스트 (Integration Test)\n\n각 부분은 되는데 **붙이면 안 되는** 문제를 찾는다. 실무 결함이 가장 많이 나오는 곳이 여기다.\n\n| 통합 지점 | 자주 나오는 결함 |\n|---|---|\n| 프론트 ↔ 백엔드 | 필드명 불일치(`userName` vs `user_name`), 타입 불일치(숫자를 문자열로), null 처리 |\n| 서비스 ↔ 외부 API | 타임아웃 시 동작, 응답 지연, 에러 코드 매핑, 재시도로 인한 중복 처리 |\n| 앱 ↔ 서버 버전 | 구버전 앱이 신규 API를 호출할 때 (강제 업데이트 정책) |\n| 서비스 ↔ DB | 트랜잭션 롤백, 동시 수정, 캐시와 DB 불일치 |\n\n통합 테스트에서 **반드시 봐야 할 것은 \"정상 응답\"이 아니라 \"비정상 응답\"** 이다.\n\n- 외부 결제사가 **타임아웃**되면 우리 주문은 어떤 상태로 남는가\n- 외부 API가 **500**을 주면 사용자에게 뭐라고 보여주는가\n- 응답이 **늦게 도착**해서 사용자가 이미 화면을 떠났다면?\n\n이걸 테스트하려면 외부 응답을 인위적으로 만들어야 한다. Postman의 목 서버, 프록시 도구, 또는 개발팀에 스텁 환경을 요청한다. (트랙 2에서 다룬다)\n\n### 탐색적 테스트 (Exploratory Test)\n\nTC 없이 **설계·실행·학습을 동시에** 하는 테스트다. \"그냥 막 눌러보는 것\"이 아니다. 그건 애드혹(ad-hoc)이고, 탐색적 테스트는 **기록이 남는 구조화된 활동**이다.\n\n실무에서 쓰는 방식이 **세션 기반 탐색적 테스트(SBTM)** 다.\n\n```text\n세션 시간: 60분 (타이머 켜고)\n차터(Charter): 무엇을 어떤 관점으로 탐색할지 한 문장\n  예) \"쿠폰 적용 화면을 '동시성' 관점으로 탐색해, 중복 적용이 가능한 경로를 찾는다\"\n\n기록:\n  - 발견 (finding): 결함 후보\n  - 질문 (question): 기획/개발에 물어볼 것\n  - 아이디어 (idea): 다음에 TC로 만들 것\n  - 소요 (setup/test/bug 비율)\n```\n\n차터가 없으면 익숙한 경로만 반복하게 된다. **차터는 \"어디를\"이 아니라 \"어떤 관점으로\"를 정하는 것**이 핵심이다. 관점 예시:\n\n| 관점 | 던지는 질문 |\n|---|---|\n| 동시성 | 두 탭에서 동시에 하면? 버튼 연타하면? |\n| 중단 | 중간에 새로고침하면? 뒤로가기하면? 네트워크를 끊으면? |\n| 극단값 | 아주 긴 문자열, 이모지, 0개, 999개 |\n| 시간 | 세션 만료 직전에 제출하면? 자정을 넘기면? |\n| 권한 | 로그아웃 상태로 URL 직접 접근하면? 남의 ID로 바꾸면? |\n| 데이터 오염 | 이전 사용자의 데이터가 남아 보이는가? |\n\n**탐색적 테스트는 자동화가 대체하지 못하는 유일한 영역**이다. 자동화는 \"내가 예상한 것\"만 확인한다. 예상하지 못한 것을 찾는 건 사람(과 트랙 4의 탐색형 에이전트)의 몫이다.\n\n### 네 유형의 배분\n\n리스크와 남은 시간에 따라 비율이 달라진다. 참고용 기준선.\n\n| 상황 | 기능 | 회귀 | 통합 | 탐색적 |\n|---|---|---|---|---|\n| 신규 기능 큰 릴리즈 | 40% | 25% | 20% | 15% |\n| 버그 픽스 위주 릴리즈 | 15% | 55% | 10% | 20% |\n| 외부 연동 추가 | 25% | 20% | 40% | 15% |\n| 리팩터링만 (기능 변경 없음) | 5% | 80% | 10% | 5% |\n\n마지막 행이 중요하다. **\"기능 변경이 없으니 테스트 안 해도 되죠?\"에 대한 답은 \"아니오, 오히려 회귀를 제일 크게 돌려야 합니다\"** 다.\n\n## 왜 채용시장이 요구하는가\n\n- 채용공고에 \"기능/회귀/통합 테스트 수행 경험\"이 거의 빠지지 않는다. 하지만 진짜 평가 포인트는 수행 경험이 아니라 **범위를 정한 경험**이다. 면접에서 \"회귀 범위는 어떻게 정하셨어요?\"가 나오면 그 답으로 등급이 갈린다.\n- **탐색적 테스트를 기록으로 남길 줄 아는 사람이 드물다.** SBTM 차터와 세션 노트를 쓸 줄 알면 \"감으로 테스트하는 사람\"이 아니라 \"재현 가능한 방법론을 쓰는 사람\"으로 보인다.\n- **AI/자동화 시대에 인간 QA의 몫이 탐색적 테스트로 이동하고 있다.** 반복 확인은 자동화가 가져가고, 사람은 \"무엇이 잘못될 수 있는가\"를 상상하는 일을 한다. 이 능력이 채용에서 점점 더 비싸진다.\n\n## 실습 과제\n\n### 과제 1 — 회귀 범위 산정 (12분)\n\n아래 상황에서 회귀 테스트 범위를 정하고 근거를 적는다.\n\n> 이번 릴리즈 변경사항: (1) 로그인 세션 유지 시간을 30분 → 2시간으로 변경, (2) 상품 목록 API에 페이징 파라미터 추가, (3) 공통 날짜 포맷 유틸 함수 수정\n\n각 변경에 대해:\n- 직접 영향 영역 / 간접 영향 영역을 나눠 적기\n- **(3)번이 가장 위험한 이유**를 설명하기\n- 시간이 절반밖에 없다면 무엇부터 버릴지 순서 정하기\n\n### 과제 2 — 탐색적 테스트 세션 실행 (20분)\n\n실습 랩의 **결함이 숨겨진 샘플 앱**에서 30분 타이머를 켜고 SBTM 세션을 진행한다.\n\n차터는 아래 중 하나를 고른다.\n- \"장바구니를 '동시성' 관점으로 탐색해, 수량·금액이 어긋나는 경로를 찾는다\"\n- \"로그인을 '중단' 관점으로 탐색해, 중간에 끊었을 때 상태가 꼬이는 경로를 찾는다\"\n\n세션 노트를 이 레슨의 **내 메모**에 남긴다. 형식:\n\n```text\n차터:\n발견:\n  - F1) ...\n질문:\n  - Q1) ...\n아이디어(다음에 TC로):\n  - I1) ...\n시간 배분: setup __분 / test __분 / bug 기록 __분\n```\n\n### 과제 3 — 통합 실패 시나리오 만들기 (10분)\n\n본인이 아는 서비스 하나를 골라 **외부 연동 실패 시나리오 5개**를 적는다.\n\n| # | 실패 상황 | 사용자에게 보여야 할 것 | 데이터는 어떻게 남아야 하나 |\n|---|---|---|---|\n| 1 | 결제사 타임아웃 (10초 초과) | | |\n| 2 | 결제 성공했는데 우리 서버 저장 실패 | | |\n| 3 | ... | | |\n\n2번이 실무에서 가장 무서운 케이스다. **돈은 빠져나갔는데 주문이 없는 상태**를 어떻게 감지하고 복구할 것인가 — 이 질문을 던질 수 있으면 이미 시니어 관점이다.\n\n## 자가 체크리스트\n\n- [ ] 기능 테스트에서 긍정·부정·권한·데이터 4가지 관점을 모두 적용할 수 있다\n- [ ] 화면 결과만이 아니라 저장된 데이터까지 확인해야 하는 이유를 설명할 수 있다\n- [ ] 회귀 범위를 코드 변경·의존관계·결함이력·임팩트 4가지 근거로 산정할 수 있다\n- [ ] 스모크 테스트와 새니티 테스트를 구분하고, 스모크 실패 시 빌드를 반려할 수 있다\n- [ ] 통합 테스트에서 정상 응답보다 비정상 응답(타임아웃·5xx·지연)을 중시하는 이유를 안다\n- [ ] \"결제는 성공했는데 우리 DB 저장이 실패한\" 상황의 위험을 설명할 수 있다\n- [ ] 탐색적 테스트와 애드혹 테스트의 차이를 차터·기록 유무로 설명할 수 있다\n- [ ] SBTM 차터를 \"어떤 관점으로\"의 형태로 쓸 수 있고, 관점 6가지 이상을 나열할 수 있다\n- [ ] 리팩터링만 있는 릴리즈에서 회귀를 가장 크게 잡아야 하는 이유를 설명할 수 있다\n\n## 참고 링크\n\n- [Session-Based Test Management (Jonathan Bach)](https://www.satisfice.com/download/session-based-test-management) — SBTM 원문. 차터와 세션 노트 형식의 출처\n- [James Bach — Exploratory Testing](https://www.satisfice.com/exploratory-testing) — 탐색적 테스트의 정의와 오해 정리\n- [Google Testing Blog — Test Sizes](https://testing.googleblog.com/2010/12/test-sizes.html) — 통합 테스트의 범위를 어떻게 나눌 것인가\n- [Martin Fowler — Testing Strategies in a Microservice Architecture](https://martinfowler.com/articles/microservice-testing/) — 통합 지점이 많을 때의 전략\n","t1-l06":"---\nid: t1-l06\ntitle: 결함 리포트 작성법\nsummary: 개발자가 되묻지 않는 리포트를 쓴다. 재현 경로, 실제/기대 결과 분리, 심각도와 우선순위 구분까지.\nminutes: 18\norder: 6\ntags: [결함리포트, 버그리포트, 심각도, 우선순위]\n---\n\n## 개념 설명\n\n결함 리포트는 QA가 가장 많이 쓰는 문서이고, **QA의 실력이 가장 빨리 드러나는 문서**다. 개발자는 리포트 제목만 보고도 그 QA의 수준을 안다.\n\n### 나쁜 리포트와 좋은 리포트\n\n```text\n[나쁨] 결제가 안 됨\n[나쁨] 장바구니 오류\n[나쁨] 화면이 이상해요\n```\n\n이 제목들의 공통 문제는 **개발자가 무엇부터 봐야 할지 알 수 없다**는 것이다. 이슈 목록에서 이런 제목 20개가 나열되면 우선순위를 매길 수 없다.\n\n```text\n[좋음] [결제] 쿠폰 적용 후 수량을 변경하면 할인이 중복 적용되어 결제금액이 음수가 된다\n[좋음] [로그인] 계정 잠금 10분 경과 후에도 잠금이 해제되지 않는다 (재로그인 시도 시에만 해제됨)\n[좋음] [상품목록] iOS 앱에서 페이지 2 이후 스크롤 시 1페이지 상품이 중복 표시된다\n```\n\n좋은 제목의 공식은 이렇다.\n\n```text\n[영향 영역] {어떤 조건에서} {무엇이} {어떻게 잘못되는가}\n```\n\n### 필수 항목과 그 이유\n\n| 항목 | 왜 필요한가 | 흔한 실수 |\n|---|---|---|\n| **제목** | 목록에서 우선순위를 판단하는 유일한 정보 | 증상만 적고 조건을 뺌 |\n| **환경** | 재현 여부가 환경에 좌우된다 | \"모바일\"만 적음 → OS/버전/기기/앱버전/서버환경까지 |\n| **재현 절차** | 개발자가 그대로 따라 할 수 있어야 한다 | 한 단계에 여러 동작을 뭉침 |\n| **실제 결과** | 무엇이 일어났는가 | 기대 결과와 섞어서 서술 |\n| **기대 결과** | 왜 그것이 결함인가의 근거 | 생략함 ← 가장 치명적 |\n| **재현율** | 간헐적이면 접근이 완전히 달라진다 | \"가끔\"이라고만 적음 → \"10회 중 3회\"로 |\n| **증거** | 스크린샷, 영상, 로그, 네트워크 응답 | 화면 캡처만 있고 로그가 없음 |\n| **심각도/우선순위** | 처리 순서를 정하는 기준 | 둘을 같은 것으로 취급 |\n\n**기대 결과를 빼는 것이 가장 흔하고 가장 나쁜 실수다.** 기대 결과가 없으면 개발자는 \"이게 원래 그런 건데요?\"라고 답할 수 있다. 기대 결과에는 **근거**를 붙이는 게 좋다.\n\n```text\n기대 결과: 할인은 1회만 적용되어 결제금액 9,000원\n근거: 기획서 v2.3 4.2절 \"쿠폰은 주문당 1회 적용\"\n```\n\n기획서에 근거가 없다면 그렇게 적는다. `근거: 명세에 정의 없음 — 상식적으로 음수 결제는 불가능하다고 판단. 정책 확인 필요` 이렇게 쓰면 **결함 리포트인 동시에 명세 질문**이 된다.\n\n### 재현 절차 쓰는 법\n\n원칙은 하나다. **한 단계에 한 동작.** 그리고 **아무 정보 없는 사람이 따라 할 수 있어야 한다.**\n\n```text\n[나쁨]\n1. 로그인해서 상품 담고 쿠폰 적용 후 결제한다\n\n[좋음]\n사전 조건: 테스트 계정 qa_user_01 / 장바구니 비어 있음 / 유효한 10% 쿠폰 1장 보유\n1. qa_user_01 로 로그인한다\n2. 상품 \"무선 이어폰\"(상품ID 10023) 상세 페이지로 이동한다\n3. [장바구니 담기] 를 누른다\n4. 장바구니로 이동한다\n5. 쿠폰 [10% 할인] 을 적용한다   → 이 시점 결제예정금액 9,000원 확인\n6. 수량을 1 → 2 로 변경한다\n7. 결제예정금액을 확인한다\n```\n\n5번처럼 **중간 확인 지점**을 넣으면 개발자가 어디까지는 정상이고 어디서 틀어지는지 바로 안다. 디버깅 시간이 크게 줄어든다.\n\n### 심각도(Severity)와 우선순위(Priority)는 다르다\n\n이걸 구분 못 하면 면접에서 바로 걸러진다.\n\n| | 심각도 (Severity) | 우선순위 (Priority) |\n|---|---|---|\n| 판단 주체 | QA (객관적) | PO/개발리드 (비즈니스 판단) |\n| 기준 | 시스템에 미치는 영향의 크기 | 언제까지 고쳐야 하는가 |\n| 바뀌는가 | 잘 안 바뀜 | 상황에 따라 자주 바뀜 |\n\n**네 조합이 모두 실제로 존재한다.** 이걸 예시로 설명할 수 있어야 한다.\n\n| 조합 | 예시 |\n|---|---|\n| 심각도 高 / 우선순위 高 | 결제가 전혀 안 된다 → 지금 당장 |\n| 심각도 高 / 우선순위 低 | 관리자만 쓰는 통계 페이지에서 서버 오류. 데이터는 안전하고 월 1회만 사용 → 다음 스프린트 |\n| 심각도 低 / 우선순위 高 | 메인 배너에 회사명 오타. 기능은 멀쩡하지만 **모든 사용자가 본다** → 지금 당장 |\n| 심각도 低 / 우선순위 低 | 설정 화면 하단 아이콘이 2px 어긋남 → 백로그 |\n\n세 번째 행이 핵심이다. **\"기능에는 문제없으니 낮은 등급\"이 아니다.** 브랜드·법무·보안 이슈는 심각도가 낮아도 우선순위가 최상이 된다.\n\n심각도 등급의 일반적 기준.\n\n```text\nBlocker  : 테스트 진행 자체가 불가. 핵심 기능 완전 불가. 데이터 유실·금전 손실\nCritical : 핵심 기능이 우회 방법 없이 실패. 보안 취약점\nMajor    : 주요 기능이 실패하지만 우회 방법이 있음\nMinor    : 부가 기능 실패. 사용성 불편\nTrivial  : 오타, 미세한 UI 어긋남\n```\n\n### 간헐적 결함을 다루는 법\n\n\"가끔 발생합니다\"는 리포트로서 거의 쓸모가 없다. 개발자가 재현을 못 하면 **닫히거나 방치된다.** 간헐적 결함일수록 정보를 더 모아야 한다.\n\n- **재현율을 숫자로**: \"10회 시도 중 3회 발생\"\n- **발생/미발생 조건을 비교**: 성공한 7회와 실패한 3회의 차이는 무엇이었나 (시간대? 데이터? 순서? 네트워크?)\n- **타임스탬프를 정확히**: 개발자가 서버 로그에서 그 시각을 찾을 수 있게. 초 단위까지\n- **네트워크 탭 HAR 파일 첨부**: 요청/응답 원본이 있으면 재현 없이도 분석이 가능하다\n- **영상 녹화**: 재현 절차로 표현 안 되는 타이밍 이슈는 화면 녹화가 가장 강력하다\n\n### 리포트 전에 스스로 확인할 것\n\n제출 전 30초만 쓰면 반려율이 크게 줄어든다.\n\n1. **최신 빌드에서 재현되는가?** 이미 고쳐진 걸 올리면 신뢰를 잃는다\n2. **중복 이슈가 아닌가?** 이슈 트래커에서 키워드로 먼저 검색\n3. **환경 문제가 아닌가?** 다른 계정, 다른 브라우저, 캐시 삭제 후에도 발생하는가\n4. **명세를 다시 읽었는가?** 의도된 동작을 결함으로 올리는 경우가 생각보다 많다\n5. **제목만 읽고 무슨 일인지 알 수 있는가?**\n\n## 왜 채용시장이 요구하는가\n\n- 채용공고의 \"결함 리포팅 및 이슈 트래킹 경험\"은 기본 항목이지만, **면접 실기로 자주 나온다.** \"이 화면에서 버그를 하나 찾아 리포트를 써 보세요\"는 흔한 과제다.\n- **심각도와 우선순위 구분은 단골 질문**이고, 네 조합의 예시를 즉석에서 못 대면 실무 경험이 얕다고 판단된다.\n- **개발자와의 신뢰가 여기서 만들어진다.** 재현 잘 되는 리포트를 쓰는 QA는 \"우리 팀 QA\"가 되고, 애매한 리포트를 쓰는 QA는 티켓 발행기가 된다. 이 차이가 연봉과 직급에 반영된다.\n- **AI로 리포트를 다듬는 것이 2026년의 기본**이 됐다. 다만 AI는 **없는 정보를 자연스럽게 지어낸다.** \"Chrome 최신 버전에서 재현\" 같은 문장을 만들어 넣는다. 확인하지 않은 것을 확인한 것처럼 쓰는 리포트는 신뢰를 통째로 깎아먹는다. AI를 쓰되 사실 여부는 반드시 본인이 검증해야 한다.\n\n## 실습 과제\n\n### 과제 1 — 나쁜 리포트 고쳐 쓰기 (10분)\n\n아래 리포트를 완전한 형태로 다시 쓴다. 부족한 정보는 **\"확인 필요\"로 명시**하고, 무엇을 어떻게 확인할지 적는다.\n\n> **제목**: 결제 오류\n> **내용**: 장바구니에서 결제하려는데 가끔 실패함. 폰에서 봤음. 다시 하면 됨.\n\n체크 포인트:\n- 제목을 공식대로 다시 썼는가\n- 실제 결과와 기대 결과를 분리했는가\n- \"가끔\"을 숫자로 바꾸기 위해 무엇을 해야 하는지 적었는가\n- 심각도와 우선순위를 각각 근거와 함께 매겼는가\n\n### 과제 2 — 심각도/우선순위 4분면 채우기 (8분)\n\n본인이 아는 서비스에서 **네 조합에 해당하는 결함을 각각 하나씩** 지어낸다. (실제 결함이 아니어도 된다)\n\n| | 우선순위 高 | 우선순위 低 |\n|---|---|---|\n| **심각도 高** | | |\n| **심각도 低** | | |\n\n각 칸에 \"왜 이 조합인가\"를 한 줄로 붙인다. 면접에서 그대로 쓸 수 있는 답변이 된다.\n\n### 과제 3 — 실습 랩에서 찾아 리포트 쓰기 (15분)\n\n실습 랩의 **결함이 숨겨진 샘플 앱**에서 결함을 2개 찾아 완전한 리포트를 작성한다.\n증거로 무엇을 첨부할지(스크린샷 / 콘솔 로그 / 네트워크 응답)도 함께 적는다.\n\n### 과제 4 — AI로 다듬고 사실 검증하기 (10분)\n\nAI 실습 도우미의 **결함 리포트 정리** 템플릿에 과제 3에서 찾은 결함을 두서없이 적어 넣고 정리시킨다.\n그리고 **AI 출력물에서 다음을 찾아 표시한다.**\n\n- 내가 말하지 않았는데 AI가 채워 넣은 정보 (환경, 버전, 재현율 등)\n- 내가 확인하지 않은 것을 확인한 것처럼 단정한 문장\n- \"확인 필요\"로 남겼어야 할 항목을 그냥 채워버린 곳\n\n**이것들을 다 지우고 나서야 제출 가능한 리포트가 된다.** 이 검증 습관이 트랙 6의 핵심이다.\n\n## 자가 체크리스트\n\n- [ ] 결함 제목을 `[영역] {조건}에서 {무엇}이 {어떻게}` 공식으로 쓸 수 있다\n- [ ] 실제 결과와 기대 결과를 분리해서 쓰고, 기대 결과에 근거를 붙일 수 있다\n- [ ] 재현 절차를 한 단계 한 동작으로 쪼개고 중간 확인 지점을 넣을 수 있다\n- [ ] 사전 조건(계정, 데이터 상태)을 명시할 수 있다\n- [ ] 심각도와 우선순위의 차이를 판단 주체·기준으로 설명할 수 있다\n- [ ] 심각도/우선순위 네 조합의 실제 예시를 각각 댈 수 있다\n- [ ] 심각도 낮음 + 우선순위 높음의 대표 사례(오타·법무·브랜드)를 설명할 수 있다\n- [ ] 간헐적 결함에서 재현율을 숫자로 만들고 발생/미발생 조건을 비교할 수 있다\n- [ ] 제출 전 5가지 자가 확인(최신빌드·중복·환경·명세·제목)을 수행한다\n- [ ] AI가 다듬은 리포트에서 지어낸 정보를 찾아 제거할 수 있다\n\n## 참고 링크\n\n- [Mozilla — Bug Writing Guidelines](https://bugzilla.mozilla.org/page.cgi?id=bug-writing.html) — 좋은 버그 리포트의 고전\n- [Atlassian Jira — Issue Fields 가이드](https://support.atlassian.com/jira-software-cloud/) — 실제 필드 구성과 워크플로 (트랙 2에서 다룬다)\n- [Chrome DevTools — Network 패널로 HAR 저장하기](https://developer.chrome.com/docs/devtools/network/) — 증거 첨부의 기본기\n","t1-l07":"---\nid: t1-l07\ntitle: 릴리즈 품질 검증과 Go/No-Go 판단\nsummary: 배포 전후에 무엇을 확인하고, 어떤 근거로 나가도 된다고 말할 것인가. 롤백 기준까지 미리 정한다.\nminutes: 20\norder: 7\ntags: [릴리즈, GoNoGo, 리스크판단, 롤백, 모니터링]\n---\n\n## 개념 설명\n\n### Go/No-Go 는 \"다 됐나요?\"에 대한 답이 아니다\n\n릴리즈 회의에서 QA에게 던져지는 질문은 대개 이렇다.\n\n> \"QA 다 끝났나요? 나가도 되죠?\"\n\n여기서 **\"네, 다 됐습니다\"** 라고 답하면 안 된다. 테스트는 결함이 없음을 증명할 수 없다. 실제로 해야 할 답은 이것이다.\n\n> \"계획한 TC 142건 중 140건 실행, 통과율 97%입니다. Blocker·Critical 0건이고, Major 2건이 남아 있습니다. 하나는 관리자 통계 화면 오류로 사용자 영향이 없고, 다른 하나는 쿠폰 중복 적용인데 해당 쿠폰을 발급 중지하는 조건으로 나갈 수 있습니다. **이 조건이면 Go 의견입니다.**\"\n\n**QA는 결정권자가 아니라 근거 제공자다.** 하지만 근거 없이 \"느낌상 불안합니다\"라고 말하면 아무도 듣지 않는다. 반대로 숫자와 조건을 제시하면 QA의 판단이 회의 결과를 좌우한다.\n\n### 판단에 필요한 다섯 가지 근거\n\n| 근거 | 구체적으로 |\n|---|---|\n| **실행 현황** | 계획 TC 수 / 실행 수 / 통과·실패·차단(Blocked) 수 |\n| **미해결 결함** | 심각도별 잔여 건수, 각각의 사용자 영향과 우회 방법 |\n| **미검증 영역** | 시간이 없어 못 본 영역과 그것을 감수하는 이유 |\n| **회귀 결과** | 자동화 스위트 통과율, 실패한 테스트의 원인 분류 |\n| **롤백 준비** | 되돌릴 수 있는가, 얼마나 걸리는가, 데이터는 어떻게 되는가 |\n\n마지막 항목이 자주 빠진다. **되돌릴 수 있으면 리스크를 더 감수해도 되고, 되돌릴 수 없으면 훨씬 보수적으로 판단해야 한다.**\n\n되돌릴 수 없는 변경의 예:\n- DB 스키마 변경 (컬럼 삭제, 타입 변경)\n- 데이터 마이그레이션 (기존 값을 덮어씀)\n- 외부에 이미 발송된 것 (푸시 알림, 이메일)\n- 앱 스토어 심사를 통과해 배포된 앱 (강제 롤백 불가, 새 버전 심사 필요)\n\n이런 게 포함된 릴리즈는 **테스트 깊이를 한 단계 올려야 한다.** 앞 레슨의 리스크 계산에서 \"되돌릴 수 있는가\"가 영향도 항목에 들어갔던 이유다.\n\n### No-Go 를 말해야 하는 순간\n\n다음 중 하나라도 해당하면 개인 의견이 아니라 **원칙으로서** No-Go를 제시한다.\n\n1. **Blocker/Critical 미해결** — 우회 방법이 없는 핵심 기능 실패\n2. **데이터 유실 또는 금전 손실 가능성** — 재현율이 낮아도 마찬가지\n3. **보안 취약점** — 인증 우회, 타인 데이터 노출, 권한 상승\n4. **롤백 불가 + 검증 부족** — 되돌릴 수 없는데 핵심 영역을 못 봤다\n5. **스모크 실패** — 애초에 테스트 가능한 빌드가 아니다\n\nNo-Go를 말할 때는 **대안을 함께 낸다.** \"안 됩니다\"만 말하는 QA는 협업 상대로 기피된다.\n\n> \"지금 상태로는 No-Go 의견입니다. 다만 세 가지 선택지가 있습니다.\n> (1) 쿠폰 기능만 피처 플래그로 끄고 나머지를 배포한다 — 오늘 가능\n> (2) 수정 후 회귀 3시간 → 내일 오전 배포\n> (3) 발생 조건이 VIP 등급에만 해당하므로, 해당 등급을 임시 제외하고 배포 — 리스크 남음\n> 저는 (1)을 권합니다.\"\n\n### 배포 전 체크리스트 (Pre-release)\n\n```text\n□ 스모크 테스트 통과 (운영과 동일한 구성의 스테이징에서)\n□ 계획 TC 실행 완료, 미실행 항목의 사유 기록\n□ 회귀 자동화 스위트 통과 (실패 건은 원인 분류 완료)\n□ 잔여 결함 목록과 각각의 처리 방침 합의 (수정 / 다음 릴리즈 / Won't fix)\n□ 롤백 절차 확인 — 누가, 어떤 명령으로, 몇 분 안에\n□ DB 마이그레이션이 있다면 롤백 스크립트 존재 여부 확인\n□ 피처 플래그로 끌 수 있는 기능 목록 정리\n□ 모니터링 대시보드와 알림 임계치 준비\n□ 배포 후 확인할 항목(스모크) 목록을 미리 작성\n□ 이해관계자 공지 (CS팀, 운영팀 — 무엇이 바뀌는지)\n```\n\nCS팀 공지가 빠지면 배포 직후 문의가 폭주할 때 아무도 답을 못 한다.\n\n### 배포 후 검증 (Post-release)\n\n배포는 끝이 아니라 **가장 위험한 순간의 시작**이다. 스테이징에서 안 나오던 게 운영에서 나온다. 실제 데이터, 실제 트래픽, 실제 외부 연동이 다르기 때문이다.\n\n**1단계 — 배포 직후 (5~15분)**\n\n미리 준비한 운영 스모크를 돌린다. 실제 계정으로 핵심 경로 하나씩.\n\n```text\n□ 메인 페이지 정상 로드\n□ 로그인 / 로그아웃\n□ 핵심 트랜잭션 1건 실제 수행 (주문 → 결제 → 취소까지 완주)\n□ 변경된 기능 직접 확인\n□ 에러 로그에 새로운 유형의 예외가 올라오는지\n```\n\n**2단계 — 지표 관찰 (1~24시간)**\n\n여기서 보는 것은 기능이 아니라 **숫자의 변화**다. (트랙 2에서 도구 사용법을 배운다)\n\n| 지표 | 무엇을 의미하나 |\n|---|---|\n| 에러율 (5xx, 4xx) | 배포 전 대비 급증하면 즉시 롤백 검토 |\n| 응답시간 p95/p99 | 평균은 멀쩡해도 꼬리가 길어지면 특정 조건에서 문제 |\n| 핵심 전환율 | 주문 완료율, 로그인 성공률 — **기능은 되는데 사람들이 못 쓰는** 경우를 잡는다 |\n| 외부 API 실패율 | 연동 쪽 문제 |\n| CS 문의 유입 | 지표보다 사람이 먼저 발견하는 경우가 많다 |\n\n세 번째 행이 중요하다. **\"에러는 안 나는데 주문 완료율이 20% 떨어졌다\"** 는 최악의 상황이고, 기능 테스트로는 절대 안 잡힌다. 버튼이 화면 밖으로 밀려났거나, 문구가 헷갈리거나, 특정 기기에서만 안 눌리는 경우다.\n\n**3단계 — 롤백 판단 기준을 미리 숫자로**\n\n배포 후에 \"롤백할까요 말까요\"를 즉흥적으로 논의하면 늦는다. **배포 전에** 이런 기준을 합의해 둔다.\n\n```text\n즉시 롤백:\n  - 5xx 에러율이 배포 전 대비 3배 이상, 5분 이상 지속\n  - 결제 성공률이 95% 미만으로 하락\n  - 데이터 정합성 오류가 1건이라도 확인됨\n\n관찰 후 판단 (30분):\n  - p95 응답시간이 1.5배 이상 증가\n  - 특정 기능의 에러율만 상승 → 피처 플래그로 해당 기능만 차단\n```\n\n**단계적 배포(카나리)** 가 가능하다면 리스크가 크게 줄어든다. 5% 트래픽에만 먼저 배포하고 지표를 본 뒤 확대하는 방식이다. QA는 각 단계에서 무엇을 확인할지 정의한다.\n\n### 릴리즈 회고\n\n배포가 끝나면 15분만 써서 남긴다.\n\n- 운영에서 발견된 결함이 있었다면 **왜 테스트에서 못 잡았는가** (환경 차이? 데이터 차이? TC 누락? 범위에서 뺐던 영역?)\n- 다음 릴리즈에 추가할 TC 또는 자동화 항목\n- 판단이 틀렸던 지점 (Go 했는데 문제가 났다면 어떤 근거가 부족했나)\n\n이 기록이 쌓이면 **결함 탈출률**(다음 레슨)을 실제로 낮출 수 있다.\n\n## 왜 채용시장이 요구하는가\n\n- 채용공고의 \"릴리즈 전후 품질 검증\", \"배포 판단 참여\"는 **주니어에게는 잘 안 시키는 일**이다. 이걸 해봤다는 건 팀에서 신뢰받는 위치였다는 신호로 읽힌다.\n- 면접 단골 질문: **\"릴리즈 직전에 Critical 결함을 발견했습니다. 어떻게 하시겠어요?\"**\n  좋은 답의 구조 = 영향 범위 파악 → 우회 방법 확인 → 롤백 가능 여부 확인 → 선택지 2~3개와 권고안 제시. \"무조건 막습니다\"도 \"일단 나가시죠\"도 답이 아니다.\n- **AI가 대체하기 가장 어려운 영역**이다. TC 생성과 실행은 자동화되지만, \"지금 나가도 되는가\"는 비즈니스 맥락·리스크 감수 수준·조직의 롤백 능력을 종합한 판단이다. QA 커리어의 상위 구간이 여기에 있다.\n\n## 실습 과제\n\n### 과제 1 — Go/No-Go 발언 작성 (12분)\n\n아래 상황에서 릴리즈 회의에서 할 발언을 **그대로 읽을 수 있는 문장**으로 작성한다.\n\n> - 계획 TC 96건 중 89건 실행 (7건은 결제 스테이징 환경 장애로 Blocked)\n> - Critical 0건, Major 1건 (특정 안드로이드 12 기기에서 이미지 업로드 실패, 전체 사용자의 약 4%)\n> - 회귀 자동화 통과율 94% — 실패 6건 중 5건은 플래키로 확인, 1건은 미분석\n> - 이번 릴리즈에 DB 컬럼 타입 변경 포함 (롤백 스크립트 있음, 검증은 안 됨)\n> - 마케팅 프로모션이 내일 오전 10시 시작 예정\n\n포함할 것: 숫자 근거 / 미검증 영역과 그 리스크 / 선택지 2~3개 / 본인 권고안과 이유\n\n**힌트**: 롤백 스크립트가 \"있지만 검증 안 됨\"인 것과 Blocked 7건이 하필 결제 영역인 것이 이 문제의 핵심이다.\n\n### 과제 2 — 롤백 기준 숫자로 정하기 (8분)\n\n본인이 아는 서비스 하나를 골라 배포 후 롤백 기준을 작성한다.\n\n| 지표 | 정상 범위 | 관찰 임계치 | 즉시 롤백 임계치 |\n|---|---|---|---|\n| 5xx 에러율 | | | |\n| 결제 성공률 | | | |\n| p95 응답시간 | | | |\n| 로그인 성공률 | | | |\n\n숫자를 모르면 **\"무엇을 알아야 이 숫자를 정할 수 있는가\"** 를 적는다. (평상시 기준선을 모르면 이상을 판단할 수 없다는 것이 이 과제의 교훈이다)\n\n### 과제 3 — 배포 후 스모크 스크립트 설계 (10분)\n\n배포 직후 15분 안에 끝나야 하는 운영 스모크 체크리스트를 만든다.\n\n제약: **10개 항목 이내**, 실제 운영 데이터를 오염시키지 않을 것.\n\n마지막 제약이 실무에서 까다롭다. 운영에서 테스트 주문을 넣으면 매출 집계와 재고가 틀어진다. 어떻게 할 것인가를 함께 적는다. (테스트 계정 제외 처리, 즉시 취소, 별도 테스트 상품 등)\n\n## 자가 체크리스트\n\n- [ ] \"QA 다 됐나요\"에 숫자 근거로 답하는 문장을 만들 수 있다\n- [ ] Go/No-Go 판단에 필요한 5가지 근거를 나열할 수 있다\n- [ ] 롤백 가능 여부가 판단 기준을 어떻게 바꾸는지 설명할 수 있다\n- [ ] 되돌릴 수 없는 변경의 예를 4가지 이상 댈 수 있다\n- [ ] No-Go 조건 5가지를 원칙으로 제시할 수 있다\n- [ ] No-Go를 말할 때 대안 선택지를 함께 제시할 수 있다\n- [ ] 배포 전 체크리스트를 10개 항목 이상 작성할 수 있다\n- [ ] 배포 후 1단계(스모크)와 2단계(지표 관찰)를 구분해 수행할 수 있다\n- [ ] \"에러는 없는데 전환율이 떨어진\" 상황의 원인을 3가지 이상 추측할 수 있다\n- [ ] 롤백 기준을 배포 전에 숫자로 합의해 두어야 하는 이유를 설명할 수 있다\n- [ ] 릴리즈 회고에서 \"왜 테스트에서 못 잡았는가\"를 분류할 수 있다\n\n## 참고 링크\n\n- [Google SRE Book — Release Engineering](https://sre.google/sre-book/release-engineering/) — 롤백과 카나리 배포의 원칙\n- [Google SRE Book — Monitoring Distributed Systems](https://sre.google/sre-book/monitoring-distributed-systems/) — 무엇을 지표로 볼 것인가 (4 Golden Signals)\n- [Martin Fowler — Feature Toggles](https://martinfowler.com/articles/feature-toggles.html) — 피처 플래그로 리스크를 분리하는 법\n- [Atlassian — Incident Postmortem](https://www.atlassian.com/incident-management/postmortem) — 회고 템플릿\n","t1-l08":"---\nid: t1-l08\ntitle: 품질 지표 — 커버리지, 결함 밀도, 실패율, 결함 탈출률\nsummary: 숫자로 품질을 말하는 법. 그리고 지표가 목표가 되는 순간 어떻게 망가지는지까지 함께 배운다.\nminutes: 20\norder: 8\ntags: [품질지표, 커버리지, 결함밀도, 결함탈출률, DDP]\n---\n\n## 개념 설명\n\n앞 레슨에서 \"숫자 근거로 말하라\"고 했다. 이번 레슨은 그 숫자들의 정의와, **그 숫자를 어떻게 오해하지 않을 것인가**를 다룬다.\n\n지표를 다루는 QA가 반드시 알아야 할 전제가 하나 있다.\n\n> **모든 품질 지표는 조작 가능하다.** 그래서 지표는 \"판단의 근거\"로 쓰고, \"달성해야 할 목표\"로 걸어두면 반드시 망가진다.\n\n### 1. 테스트 커버리지\n\n커버리지에는 성격이 다른 두 가지가 있다. **면접에서 자주 섞어 쓰는데, 구분해야 한다.**\n\n**요구사항 커버리지 (QA의 지표)**\n\n```text\n요구사항 커버리지 = (TC가 매핑된 요구사항 수 / 전체 요구사항 수) × 100\n```\n\n요구사항 명세의 각 항목에 최소 1개 이상의 TC가 연결돼 있는가를 본다. **이게 QA가 직접 관리하는 커버리지다.** 요구사항 추적 매트릭스(RTM)로 관리한다.\n\n| 요구사항 ID | 내용 | TC ID | 실행 결과 |\n|---|---|---|---|\n| REQ-01 | 쿠폰은 주문당 1회 적용 | TC-011, TC-012, TC-013 | Pass |\n| REQ-02 | 휴면 회원은 쿠폰 사용 불가 | TC-021 | Fail |\n| REQ-03 | 도서산간 추가 배송비 | **없음** | ← 구멍 |\n\nRTM의 진짜 가치는 마지막 행이다. **TC가 하나도 없는 요구사항을 발견하는 것**이 목적이다.\n\n**코드 커버리지 (개발의 지표)**\n\n```text\n라인 커버리지   : 실행된 코드 라인 / 전체 라인\n브랜치 커버리지 : 실행된 분기 / 전체 분기   ← 이쪽이 의미 있다\n```\n\nQA가 만드는 숫자는 아니지만 **읽을 줄은 알아야 한다.** 그리고 이 지표의 함정을 알아야 한다.\n\n```javascript\nfunction calcShipping(amount, isVip) {\n  if (amount >= 30000 || isVip) return 0;\n  return 3000;\n}\n\n// 이 테스트는 라인 커버리지 100% 를 만든다\ntest('배송비', () => {\n  calcShipping(50000, false);   // 0 반환 경로\n  calcShipping(10000, false);   // 3000 반환 경로\n});\n```\n\n라인 커버리지 100%인데 **아무것도 검증하지 않았다.** `expect` 가 없다. 그리고 `isVip=true` 경로는 실행조차 안 됐는데 `||` 단축 평가 때문에 라인은 다 지나갔다.\n\n> **커버리지는 \"테스트되지 않은 곳\"을 찾는 도구이지, \"테스트가 잘 됐다\"는 증거가 아니다.**\n\n커버리지 80%가 목표로 걸리면 개발자는 assert 없는 테스트를 양산하게 된다. 이게 굿하트의 법칙이다. QA가 코드 커버리지 리포트를 볼 때는 **숫자가 아니라 \"0%인 파일\"** 을 본다. 그게 위험 지점이다.\n\n### 2. 결함 밀도 (Defect Density)\n\n```text\n결함 밀도 = 발견된 결함 수 / 규모\n```\n\n규모 단위는 조직에 따라 다르다. KLOC(코드 1000줄), 기능 포인트, 화면 수, 스토리 포인트 등.\n\n**절대값은 의미가 없고 비교할 때만 쓴다.**\n\n| 모듈 | 결함 수 | 규모(KLOC) | 밀도 |\n|---|---|---|---|\n| 결제 | 24 | 8 | 3.0 |\n| 상품목록 | 6 | 12 | 0.5 |\n| 알림 | 15 | 3 | **5.0** |\n\n알림 모듈이 눈에 띈다. 코드는 작은데 결함이 가장 많다. → **다음 릴리즈에서 이 모듈의 회귀 범위를 넓히고, 리팩터링을 제안할 근거**가 된다.\n\n해석에 주의할 점: **결함 밀도가 낮은 게 항상 좋은 게 아니다.** 아예 테스트를 안 한 모듈도 밀도가 0이다. 실행한 TC 수와 함께 봐야 한다.\n\n### 3. 테스트 실패율 / 통과율\n\n```text\n통과율 = Pass / (Pass + Fail) × 100\n실행률 = 실행 / 계획 × 100\n```\n\n**Blocked(차단)를 분모에서 어떻게 다룰지 팀 규칙을 정해야 한다.** 환경 문제로 실행 못 한 TC를 Fail로 세면 품질이 나빠 보이고, 빼버리면 미검증 영역이 숨는다. 권장 방식은 **분모에서 제외하되 별도로 명시**하는 것이다.\n\n```text\n계획 96건 / 실행 89건 (실행률 92.7%) / 통과 86건 (통과율 96.6%) / Blocked 7건 ← 결제 영역\n```\n\nBlocked 건수를 감추지 않는 게 핵심이다. 앞 레슨의 Go/No-Go에서 이게 결정적 정보였다.\n\n**자동화 스위트의 실패율은 별도로 관리한다.** 그리고 실패를 반드시 분류한다.\n\n| 분류 | 의미 | 조치 |\n|---|---|---|\n| 진짜 결함 | 제품이 잘못됨 | 결함 리포트 |\n| 플래키 | 재실행하면 통과 | 격리 후 원인 수정 (트랙 3) |\n| 테스트 오류 | 테스트 코드가 잘못됨 | 테스트 수정 |\n| 환경 문제 | 인프라·데이터 문제 | 환경 수정 |\n\n이 분류를 안 하면 **\"어차피 가끔 빨간불 뜨는 거\"** 가 되고, 그 순간 자동화 스위트는 죽는다. 아무도 안 보게 된다.\n\n### 4. 결함 탈출률 (Defect Escape Rate / DDP) ⭐\n\n**QA 조직의 성과를 가장 잘 나타내는 단일 지표**다.\n\n```text\n결함 탈출률 = 운영에서 발견된 결함 / (QA가 발견한 결함 + 운영에서 발견된 결함) × 100\n\n결함 제거 효율(DDP) = 100 - 결함 탈출률\n```\n\n예: QA가 45건 잡고 운영에서 5건 터졌다면 → 탈출률 10%, DDP 90%.\n\n이 지표가 좋은 이유는 **\"QA가 무엇을 놓쳤는가\"를 직접 측정**하기 때문이다. 발견 건수만 세면 \"많이 찾은 QA가 좋은 QA\"가 되는데, 그건 개발 품질이 나쁘다는 뜻일 수도 있다. 탈출률은 그 왜곡이 없다.\n\n**탈출한 결함은 반드시 원인을 분류한다.** 이게 실제 개선으로 이어지는 부분이다.\n\n| 탈출 원인 | 개선 방향 |\n|---|---|\n| TC 자체가 없었다 | 설계 기법 적용 누락 → 해당 기법 재점검 |\n| TC는 있었는데 실행 못 했다 | 시간·환경 문제 → 계획 또는 자동화 |\n| 실행했는데 못 봤다 | 기대 결과가 모호했음 → TC 문장 개선 |\n| 환경 차이 | 스테이징이 운영과 다름 → 환경 개선 요청 |\n| 데이터 차이 | 실제 데이터 패턴 미반영 → 테스트 데이터 전략 |\n| 명세에 없던 요구 | 요구사항 프로세스 문제 → 기획 단계 참여 확대 |\n\n3~6번은 **QA 개인의 실수가 아니라 프로세스 문제**다. 이걸 구분해서 말할 수 있으면 회고가 비난이 아니라 개선이 된다.\n\n### 5. 그 밖에 실무에서 쓰는 것\n\n| 지표 | 정의 | 무엇을 보는가 |\n|---|---|---|\n| 결함 재발률 | 재오픈된 결함 / 전체 수정 결함 | 수정 품질, 회귀 테스트 부실 |\n| 평균 수정 시간 (MTTR) | 리포트 → 수정 완료 평균 시간 | 대응 속도 |\n| 자동화 비율 | 자동화 TC / 전체 TC | 단독으로는 무의미. 실행 시간·유지비와 함께 |\n| 결함 유입 단계 | 요구사항/설계/구현 중 어디서 생긴 결함인가 | 앞단으로 갈수록 개선 효과가 크다 |\n\n**자동화 비율을 목표로 거는 것은 특히 위험하다.** 유지비가 큰 UI 테스트를 무작정 늘리면 비율은 오르고 팀은 느려진다. 트랙 3에서 \"무엇을 자동화하지 않을지\"를 따로 배우는 이유다.\n\n### 지표를 다룰 때의 원칙\n\n1. **추세로 본다.** 이번 릴리즈 탈출률 10%는 단독으로는 좋은지 나쁜지 모른다. 지난 5회가 18 → 15 → 12 → 11 → 10 이면 좋은 것이다\n2. **한 지표만 보지 않는다.** 통과율 100%인데 실행률이 40%면 아무 의미 없다\n3. **목표로 걸지 않는다.** 특히 개인 평가에 연동하면 반드시 조작된다\n4. **숫자 옆에 맥락을 쓴다.** \"통과율 96.6% (Blocked 7건은 결제 스테이징 장애)\"\n\n## 왜 채용시장이 요구하는가\n\n- 채용공고의 \"품질 지표 관리 경험\"은 **QA를 실행 인력이 아니라 관리자로 보는 조직**의 신호다. 리드·매니저 트랙으로 가려면 필수다.\n- 면접에서 **\"QA 업무 성과를 어떻게 측정하셨나요?\"** 는 상당히 자주 나온다. \"버그 몇 건 찾았습니다\"는 약한 답이고, **결함 탈출률과 그 원인 분류**를 말하면 강한 답이 된다.\n- **AI 도입 효과를 증명하는 언어도 지표다.** \"AI로 TC를 생성했더니 좋았습니다\"는 설득이 안 된다. \"TC 작성 시간이 40% 줄고 결함 탈출률은 12% → 9%로 개선됐다\"가 설득이다. 2026년에 AI 도구 도입을 주도하려면 이 언어가 필요하다.\n- **AI가 만든 지표 리포트를 검증하는 것도 QA의 일이다.** AI에게 결함 데이터를 주고 리포트를 시키면 계산을 틀리거나, 분모를 마음대로 바꾸거나, 없는 추세를 읽어낸다. 정의를 정확히 알아야 검증할 수 있다.\n\n## 실습 과제\n\n### 과제 1 — 지표 계산과 해석 (12분)\n\n아래 데이터로 지표를 계산하고, **회고 회의에서 발표할 3문장**을 작성한다.\n\n```text\n릴리즈 3.4.0\n  계획 TC 120건 / 실행 108건 / Pass 99건 / Fail 9건 / Blocked 12건\n  QA 발견 결함: Blocker 0, Critical 2, Major 11, Minor 23\n  배포 후 2주간 운영 발견 결함: Critical 1, Major 3, Minor 4\n  이전 3회 릴리즈 결함 탈출률: 21%, 17%, 14%\n```\n\n- 실행률 / 통과율 / 결함 탈출률 / DDP 계산\n- 추세는 개선 중인가\n- **Blocked 12건이 이 숫자들을 어떻게 왜곡하고 있는가**\n- 발표 3문장 (좋아진 것 / 우려되는 것 / 다음에 할 것)\n\n### 과제 2 — 탈출 결함 원인 분류 (10분)\n\n과제 1에서 운영으로 탈출한 8건에 대해, 그럴듯한 원인을 지어내 6가지 분류에 배치한다.\n그리고 **가장 많은 분류에 대한 개선안 1개**를 구체적으로 적는다. (\"더 꼼꼼히 보겠다\"는 개선안이 아니다)\n\n### 과제 3 — 지표 조작 시나리오 (8분)\n\n**\"이 지표를 목표로 걸면 사람들이 어떻게 편법을 쓸까?\"** 를 각 지표마다 하나씩 적어본다.\n\n| 지표 | 목표로 걸었을 때의 편법 |\n|---|---|\n| 코드 커버리지 80% | |\n| 자동화 비율 70% | |\n| 결함 발견 건수 월 50건 | |\n| 통과율 95% | |\n| 결함 탈출률 5% 이하 | |\n\n마지막 행이 어렵다. 탈출률조차 조작할 수 있다 — **운영 결함을 \"사양 변경\"으로 분류하면 분자가 줄어든다.** 이걸 아는 것이 지표를 제대로 쓰는 출발점이다.\n\n### 과제 4 — AI에게 리포트 시키고 계산 검증 (10분)\n\nAI 실습 도우미에 과제 1의 원본 데이터를 그대로 주고 품질 리포트를 만들게 한 뒤, **손으로 계산한 값과 대조**한다.\n\n확인할 것:\n- 실행률·통과율의 **분모를 무엇으로 잡았는가** (Blocked 처리 방식)\n- 결함 탈출률 계산이 정의와 일치하는가\n- 데이터에 없는 추세나 원인을 지어내지 않았는가\n- \"품질이 개선되고 있습니다\" 같은 **근거 없는 총평**을 붙이지 않았는가\n\n경험상 AI는 Blocked 처리에서 자주 틀리고, 요청하지 않은 낙관적 총평을 붙인다.\n\n## 자가 체크리스트\n\n- [ ] 요구사항 커버리지와 코드 커버리지를 구분하고 각각 누가 관리하는지 안다\n- [ ] RTM의 목적이 \"TC가 없는 요구사항 찾기\"임을 설명할 수 있다\n- [ ] 라인 커버리지 100%인데 아무것도 검증하지 않는 테스트의 예를 들 수 있다\n- [ ] 커버리지 리포트에서 숫자가 아니라 \"0%인 파일\"을 봐야 하는 이유를 안다\n- [ ] 결함 밀도를 계산하고, 밀도가 낮은 게 항상 좋은 게 아닌 이유를 설명할 수 있다\n- [ ] 통과율·실행률을 계산하고 Blocked를 어떻게 처리할지 규칙으로 말할 수 있다\n- [ ] 자동화 테스트 실패를 4가지(진짜 결함/플래키/테스트 오류/환경)로 분류할 수 있다\n- [ ] 결함 탈출률과 DDP를 정의대로 계산할 수 있다\n- [ ] 탈출한 결함의 원인을 6가지로 분류하고, 개인 실수와 프로세스 문제를 구분할 수 있다\n- [ ] 지표를 목표로 걸었을 때 발생하는 조작 방식을 각 지표마다 예상할 수 있다\n- [ ] 숫자를 보고할 때 추세와 맥락을 함께 제시할 수 있다\n- [ ] AI가 만든 품질 리포트에서 분모 오류와 근거 없는 총평을 잡아낼 수 있다\n\n## 참고 링크\n\n- [Capers Jones — Defect Removal Efficiency](https://www.ifpug.org/) — DDP 개념의 출처. 업계 벤치마크 수치 참고\n- [Martin Fowler — Test Coverage](https://martinfowler.com/bliki/TestCoverage.html) — \"커버리지를 목표로 삼지 말라\"의 고전적 논거\n- [Google Testing Blog — Code Coverage Best Practices](https://testing.googleblog.com/2020/08/code-coverage-best-practices.html) — 커버리지를 실무에서 어떻게 쓸 것인가\n- [굿하트의 법칙 (Goodhart's law)](https://en.wikipedia.org/wiki/Goodhart%27s_law) — \"측정이 목표가 되면 좋은 측정이기를 그친다\"\n","t2-l01":"---\nid: t2-l01\ntitle: 이슈관리와 협업 — Jira · Confluence · Notion · Slack\nsummary: 티켓 하나가 어떤 흐름을 타는지, JQL로 내 일을 어떻게 찾는지, 그리고 QA가 협업 도구에서 실제로 하는 일.\nminutes: 18\norder: 1\ntags: [Jira, Confluence, Notion, Slack, JQL, 협업]\n---\n\n## 개념 설명\n\n도구 사용법 자체는 반나절이면 익힌다. 채용에서 보는 건 **\"이 사람이 팀의 일 흐름을 이해하고 있는가\"** 다. 이 레슨은 버튼 위치가 아니라 흐름을 다룬다.\n\n### Jira — 이슈 트래커\n\n**이슈 타입의 계층**을 먼저 이해해야 한다. 팀마다 이름은 조금씩 다르지만 구조는 같다.\n\n```text\nEpic (큰 기능 덩어리)\n └─ Story / Task (개발 단위)\n     └─ Sub-task (쪼갠 작업)\nBug (결함)          ← QA가 가장 많이 만드는 것\n```\n\n**결함 티켓의 표준 워크플로**는 대략 이렇게 흐른다.\n\n```text\nOpen ──> In Progress ──> Resolved ──> [QA 확인] ──> Closed\n  ^                          │\n  └──── Reopened ◄───────────┘  (재현되면 되돌린다)\n\n  └──> Won't Fix / Duplicate / Cannot Reproduce / Not a Bug  (닫히는 다른 경로)\n```\n\n**QA가 실제로 신경 쓰는 지점은 두 군데다.**\n\n1. **Resolved → Closed 로 넘기는 판단** — 개발자가 \"고쳤다\"고 하면 QA가 확인하고 닫는다. 이때 원래 재현 절차 그대로 재현해 보고, **주변 회귀까지** 본다. 고치면서 다른 걸 깨뜨리는 일이 흔하다\n2. **Cannot Reproduce 로 되돌아온 티켓** — 대부분 리포트에 정보가 부족했던 것이다. 앞 트랙의 결함 리포트 레슨이 여기서 값을 한다\n\n**필드 중 실무에서 중요한 것들**\n\n| 필드 | QA가 쓰는 이유 |\n|---|---|\n| Priority / Severity | 처리 순서. 두 필드를 다 쓰는 팀도, 하나만 쓰는 팀도 있다 |\n| Affects Version | **어느 버전에서 발견됐는가** — 회귀인지 신규인지 판단 |\n| Fix Version | 어느 릴리즈에 포함되는가 — 릴리즈 노트가 여기서 자동 생성된다 |\n| Component | 담당 팀 자동 배정, 결함 밀도 집계의 단위 |\n| Labels | `regression`, `flaky`, `escaped` 같은 분류. 나중에 통계를 낼 수 있다 |\n| Linked Issues | `blocks`, `is caused by`, `relates to` — 원인 티켓 연결 |\n\n**`escaped` 라벨을 습관화하면** 앞 트랙의 결함 탈출률을 JQL 한 줄로 계산할 수 있다. 지표를 만들려면 데이터를 남기는 습관이 먼저다.\n\n### JQL — 이걸 쓸 줄 알아야 Jira를 쓰는 것이다\n\nJQL(Jira Query Language)은 SQL과 비슷한 이슈 검색 문법이다. **JQL을 못 쓰면 매번 화면을 뒤지느라 시간을 버린다.**\n\n```sql\n-- 내가 리포트했는데 아직 안 닫힌 것\nreporter = currentUser() AND status not in (Closed, Done) ORDER BY priority DESC\n\n-- 이번 릴리즈에 포함되는 미해결 Critical 이상 (Go/No-Go 회의 준비용)\nfixVersion = \"3.4.0\" AND priority in (Blocker, Critical) AND status != Closed\n\n-- QA 확인 대기 중인 것 (내가 지금 해야 할 일)\nstatus = Resolved AND reporter = currentUser()\n\n-- 최근 30일간 운영에서 탈출한 결함 (탈출률 계산용)\nlabels = escaped AND created >= -30d\n\n-- 결제 컴포넌트에서 재발한 결함\ncomponent = \"Payment\" AND status changed FROM Closed TO Reopened\n```\n\n마지막 쿼리의 `status changed FROM ... TO ...` 가 강력하다. **결함 재발률**을 이걸로 뽑는다.\n\n이런 쿼리를 대시보드 위젯으로 저장해두면 매일 아침 확인할 화면이 만들어진다.\n\n### Confluence / Notion — 문서\n\n이슈 트래커는 \"지금 처리 중인 일\", 문서 도구는 \"쌓여서 참조되는 것\"을 담는다. QA가 이곳에 남기는 문서는 보통 다섯 가지다.\n\n| 문서 | 갱신 주기 | 핵심 |\n|---|---|---|\n| 테스트 전략 | 분기~연 | 조직 차원. 자동화 기준, 환경 정책, 결함 등급 정의 |\n| 릴리즈별 테스트 계획 | 릴리즈마다 | 트랙 1의 7항목 |\n| 테스트 케이스 / RTM | 기능마다 | 요구사항 ↔ TC 매핑. 커버리지의 근거 |\n| 릴리즈 리포트 | 릴리즈마다 | 실행 현황, 잔여 결함, Go/No-Go 근거, 회고 |\n| 트러블슈팅 / 환경 가이드 | 상시 | 테스트 계정, 환경 접속법, 자주 겪는 문제 |\n\n마지막 항목을 잘 관리하는 QA가 팀에서 신뢰를 받는다. **\"그거 어떻게 하는 거였죠?\"에 링크 하나로 답하는 사람**이 되기 때문이다.\n\n문서 작성 원칙 하나만 기억하면 된다. **문서는 최신이 아니면 해롭다.** 틀린 문서는 없는 문서보다 나쁘다. 그래서 유지할 수 없는 문서는 아예 만들지 않는 게 낫고, 만든 문서에는 \"최종 확인일\"과 \"담당\"을 반드시 남긴다.\n\n### Slack — QA의 실제 커뮤니케이션\n\n여기서 실력 차이가 크게 난다. 같은 내용도 어떻게 쓰느냐에 따라 팀의 시간이 달라진다.\n\n**나쁜 예**\n\n> 결제가 안 되는데요?\n\n**좋은 예**\n\n> 🔴 **[스테이징] 결제 실패 — 확인 요청**\n> - 증상: 카드 결제 시 \"일시적 오류\" 후 주문 미생성\n> - 재현: 10회 중 10회 (계정 qa_user_01)\n> - 발생 시각: 14:32 ~ 현재\n> - 확인한 것: 다른 계정·다른 카드에서도 동일 / 어제 16시 배포 이후로 추정\n> - 티켓: PROJ-1423\n> - **필요한 것**: 결제 서버 로그 14:30~14:40 확인 부탁드립니다 (@개발자)\n\n차이는 세 가지다. **(1) 이미 확인한 것을 명시**해서 중복 조사를 막고, **(2) 무엇이 필요한지 구체적으로 요청**하고, **(3) 티켓 링크로 맥락을 연결**한다.\n\n실무 팁 몇 가지.\n\n- **스레드를 쓴다.** 채널이 스크롤 지옥이 되면 아무도 안 읽는다\n- **긴급도를 이모지나 접두어로 표시한다.** 🔴 차단 / 🟡 확인 필요 / 🟢 정보 공유\n- **DM 대신 채널**을 쓴다. DM으로 해결한 문제는 팀의 자산이 되지 않고, 같은 질문이 반복된다\n- **CI 실패, 배포 알림을 채널로 받는다.** (트랙 3에서 GitHub Actions → Slack 알림을 붙인다)\n\n### 도구를 연결하면 손이 줄어든다\n\n무료 범위에서 할 수 있는 자동화들이다.\n\n```text\nGitHub PR 머지  ──> Jira 티켓 자동 In Review 전환 (커밋 메시지에 PROJ-1423 포함)\nCI 테스트 실패   ──> Slack 알림 + 실패 리포트 링크\nJira 티켓 생성   ──> Slack 채널 알림\nConfluence 문서 ──> Jira 이슈 목록 매크로로 실시간 임베드\n```\n\n첫 줄이 특히 유용하다. **커밋 메시지에 티켓 번호를 넣는 습관**만으로 코드 변경과 결함이 자동 연결되고, 나중에 \"이 결함은 어느 커밋에서 생겼나\"를 추적할 수 있다.\n\n## 왜 채용시장이 요구하는가\n\n- 채용공고의 \"Jira, Confluence 사용 경험\"은 **거의 모든 공고에 있는 기본 항목**이라 없으면 서류에서 걸린다. 다만 이건 변별력이 없는 항목이기도 하다.\n- **변별력은 JQL에서 난다.** 면접에서 \"Jira에서 데이터를 어떻게 뽑으셨나요?\"를 물었을 때 JQL 쿼리를 말할 수 있으면 \"도구를 쓰는 사람\"이 아니라 \"도구로 관리하는 사람\"으로 보인다.\n- **비동기 커뮤니케이션 능력**이 원격·하이브리드 환경에서 크게 평가된다. Slack 메시지 한 통에서 그 사람이 남의 시간을 아껴주는 사람인지가 드러난다.\n- AI 도구들이 티켓 초안을 대신 써주는 시대지만, **무엇을 이미 확인했고 무엇이 필요한지**는 사람만 안다. AI가 쓴 티켓을 그대로 올리면 \"확인하지 않은 것을 확인한 것처럼\" 적히는 사고가 난다.\n\n## 실습 과제\n\n### 과제 1 — 무료로 Jira 환경 만들기 (10분)\n\nJira Cloud는 **10명까지 무료**다. 개인 학습용으로 하나 만든다.\n\n1. Jira Cloud 무료 플랜으로 사이트 생성, 스크럼 또는 칸반 프로젝트 하나 생성\n2. Bug 이슈 타입의 워크플로를 확인 — 기본 상태가 무엇인지 본다\n3. 트랙 1의 결함 리포트 과제에서 쓴 결함 2건을 실제 티켓으로 등록\n4. 한 건을 Resolved → Closed 까지 직접 옮겨보고, 다른 한 건은 Reopened 시켜본다\n\n### 과제 2 — JQL 5개 작성 (12분)\n\n본인 프로젝트에서 아래를 뽑는 JQL을 직접 작성해 실행한다. (결과가 0건이어도 문법이 통과하면 성공)\n\n| # | 뽑을 것 |\n|---|---|\n| 1 | 내가 만들었고 아직 안 닫힌 이슈, 우선순위 높은 순 |\n| 2 | 최근 7일 내 생성된 Bug |\n| 3 | Resolved 상태로 3일 이상 방치된 이슈 |\n| 4 | 특정 라벨(`escaped`)이 붙은 이슈 |\n| 5 | Closed 에서 Reopened 로 상태가 바뀐 적 있는 이슈 |\n\n3번이 실무에서 특히 쓸모 있다. **QA 확인 대기 중인데 잊힌 티켓**을 잡아낸다.\n\n### 과제 3 — Slack 메시지 다시 쓰기 (8분)\n\n아래 메시지를 좋은 예의 형식으로 다시 쓴다. 부족한 정보는 **\"이걸 먼저 확인하고 보내겠다\"** 로 표시한다.\n\n> 앱에서 로그인이 자꾸 풀리는데 이거 왜 이러죠? 아까부터 그러네요\n\n### 과제 4 — AI로 티켓 초안 만들고 검증 (10분)\n\nAI 실습 도우미의 **결함 리포트 정리** 템플릿으로 티켓 본문을 만든 뒤, 다음을 확인한다.\n\n- 내가 말하지 않은 환경 정보(브라우저 버전, OS 버전)를 채워 넣었는가\n- Affects Version / Component 를 임의로 지정했는가\n- \"재현율 100%\" 처럼 내가 세어보지 않은 숫자를 단정했는가\n\n**AI가 채운 필드 중 내가 실제로 확인한 것만 남기고 나머지는 지운다.** 그 상태가 제출 가능한 티켓이다.\n\n## 자가 체크리스트\n\n- [ ] Epic / Story / Task / Sub-task / Bug 의 계층을 설명할 수 있다\n- [ ] 결함 티켓의 표준 워크플로와 Reopened 가 발생하는 이유를 설명할 수 있다\n- [ ] Resolved → Closed 로 넘기기 전에 주변 회귀까지 확인해야 하는 이유를 안다\n- [ ] Affects Version 과 Fix Version 의 차이와 각각의 용도를 안다\n- [ ] JQL 로 \"내가 확인해야 할 이슈\"를 뽑는 쿼리를 쓸 수 있다\n- [ ] `status changed FROM Closed TO Reopened` 로 결함 재발을 추적할 수 있다\n- [ ] 라벨을 남겨두면 나중에 지표를 계산할 수 있다는 걸 이해하고 습관화한다\n- [ ] QA가 문서 도구에 남기는 5가지 문서를 나열할 수 있다\n- [ ] \"틀린 문서는 없는 문서보다 나쁘다\"의 의미를 설명하고 최종 확인일을 남긴다\n- [ ] Slack 이슈 공유 메시지에 (이미 확인한 것 / 필요한 것 / 티켓 링크)를 포함시킨다\n- [ ] 커밋 메시지에 티켓 번호를 넣으면 무엇이 가능해지는지 설명할 수 있다\n- [ ] AI가 만든 티켓에서 확인하지 않은 정보를 걸러낼 수 있다\n\n## 참고 링크\n\n- [Jira Cloud 무료 플랜](https://www.atlassian.com/software/jira/free) — 10명까지 무료. 개인 학습용으로 충분하다\n- [JQL 문법 레퍼런스](https://support.atlassian.com/jira-software-cloud/docs/use-advanced-search-with-jira-query-language-jql/) — 함수와 연산자 전체 목록\n- [Atlassian — Bug Tracking 가이드](https://www.atlassian.com/software/jira/guides/bug-tracking) — 워크플로 설계 관점\n- [Notion 개인 무료 플랜](https://www.notion.com/pricing) — 개인 사용은 무료. 테스트 케이스 DB를 표로 관리하기 좋다\n","t2-l02":"---\nid: t2-l02\ntitle: API 테스트 (1) — HTTP 기초와 Postman 응답 검증\nsummary: 화면 없이 서버를 직접 두드려 본다. 상태코드·헤더·바디를 무엇을 기준으로 검증할지 정하고 Postman 테스트 스크립트로 옮긴다.\nminutes: 20\norder: 2\ntags: [API테스트, Postman, HTTP, 상태코드, Insomnia]\n---\n\n## 개념 설명\n\n### 왜 UI가 아니라 API를 테스트하는가\n\n같은 결함을 API에서 잡으면 UI에서 잡는 것보다 **빠르고, 안정적이고, 원인이 명확하다.**\n\n| | UI 테스트 | API 테스트 |\n|---|---|---|\n| 실행 속도 | 수십 초 | 수십 밀리초 |\n| 깨지는 원인 | 렌더링, 애니메이션, 셀렉터 변경 | 계약(스펙) 변경 |\n| 결함 위치 | 프론트인지 백엔드인지 불명확 | 백엔드로 특정됨 |\n| 만들 수 있는 상황 | 화면에서 가능한 것만 | **화면에서 불가능한 요청도 가능** |\n\n마지막 행이 핵심이다. **UI는 잘못된 입력을 막는다. 그래서 UI로만 테스트하면 서버 검증이 없는 것을 발견할 수 없다.**\n\n트랙 1의 상태전이 레슨에서 \"불가 전이를 API로 직접 호출해 확인하라\"고 했던 게 이것이다. 버튼을 숨겨놓고 서버 검증을 빼먹은 코드는 **UI 테스트를 아무리 돌려도 통과한다.** 그리고 운영에서 뚫린다.\n\n### HTTP 요청의 구조\n\n```http\nPOST /api/v1/orders HTTP/1.1\nHost: api.example.com\nContent-Type: application/json\nAuthorization: Bearer eyJhbGciOi...\nIdempotency-Key: 8f14e45f-ceea-467a-9e1e-3a2b1c0d9f77\n\n{\n  \"productId\": 10023,\n  \"quantity\": 2,\n  \"couponCode\": \"WELCOME10\"\n}\n```\n\n| 구성 | QA가 봐야 할 것 |\n|---|---|\n| 메서드 | GET은 조회만(부수효과 없어야 함), POST는 생성, PUT/PATCH는 수정, DELETE는 삭제 |\n| 경로 | 버전(`/v1/`), 리소스 이름, path 파라미터 |\n| 헤더 | 인증, Content-Type, 그리고 **커스텀 헤더** |\n| 바디 | 필드명·타입·필수 여부 |\n\n`Idempotency-Key` 같은 헤더가 보이면 **\"같은 요청을 두 번 보내면 어떻게 되는가\"** 를 반드시 테스트해야 한다는 신호다. 결제 중복 방지 장치이므로, 이게 실제로 동작하는지 확인하는 건 QA의 일이다.\n\n### 상태코드 — 외우지 말고 분류로 이해한다\n\n```text\n2xx 성공     200 OK / 201 Created / 204 No Content\n3xx 리다이렉트 301 영구이동 / 302 임시 / 304 Not Modified(캐시)\n4xx 클라이언트 잘못  ← 요청을 고쳐야 함\n5xx 서버 잘못        ← 서버를 고쳐야 함\n```\n\n**4xx / 5xx 구분이 실무에서 가장 중요하다.** 잘못된 입력을 보냈는데 서버가 500을 주면 그 자체가 결함이다. \"검증하지 않고 그냥 터진 것\"이기 때문이다.\n\nQA가 자주 마주치는 4xx들.\n\n| 코드 | 의미 | 이 코드가 나와야 정상인 상황 |\n|---|---|---|\n| 400 Bad Request | 요청 형식이 잘못됨 | 필수 필드 누락, 타입 오류 |\n| 401 Unauthorized | **인증 안 됨** | 토큰 없음, 만료된 토큰 |\n| 403 Forbidden | **인증은 됐으나 권한 없음** | 남의 주문 조회 시도 |\n| 404 Not Found | 리소스 없음 | 존재하지 않는 ID |\n| 409 Conflict | 상태 충돌 | 이미 취소된 주문을 또 취소 |\n| 422 Unprocessable | 형식은 맞으나 의미가 틀림 | 수량 -1, 과거 날짜 예약 |\n| 429 Too Many Requests | 요청 과다 | 레이트 리밋 동작 확인 |\n\n**401과 403의 구분**은 면접 단골이다. \"너 누구야\"(401)와 \"너인 건 알겠는데 안 돼\"(403)의 차이다.\n\n**보안 관점의 함정**: 남의 데이터를 조회했을 때 404를 주는 게 나은가 403이 나은가? 403을 주면 **\"그 ID는 존재한다\"는 정보가 새어나간다.** 민감한 리소스는 일부러 404를 주기도 한다. 이런 판단이 있었는지 확인하는 것도 QA의 몫이다.\n\n### 무엇을 검증할 것인가 — 4개 층\n\n응답을 받았을 때 볼 것을 층으로 나눠 두면 빠뜨리지 않는다.\n\n```text\n1층 상태코드   기대한 코드가 왔는가\n2층 헤더       Content-Type, 캐시 정책, 보안 헤더, 커스텀 헤더\n3층 바디 구조  필드가 다 있는가, 타입이 맞는가, null 허용 여부\n4층 바디 값    비즈니스 규칙대로 계산됐는가  ← 여기가 진짜 검증\n```\n\n**대부분의 사람이 1층에서 멈춘다.** `200 OK`가 왔다고 통과 처리하는 테스트는 사실상 \"서버가 살아있다\"만 확인한 것이다.\n\n4층의 예를 들면 이렇다.\n\n```text\n주문 생성 응답에서 확인할 것\n  □ status = \"PENDING\" (생성 직후 상태가 맞는가)\n  □ totalAmount = 상품가격 × 수량 - 할인액   ← 직접 계산해서 비교\n  □ couponApplied = true 이고 discountAmount > 0\n  □ createdAt 이 현재 시각과 몇 초 이내인가\n  □ orderId 형식이 규칙에 맞는가\n  □ 응답에 내부 정보(내부 사용자 ID, SQL 오류, 스택 트레이스)가 새지 않는가\n```\n\n마지막 항목은 보안 검증이다. 에러 응답에 스택 트레이스가 그대로 나오는 서비스가 실제로 흔하다.\n\n### Postman 사용 흐름\n\n**컬렉션 → 폴더 → 요청** 구조로 정리한다. 폴더는 기능 단위로 나눈다.\n\n```text\n[컬렉션] 이커머스 API\n ├─ 00_auth\n │   └─ 로그인 (토큰 발급)\n ├─ 01_products\n │   ├─ 상품 목록 조회\n │   └─ 상품 상세 조회\n └─ 02_orders\n     ├─ 주문 생성\n     ├─ 주문 조회\n     └─ 주문 취소\n```\n\n**환경(Environment) 변수**로 서버 주소와 토큰을 분리한다. 이걸 안 하면 스테이징과 운영을 오갈 때마다 URL을 다 고쳐야 한다.\n\n```text\n{{baseUrl}}   → https://staging-api.example.com\n{{token}}     → (로그인 요청이 자동으로 채운다)\n{{orderId}}   → (주문 생성이 자동으로 채운다)\n```\n\n로그인 응답에서 토큰을 꺼내 변수에 저장하는 스크립트를 **Scripts(Post-response)** 탭에 넣는다.\n\n```javascript\n// 로그인 요청의 응답 후 스크립트\nconst body = pm.response.json();\npm.environment.set(\"token\", body.accessToken);\n```\n\n이후 요청들의 Authorization 헤더에 `Bearer {{token}}` 을 쓰면 토큰이 자동으로 흐른다.\n\n### Postman 테스트 스크립트 — 4개 층을 코드로\n\n```javascript\n// 주문 생성 요청의 Post-response 스크립트\nconst body = pm.response.json();\n\n// 1층 — 상태코드\npm.test(\"201 Created 로 응답한다\", () => {\n  pm.response.to.have.status(201);\n});\n\n// 2층 — 헤더\npm.test(\"JSON 으로 응답한다\", () => {\n  pm.expect(pm.response.headers.get(\"Content-Type\")).to.include(\"application/json\");\n});\n\n// 3층 — 바디 구조와 타입\npm.test(\"응답에 필수 필드가 모두 있다\", () => {\n  pm.expect(body).to.have.property(\"orderId\").that.is.a(\"string\");\n  pm.expect(body).to.have.property(\"status\").that.is.a(\"string\");\n  pm.expect(body).to.have.property(\"totalAmount\").that.is.a(\"number\");\n});\n\n// 4층 — 비즈니스 규칙 (여기가 핵심)\npm.test(\"10% 쿠폰이 적용된 금액이 맞다\", () => {\n  const expected = Math.floor(body.unitPrice * body.quantity * 0.9);\n  pm.expect(body.totalAmount).to.eql(expected);\n});\n\npm.test(\"생성 직후 상태는 PENDING 이다\", () => {\n  pm.expect(body.status).to.eql(\"PENDING\");\n});\n\npm.test(\"응답에 내부 정보가 노출되지 않는다\", () => {\n  const raw = pm.response.text();\n  pm.expect(raw).to.not.include(\"SQLException\");\n  pm.expect(raw).to.not.include(\"internalUserId\");\n});\n\n// 다음 요청을 위해 orderId 를 넘긴다\npm.environment.set(\"orderId\", body.orderId);\n```\n\n**가짜 통과를 만드는 안티패턴**을 조심한다. 트랙 6에서 다시 다룬다.\n\n```javascript\n// 나쁨 — 200 이든 400 이든 통과한다\npm.test(\"응답 받음\", () => {\n  pm.expect(pm.response.code).to.be.oneOf([200, 201, 400, 404]);\n});\n\n// 나쁨 — 아무것도 검증하지 않는다\npm.test(\"주문 생성\", () => {\n  pm.expect(body).to.be.an(\"object\");\n});\n```\n\n### Insomnia · Bruno — 대안\n\n| 도구 | 특징 | 비용 |\n|---|---|---|\n| Postman | 사실상 표준. 팀 기능·모니터·목서버 풍부 | 개인 무료 티어 |\n| Insomnia | 가볍고 UI가 단순. GraphQL 지원이 좋다 | 무료 티어 |\n| Bruno | **컬렉션을 파일로 저장** → git 으로 버전관리·PR 리뷰 가능. 오프라인 우선 | 오픈소스 |\n\nBruno의 \"컬렉션이 그냥 파일\"이라는 점은 실무에서 꽤 큰 장점이다. **API 테스트를 코드 리뷰에 태울 수 있다.**\n\n## 왜 채용시장이 요구하는가\n\n- **API 테스트는 QA 채용공고에서 자동화 다음으로 자주 등장한다.** Postman 사용 경험은 거의 필수 항목이다.\n- 면접에서 **\"UI 테스트로는 못 잡고 API 테스트로만 잡을 수 있는 결함의 예를 들어보세요\"** 가 나온다. 답은 \"UI에서 막아둔 요청을 서버가 검증하지 않는 경우\"다.\n- **401 / 403 / 404 구분**, **4xx vs 5xx 판단**은 개발자와 대화하는 최소 어휘다. 이게 안 되면 \"프론트 문제인지 백엔드 문제인지\" 스스로 판단할 수 없다.\n- **AI가 만든 API 테스트의 대부분이 1층에서 멈춘다.** 상태코드만 확인하고 통과시키는 테스트를 대량 생산한다. 4층 검증이 있는지 확인하는 게 사람의 일이다.\n\n## 실습 과제\n\n### 과제 1 — 공개 API로 4층 검증 연습 (15분)\n\n무료 연습용 API를 쓴다. 회원가입도 필요 없다.\n\n- `https://httpbin.org` — 요청을 그대로 되돌려준다. 헤더·상태코드 실험에 최적\n- `https://jsonplaceholder.typicode.com` — 가짜 REST API (posts, users, comments)\n\nPostman에 컬렉션을 만들고 다음을 수행한다.\n\n1. `GET https://jsonplaceholder.typicode.com/posts/1` — 4개 층 각각에 테스트 1개씩 작성\n2. `GET .../posts/9999` — 존재하지 않는 ID. **어떤 상태코드가 오는가?** 기대와 다르면 왜 그런지 적기\n3. `POST .../posts` 로 생성 요청 후 응답 검증\n4. `https://httpbin.org/status/500` 을 호출해 5xx 응답을 받아보고, 이런 응답이 왔을 때 QA가 무엇을 해야 하는지 메모에 적기\n\n### 과제 2 — 환경 변수와 토큰 자동 흐름 (12분)\n\n`https://httpbin.org/post` 를 로그인이라고 가정하고 연습한다.\n\n1. Environment를 만들고 `baseUrl` 변수 설정\n2. 요청 A의 응답에서 값을 꺼내 `pm.environment.set()` 으로 저장\n3. 요청 B에서 `{{변수}}` 로 그 값을 사용\n4. **요청 순서를 바꿔서 실행**해 보고 무엇이 깨지는지 확인 — 이게 다음 레슨의 \"테스트 간 의존성\" 문제다\n\n### 과제 3 — 서버 검증 뚫기 시나리오 설계 (10분)\n\n본인이 아는 서비스의 기능 하나를 골라, **UI로는 불가능하지만 API로는 가능한 요청 5개**를 설계한다.\n\n| # | UI 제약 | API로 우회하는 요청 | 서버가 막아야 할 것 |\n|---|---|---|---|\n| 1 | 수량 입력이 1~10으로 제한됨 | `quantity: 9999` 또는 `-1` | 422 반환 |\n| 2 | 배송중 주문은 취소 버튼이 없음 | 취소 API 직접 호출 | 409 반환 |\n| 3 | | | |\n\n이 표가 곧 **보안·무결성 TC 목록**이 된다.\n\n### 과제 4 — AI가 만든 API 테스트 채점 (10분)\n\nAI 실습 도우미에 아래를 요청한다.\n\n> 주문 생성 API(`POST /api/v1/orders`, 요청 필드 productId·quantity·couponCode, 응답 필드 orderId·status·unitPrice·quantity·discountAmount·totalAmount)에 대한 Postman 테스트 스크립트를 작성하라.\n\n받은 코드를 **4개 층 기준으로 채점**한다.\n\n| 층 | 있는가 | 비고 |\n|---|---|---|\n| 1층 상태코드 | | |\n| 2층 헤더 | | |\n| 3층 구조·타입 | | |\n| 4층 비즈니스 계산 | | ← 여기가 대체로 비어 있다 |\n| 가짜 통과 안티패턴 | | `oneOf([200,400])` 같은 것 |\n| 존재하지 않는 pm API 사용 | | 환각 점검 |\n\n## 자가 체크리스트\n\n- [ ] UI 테스트로는 잡을 수 없고 API 테스트로만 잡히는 결함의 유형을 설명할 수 있다\n- [ ] HTTP 요청의 4요소(메서드·경로·헤더·바디)를 구분하고 각각에서 볼 것을 안다\n- [ ] 4xx와 5xx의 의미 차이와, 잘못된 입력에 5xx가 오면 그 자체가 결함인 이유를 안다\n- [ ] 401과 403의 차이를 설명할 수 있다\n- [ ] 민감 리소스에서 403 대신 404를 주는 이유(존재 여부 노출 방지)를 설명할 수 있다\n- [ ] 409와 422가 나와야 정상인 상황을 각각 예로 들 수 있다\n- [ ] 응답 검증을 상태코드·헤더·구조·값 4개 층으로 나눠 설계할 수 있다\n- [ ] 4층(비즈니스 값) 검증을 직접 계산해서 비교하는 코드로 쓸 수 있다\n- [ ] 에러 응답에 스택 트레이스·내부 ID가 노출되는지 확인한다\n- [ ] Postman 환경 변수로 baseUrl·토큰을 분리하고 응답값을 다음 요청에 넘길 수 있다\n- [ ] `oneOf([200, 400])` 같은 가짜 통과 패턴을 알아보고 거부할 수 있다\n- [ ] Idempotency-Key 헤더를 보면 중복 요청 테스트가 필요하다고 판단할 수 있다\n\n## 참고 링크\n\n- [Postman Learning Center — Writing Tests](https://learning.postman.com/docs/tests-and-scripts/write-scripts/test-scripts/) — pm API 공식 문서. 환각 검증할 때 여기서 확인한다\n- [MDN — HTTP 상태 코드](https://developer.mozilla.org/ko/docs/Web/HTTP/Status) — 한국어. 코드별 정확한 의미\n- [httpbin.org](https://httpbin.org) — 무료 HTTP 요청 테스트 서버\n- [JSONPlaceholder](https://jsonplaceholder.typicode.com) — 무료 가짜 REST API\n- [Bruno](https://www.usebruno.com/) — 컬렉션을 파일로 관리하는 오픈소스 API 클라이언트\n","t2-l03":"---\nid: t2-l03\ntitle: API 테스트 (2) — Swagger 읽기와 컬렉션 러너·CI 연동\nsummary: OpenAPI 명세를 TC의 근거로 삼는 법. 그리고 컬렉션을 Newman으로 CI에서 자동 실행해 리포트를 받는다.\nminutes: 20\norder: 3\ntags: [Swagger, OpenAPI, Newman, 컬렉션러너, CI]\n---\n\n## 개념 설명\n\n### Swagger / OpenAPI 는 QA에게 무엇인가\n\nOpenAPI 명세(흔히 Swagger라고 부른다)는 **API의 계약서**다. QA 입장에서 이건 세 가지 의미를 갖는다.\n\n1. **TC의 근거 문서** — 요구사항 명세가 부실해도 여기엔 필드·타입·필수 여부가 적혀 있다\n2. **명세 결함을 찾는 대상** — 명세 자체가 틀렸거나 비어 있는 곳이 결함이다\n3. **테스트 자동 생성의 입력** — AI에게 명세를 주면 TC 초안을 뽑을 수 있다 (트랙 4)\n\n### 명세에서 무엇을 읽어야 하나\n\n```yaml\npaths:\n  /orders:\n    post:\n      summary: 주문 생성\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required: [productId, quantity]        # ← 필수 필드\n              properties:\n                productId:\n                  type: integer\n                quantity:\n                  type: integer\n                  minimum: 1\n                  maximum: 10                        # ← 경계값이 여기 있다\n                couponCode:\n                  type: string\n                  nullable: true                     # ← null 허용\n      responses:\n        '201': { description: 생성됨 }\n        '400': { description: 잘못된 요청 }\n        '409': { description: 재고 부족 }\n        # '401' 없음 ← 인증 실패 시 동작이 정의되지 않았다\n```\n\n**QA가 이 명세에서 뽑아내는 것들**\n\n| 명세의 항목 | 여기서 나오는 TC |\n|---|---|\n| `required: [productId, quantity]` | 각 필수 필드를 하나씩 뺀 요청 → 400 |\n| `minimum: 1, maximum: 10` | 0, 1, 10, 11 → **경계값 4건** |\n| `type: integer` | 문자열 `\"2\"`, 소수 `2.5`, null 투입 |\n| `nullable: true` | null 을 넣었을 때와 필드를 아예 뺐을 때가 **같게 동작하는가** |\n| 정의된 응답 코드 목록 | 각 코드가 실제로 그 상황에서 오는가 |\n| **정의되지 않은 응답 코드** | 401은 어떻게 되나? 429는? → **명세 결함으로 제기** |\n\n마지막 행이 QA의 부가가치다. **명세에 없는 것을 찾는 것**이 명세를 읽는 목적이다.\n\n명세에서 자주 발견되는 결함들.\n\n- 응답 예시(`example`)의 값이 실제 응답과 다르다\n- `required` 로 표시됐는데 실제로는 없어도 통과한다 (또는 그 반대)\n- 에러 응답의 스키마가 정의돼 있지 않다 → 프론트가 에러 처리를 못 한다\n- 페이징 파라미터의 최대값이 없다 → `size=100000` 을 보내면 서버가 죽는다\n- 날짜 형식이 명시되지 않았다 → 프론트와 백엔드가 다른 포맷을 가정한다\n\n### Swagger UI 로 바로 실험하기\n\nSwagger UI 화면의 **Try it out** 버튼으로 브라우저에서 즉시 호출할 수 있다. 별도 도구 없이 명세를 보면서 바로 찔러볼 수 있어서, **탐색적 API 테스트에 가장 빠른 경로**다.\n\n여기서 유용한 습관 하나. Try it out 으로 요청을 보내면 Swagger UI가 **동등한 curl 명령**을 보여준다. 그걸 복사해 두면 결함 리포트의 재현 절차로 그대로 붙여넣을 수 있다.\n\n```bash\ncurl -X POST \"https://api.example.com/orders\" \\\n  -H \"Content-Type: application/json\" \\\n  -H \"Authorization: Bearer eyJ...\" \\\n  -d '{\"productId\": 10023, \"quantity\": 11}'\n```\n\n**결함 리포트에 curl 한 줄이 들어가면 개발자의 재현 시간이 0에 수렴한다.** 트랙 1의 결함 리포트 레슨과 이어지는 지점이다. (단, 토큰은 마스킹하거나 별도로 전달한다)\n\n### OpenAPI 명세를 Postman 컬렉션으로 가져오기\n\nPostman은 OpenAPI 파일(JSON/YAML)이나 URL을 **Import** 하면 모든 엔드포인트를 컬렉션으로 만들어 준다. 요청을 손으로 하나씩 만들 필요가 없다.\n\n주의할 점: 자동 생성된 요청의 바디는 **명세의 example 값**이다. 실제로 동작하는 값이 아닐 수 있다. 그대로 실행하면 대부분 400이 난다. 이건 도구 문제가 아니라 **명세의 example이 최신이 아니라는 신호**이므로, 발견하면 결함으로 남긴다.\n\n### 컬렉션 러너 — 순서와 의존성\n\n컬렉션 전체를 순서대로 실행하는 기능이다. 여기서 실무의 핵심 문제가 나온다.\n\n```text\n로그인 → 주문 생성 → 주문 조회 → 주문 취소\n  토큰      orderId      확인       정리\n```\n\n이 흐름은 **앞 요청이 실패하면 뒤가 전부 무너진다.** 자동화 테스트의 고질병인 **테스트 간 의존성**이다.\n\n| 전략 | 장점 | 단점 |\n|---|---|---|\n| 순차 의존 (위 방식) | 실제 사용자 흐름과 같다 | 하나 깨지면 연쇄 실패, 원인 파악 어려움 |\n| 각 테스트가 자기 데이터를 준비 | 독립 실행 가능, 병렬 가능 | 준비 코드 중복, 느림 |\n| 사전 준비 데이터 고정 | 빠름 | 데이터가 오염되면 전부 실패 |\n\n실무에서는 **시나리오 단위로 묶고, 시나리오끼리는 독립**시키는 절충을 쓴다. \"주문 흐름\"은 순차로 두되, \"주문 흐름\"과 \"쿠폰 흐름\"은 서로 의존하지 않게 한다.\n\n**정리(cleanup)를 반드시 넣는다.** 테스트가 만든 주문을 취소하지 않으면 실행할 때마다 데이터가 쌓이고, 결국 다른 테스트가 깨진다.\n\nPostman에서 흐름을 제어하는 함수도 있다.\n\n```javascript\n// 재고가 없으면 이후 요청을 건너뛴다\nif (pm.response.code === 409) {\n  postman.setNextRequest(null);   // 실행 중단\n}\n\n// 조건에 따라 특정 요청으로 점프\npostman.setNextRequest(\"주문 취소\");\n```\n\n### Newman — CI에서 컬렉션 자동 실행\n\nNewman은 **Postman 컬렉션을 커맨드라인에서 실행**하는 공식 CLI다. 무료이고, 이게 있어야 API 테스트가 CI에 들어간다.\n\n```bash\nnpm install -g newman newman-reporter-htmlextra\n\nnewman run collection.json \\\n  -e staging.postman_environment.json \\\n  --reporters cli,junit,htmlextra \\\n  --reporter-junit-export results/junit.xml \\\n  --reporter-htmlextra-export results/report.html\n```\n\n- `junit.xml` — CI 도구가 읽어서 테스트 결과 탭에 표시한다\n- `htmlextra` — 사람이 보는 리포트. 실패한 요청의 request/response 원문이 다 들어있다\n\n**GitHub Actions 에서 돌리기** (public 저장소는 무제한 무료)\n\n```yaml\nname: API Tests\n\non:\n  pull_request:\n  schedule:\n    - cron: '0 22 * * 0-4'   # UTC 22시 = KST 평일 07시\n\njobs:\n  api-test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: '20'\n\n      - name: Newman 설치\n        run: npm install -g newman newman-reporter-htmlextra\n\n      - name: 컬렉션 실행\n        run: |\n          newman run tests/api/collection.json \\\n            -e tests/api/staging.env.json \\\n            --env-var \"apiKey=$API_KEY\" \\\n            --reporters cli,junit,htmlextra \\\n            --reporter-junit-export results/junit.xml \\\n            --reporter-htmlextra-export results/report.html\n        env:\n          API_KEY: ${{ secrets.API_KEY }}\n\n      - name: 리포트 업로드\n        if: always()          # 실패해도 리포트는 남긴다\n        uses: actions/upload-artifact@v4\n        with:\n          name: newman-report\n          path: results/\n```\n\n두 가지를 눈여겨본다.\n\n- **`env` 와 `secrets`** — API 키를 컬렉션 파일에 넣으면 저장소에 커밋된다. 반드시 Secrets 로 분리하고 `--env-var` 로 주입한다\n- **`if: always()`** — 이게 없으면 테스트 실패 시 리포트 업로드 단계가 건너뛰어져서 **정작 실패했을 때 원인을 볼 수 없다.** 실무에서 자주 하는 실수다\n\n### API 테스트를 어디까지 자동화할 것인가\n\n전부 자동화하는 게 답은 아니다. 판단 기준은 트랙 3에서 자세히 다루지만, API 한정으로 보면 이렇다.\n\n| 자동화 우선순위 | 대상 |\n|---|---|\n| 높음 | 인증, 핵심 트랜잭션(주문·결제), 권한 검증, 계약(스키마) 검증 |\n| 중간 | 경계값·유효성 검증 (변경이 잦지 않은 것) |\n| 낮음 | 자주 바뀌는 신규 기능, 외부 연동에 강하게 의존하는 흐름 |\n\n**권한 검증은 반드시 자동화한다.** 사람이 매번 \"남의 주문 조회해 보기\"를 손으로 하지 않게 되고, 그러면 언젠가 뚫린다.\n\n## 왜 채용시장이 요구하는가\n\n- 채용공고에 \"Swagger 기반 API 테스트\", \"API 문서 이해\" 가 자주 등장한다. **명세를 읽고 TC를 뽑는 능력**을 묻는 것이다.\n- **Newman + CI 연동 경험은 변별력이 크다.** Postman으로 수동 호출만 해본 사람과, CI에 붙여 매일 자동 실행되게 만든 사람은 다른 등급으로 평가된다. 트랙 3의 CI/CD 연동과 이어진다.\n- **API 명세는 AI 테스트 생성의 가장 좋은 입력**이다. 트랙 4에서 명세와 PR diff를 넣어 TC를 생성하는 실습을 하는데, 그때 \"명세의 어디가 비어 있는지\" 알아야 AI 출력의 빈틈이 보인다.\n- AI에게 OpenAPI 명세를 주면 TC를 잘 만든다. 다만 **명세에 없는 응답 코드나 제약을 물어보는 일은 하지 않는다.** 그 질문이 사람의 몫이다.\n\n## 실습 과제\n\n### 과제 1 — Swagger 명세에서 TC 뽑기 (15분)\n\n무료 공개 명세로 연습한다. **Swagger Petstore** (`https://petstore3.swagger.io`) 는 Try it out 까지 되는 공식 데모다.\n\n1. `POST /pet` 의 요청 스키마를 열어 필수 필드와 타입을 확인\n2. 명세만 보고 TC 12건을 설계 — 필수 필드 누락, 타입 오류, 경계값, 정의된 응답 코드별로\n3. **명세에 정의되지 않은 상황 3개**를 찾아 질문 목록으로 정리\n   (예: 인증 실패 시 응답은? 같은 pet을 두 번 등록하면? 이름에 이모지를 넣으면?)\n4. Try it out 으로 3개를 실제 호출해 보고, **명세와 실제 동작이 다른 곳**을 찾는다\n\n### 과제 2 — OpenAPI → Postman 컬렉션 (10분)\n\n1. Petstore 명세 URL을 Postman에 Import\n2. 자동 생성된 요청 하나를 그대로 실행해 보고 결과 기록\n3. 실패했다면 **왜 실패했는지** 분석 (example 값이 최신이 아닌가? 인증이 필요한가?)\n4. 4층 검증 스크립트를 붙여 통과시키기\n\n### 과제 3 — 흐름 컬렉션 만들고 러너로 실행 (15분)\n\n`https://jsonplaceholder.typicode.com` 로 3단계 흐름을 만든다.\n\n```text\n1. POST /posts        → 생성, 응답의 id 를 변수에 저장\n2. GET  /posts/{{id}} → 저장한 id 로 조회\n3. DELETE /posts/{{id}} → 정리\n```\n\n그다음 **일부러 깨뜨려 본다.**\n\n- 1번 요청의 변수 저장 코드를 지우고 러너 실행 → 2번이 어떻게 실패하는가\n- 2번을 먼저 실행되게 순서를 바꾸면 어떻게 되는가\n- 이 실패 메시지만 보고 원인을 알 수 있는가?\n\n**여기서 느끼는 불편함이 \"테스트 간 의존성\" 문제의 실체**다. 무엇을 개선하면 좋을지 메모에 적는다.\n\n### 과제 4 — Newman 로컬 실행 (10분)\n\n과제 3의 컬렉션을 export 하고 로컬에서 실행한다.\n\n```bash\nnpm install -g newman\nnewman run collection.json --reporters cli,json --reporter-json-export result.json\n```\n\n- 종료 코드(`echo $?`)를 확인한다 — 실패 시 0이 아니어야 CI가 빌드를 실패시킬 수 있다\n- `result.json` 을 열어 어떤 정보가 담기는지 본다\n\n### 과제 5 — AI가 만든 워크플로 검증 (10분)\n\nAI 실습 도우미에 요청한다.\n\n> Postman 컬렉션을 GitHub Actions에서 Newman으로 매일 실행하고 리포트를 아티팩트로 남기는 워크플로 YAML을 작성하라.\n\n받은 YAML을 **다음 기준으로 검증**한다.\n\n| 확인 항목 | 결과 |\n|---|---|\n| API 키를 Secrets 로 분리했는가, 아니면 하드코딩했는가 | |\n| 실패 시에도 리포트를 업로드하는가 (`if: always()`) | |\n| cron 시간대가 UTC 기준임을 반영했는가 | |\n| 존재하지 않는 액션 버전이나 옵션을 쓰지 않았는가 | |\n| `actions/upload-artifact` 버전이 유효한가 | |\n\n**AI는 `if: always()` 를 자주 빠뜨리고, cron을 KST로 착각한다.** 실제로 돌려보기 전에는 알 수 없는 종류의 결함이다.\n\n## 자가 체크리스트\n\n- [ ] OpenAPI 명세에서 필수 필드·타입·경계값을 읽어 TC로 옮길 수 있다\n- [ ] 명세에 **정의되지 않은 상황**을 찾아 명세 결함으로 제기할 수 있다\n- [ ] `nullable: true` 와 필드 누락이 다르게 동작할 수 있음을 알고 둘 다 테스트한다\n- [ ] Swagger UI의 Try it out 으로 탐색적 API 테스트를 수행할 수 있다\n- [ ] Swagger가 생성한 curl을 결함 리포트의 재현 절차로 활용할 수 있다 (토큰 마스킹 포함)\n- [ ] OpenAPI 명세를 Postman 컬렉션으로 가져올 수 있고, example 불일치를 결함으로 인식한다\n- [ ] 테스트 간 의존성의 세 가지 전략과 각각의 트레이드오프를 설명할 수 있다\n- [ ] 컬렉션에 정리(cleanup) 단계를 넣어야 하는 이유를 안다\n- [ ] Newman으로 컬렉션을 CLI 실행하고 junit/html 리포트를 생성할 수 있다\n- [ ] CI에서 API 키를 Secrets로 주입하고 컬렉션 파일에 넣지 않는다\n- [ ] `if: always()` 가 없으면 실패 시 리포트를 못 받는다는 걸 안다\n- [ ] 권한 검증 API 테스트를 자동화 우선순위 상위에 두는 이유를 설명할 수 있다\n\n## 참고 링크\n\n- [Swagger Petstore (공식 데모)](https://petstore3.swagger.io) — Try it out 가능한 무료 연습 대상\n- [OpenAPI 명세 3.1](https://spec.openapis.org/oas/latest.html) — 스키마 키워드의 정확한 의미\n- [Newman 공식 문서](https://learning.postman.com/docs/collections/using-newman-cli/command-line-integration-with-newman/) — CLI 옵션 전체\n- [newman-reporter-htmlextra](https://github.com/DannyDainton/newman-reporter-htmlextra) — 실무에서 가장 많이 쓰는 리포터\n- [GitHub Actions 문서](https://docs.github.com/en/actions) — public 저장소는 무료 무제한\n","t2-l04":"---\nid: t2-l04\ntitle: SQL (1) — QA를 위한 조회와 JOIN 읽기\nsummary: 화면 뒤에 실제로 저장된 값을 확인한다. SELECT·WHERE·JOIN을 '검증 도구'로 쓰는 법과 MySQL/MSSQL 차이.\nminutes: 20\norder: 4\ntags: [SQL, MySQL, MSSQL, DBeaver, 데이터검증]\n---\n\n## 개념 설명\n\n### QA가 SQL을 쓰는 세 가지 이유\n\n개발자처럼 쿼리를 짜기 위해서가 아니다. 목적이 다르다.\n\n1. **화면과 실제 데이터가 일치하는지 확인** — 화면엔 9,000원인데 DB엔 10,000원이 저장됐다면 결함이다\n2. **테스트 데이터를 만들고 상태를 세팅** — \"재고 1개 남은 상품\", \"휴면 회원 계정\"을 만들어야 테스트할 수 있다\n3. **결함의 원인 범위를 좁힘** — \"프론트가 잘못 보여주는 건가, 서버가 잘못 저장한 건가\"를 스스로 판단\n\n세 번째가 개발자와의 대화를 바꾼다. \"결제 금액이 이상해요\" 대신 **\"orders 테이블엔 9,000원으로 맞게 들어갔는데 화면엔 10,000원이 뜹니다. 프론트 쪽으로 보입니다\"** 라고 말할 수 있다.\n\n### 읽어야 할 SQL, 쓸 수 있어야 할 SQL\n\nQA에게 필요한 범위는 명확하다.\n\n| 구분 | 범위 |\n|---|---|\n| **반드시 쓸 수 있어야** | SELECT, WHERE, ORDER BY, LIMIT, COUNT/SUM/AVG, GROUP BY, JOIN(INNER/LEFT) |\n| **읽을 수 있어야** | 서브쿼리, HAVING, CASE WHEN, 윈도우 함수(있으면 알아보는 정도) |\n| **알되 함부로 쓰면 안 됨** | INSERT, UPDATE, DELETE ← 뒤에서 다룬다 |\n\n### SELECT — 검증의 출발점\n\n```sql\n-- 주문 한 건이 어떻게 저장됐는지 확인\nSELECT order_id, user_id, status, total_amount, discount_amount, created_at\nFROM orders\nWHERE order_id = 'ORD-20260815-0001';\n```\n\n**QA가 조회할 때의 습관 세 가지**\n\n1. **`SELECT *` 를 쓰지 않는다.** 필요한 컬럼만 적는다. 컬럼이 100개인 테이블에서 눈으로 찾는 건 시간 낭비이고, 개인정보 컬럼까지 불필요하게 화면에 띄우게 된다\n2. **항상 LIMIT을 붙인다.** 운영 DB에서 `WHERE` 없는 조회를 날리면 서비스가 느려진다\n3. **`created_at` 을 같이 본다.** 언제 만들어진 데이터인지 모르면 내가 방금 만든 것인지 남의 것인지 구분이 안 된다\n\n```sql\n-- 좋은 습관\nSELECT order_id, status, total_amount, created_at\nFROM orders\nWHERE user_id = 12345\nORDER BY created_at DESC\nLIMIT 20;\n```\n\n### WHERE — 조건에서 자주 틀리는 것들\n\n```sql\n-- NULL 은 = 로 비교되지 않는다. 이건 항상 0건이다\nWHERE coupon_code = NULL          -- ✗\nWHERE coupon_code IS NULL         -- ✓\n\n-- NOT IN 에 NULL 이 섞이면 전체가 0건이 된다 (자주 당한다)\nWHERE user_id NOT IN (SELECT user_id FROM blacklist)              -- blacklist 에 NULL 있으면 0건\nWHERE user_id NOT IN (SELECT user_id FROM blacklist WHERE user_id IS NOT NULL)   -- ✓\n\n-- 날짜 범위: BETWEEN 은 양끝을 포함한다. 시각이 있는 컬럼에선 위험하다\nWHERE created_at BETWEEN '2026-08-01' AND '2026-08-31'\n-- → 8/31 00:00:00 까지만 포함. 8/31 하루가 통째로 빠진다\nWHERE created_at >= '2026-08-01' AND created_at < '2026-09-01'    -- ✓ 이렇게 쓴다\n```\n\n**세 번째가 실무에서 가장 자주 나오는 데이터 결함**이다. 월별 집계 리포트에서 매달 마지막 날이 빠지는 버그가 여기서 나온다. 트랙 1의 경계값 분석이 SQL에서도 그대로 적용된다.\n\n문자열 비교의 함정도 있다.\n\n```sql\n-- 대소문자 구분 여부는 DB 설정(collation)에 따라 다르다\nWHERE email = 'QA@Example.com'    -- MySQL 기본 설정에선 대소문자 무시, MSSQL은 설정에 따라 다름\n\n-- 앞뒤 공백\nWHERE name = '홍길동 '            -- 눈에 안 보이는 공백 때문에 0건\nWHERE TRIM(name) = '홍길동'       -- 확인용으로는 이렇게\n```\n\n\"분명 데이터가 있는데 조회가 안 돼요\"의 90%가 NULL, 공백, 대소문자, 날짜 경계 중 하나다.\n\n### JOIN — 여러 테이블을 이어 검증하기\n\nQA가 실제로 필요한 JOIN은 두 가지뿐이다.\n\n```sql\n-- INNER JOIN: 양쪽에 다 있는 것만\nSELECT o.order_id, o.total_amount, u.email, p.name AS product_name\nFROM orders o\nINNER JOIN users u    ON o.user_id = u.user_id\nINNER JOIN order_items oi ON o.order_id = oi.order_id\nINNER JOIN products p ON oi.product_id = p.product_id\nWHERE o.order_id = 'ORD-20260815-0001';\n```\n\n```sql\n-- LEFT JOIN: 왼쪽은 전부, 오른쪽은 있으면 붙인다\n-- → 오른쪽이 NULL 인 행을 찾으면 \"짝이 없는 데이터\"를 발견할 수 있다\nSELECT o.order_id, o.status, p.payment_id\nFROM orders o\nLEFT JOIN payments p ON o.order_id = p.order_id\nWHERE o.status = 'PAID'\n  AND p.payment_id IS NULL;      -- ← 결제완료인데 결제 기록이 없는 주문\n```\n\n**LEFT JOIN + IS NULL 패턴이 QA에게 가장 강력한 무기다.** \"있어야 하는데 없는 것\"을 찾는 방법이기 때문이다. 다음 레슨에서 이 패턴을 정합성 검증으로 확장한다.\n\nJOIN에서 흔한 실수 하나.\n\n```sql\n-- 주문 1건인데 결과가 3행 나온다?\nSELECT o.order_id, o.total_amount\nFROM orders o\nJOIN order_items oi ON o.order_id = oi.order_id;\n-- → 주문에 상품이 3개 들어있으면 주문 행이 3번 반복된다 (1:N 관계)\n```\n\n이걸 모르고 `SUM(o.total_amount)` 을 하면 **금액이 3배로 부풀려진다.** 집계할 때 반드시 조심해야 할 지점이고, 다음 레슨의 검증 쿼리에서 다시 나온다.\n\n### GROUP BY — 집계로 이상 징후 찾기\n\n```sql\n-- 상태별 주문 건수 (배포 전후 비교용)\nSELECT status, COUNT(*) AS cnt\nFROM orders\nWHERE created_at >= '2026-08-15'\nGROUP BY status\nORDER BY cnt DESC;\n```\n\n```sql\n-- 중복 의심: 같은 사용자가 같은 상품을 1분 안에 여러 번 주문\nSELECT user_id, product_id, COUNT(*) AS cnt\nFROM order_items oi\nJOIN orders o ON oi.order_id = o.order_id\nWHERE o.created_at >= '2026-08-15'\nGROUP BY user_id, product_id\nHAVING COUNT(*) > 1;\n```\n\n`WHERE` 는 그룹 짓기 **전** 필터, `HAVING` 은 그룹 지은 **후** 필터다. 이 순서를 기억하면 헷갈리지 않는다.\n\n### MySQL vs MSSQL — QA가 마주치는 차이\n\n같은 SQL이 아니다. 팀 DB가 무엇인지 확인하고 문법을 맞춰야 한다.\n\n| 하는 일 | MySQL | MSSQL (SQL Server) |\n|---|---|---|\n| 상위 N건 | `... LIMIT 10` | `SELECT TOP 10 ...` |\n| 문자열 연결 | `CONCAT(a, b)` | `a + b` 또는 `CONCAT(a, b)` |\n| 현재 시각 | `NOW()` | `GETDATE()` |\n| 날짜 더하기 | `DATE_ADD(d, INTERVAL 1 DAY)` | `DATEADD(day, 1, d)` |\n| NULL 대체 | `IFNULL(a, 0)` / `COALESCE` | `ISNULL(a, 0)` / `COALESCE` |\n| 문자열 자르기 | `SUBSTRING(s, 1, 5)` | 동일 |\n| 식별자 감싸기 | `` `column` `` | `[column]` |\n\n`COALESCE` 는 양쪽에서 다 되므로 이걸 쓰는 습관을 들이면 이식성이 좋다.\n\n**날짜/시간 타입 주의**: MySQL의 `DATETIME` 은 시간대 정보가 없고, `TIMESTAMP` 는 UTC로 저장돼 세션 시간대로 변환된다. 이 차이 때문에 **\"9시간 차이나는 데이터\"** 결함이 자주 발생한다. 조회 결과의 시각이 이상하면 이걸 의심한다.\n\n### DBeaver — 무료 DB 클라이언트\n\nDBeaver Community Edition은 **오픈소스이고 무료**다. MySQL, PostgreSQL, MSSQL, Oracle, SQLite 등 대부분을 하나로 붙일 수 있다.\n\nQA에게 유용한 기능들.\n\n- **ER 다이어그램 자동 생성** — 테이블 간 관계를 그림으로 본다. 처음 보는 스키마를 파악할 때 가장 빠르다\n- **결과를 CSV/Excel로 내보내기** — 결함 리포트 증거 첨부용\n- **읽기 전용 연결 설정** — 실수로 UPDATE를 날리는 사고를 원천 차단한다\n- **SQL 실행 기록** — 내가 뭘 실행했는지 남는다\n\n### 안전 수칙 — 이건 지키지 않으면 사고가 난다\n\n운영 DB 접근 권한을 받았다면 다음을 반드시 지킨다.\n\n1. **읽기 전용 계정을 쓴다.** 권한 자체를 SELECT만 받는 게 가장 안전하다\n2. **UPDATE / DELETE 는 운영에서 실행하지 않는다.** 데이터 수정이 필요하면 개발자에게 요청하고 기록을 남긴다\n3. 테스트 환경에서 UPDATE/DELETE를 쓸 때도 **먼저 SELECT로 대상을 확인**한다\n\n```sql\n-- 1단계: 지울 대상을 먼저 눈으로 본다\nSELECT COUNT(*) FROM orders WHERE user_id = 12345 AND status = 'DRAFT';\n\n-- 2단계: 건수가 예상과 맞으면 그때 실행\nDELETE FROM orders WHERE user_id = 12345 AND status = 'DRAFT';\n```\n\n4. **트랜잭션을 쓸 수 있으면 쓴다.**\n\n```sql\nBEGIN;\nUPDATE orders SET status = 'CANCELLED' WHERE order_id = 'ORD-...';\nSELECT status FROM orders WHERE order_id = 'ORD-...';   -- 확인\n-- 맞으면 COMMIT; 아니면 ROLLBACK;\nROLLBACK;\n```\n\n5. **WHERE 없는 UPDATE/DELETE는 절대 실행하지 않는다.** DBeaver에는 이를 막는 안전장치 설정이 있다. 켜둔다\n\n## 왜 채용시장이 요구하는가\n\n- **QA 채용공고에 SQL이 들어가는 비율이 계속 높아지고 있다.** \"SQL을 활용한 데이터 검증 가능자\"는 이제 흔한 문구다.\n- 면접 실기로 **간단한 조회·JOIN 쿼리를 직접 쓰게 하는 경우**가 있다. 화이트보드에 LEFT JOIN을 그릴 수 있어야 한다.\n- **결함의 원인 범위를 스스로 좁히는 능력**이 협업 비용을 크게 줄인다. 개발자 입장에서 \"DB 확인해 봤더니 이렇더라\"까지 해오는 QA는 완전히 다른 대우를 받는다.\n- **AI가 만든 SQL을 검증하려면 SQL을 읽을 줄 알아야 한다.** AI는 그럴듯하지만 틀린 쿼리를 잘 만든다. 특히 JOIN으로 행이 뻥튀기되는 것, `NOT IN` + NULL 함정, 날짜 경계 처리를 자주 틀린다. 이건 실행해도 에러가 안 나고 **숫자만 조용히 틀린다.** 가장 위험한 종류의 결함이다.\n\n## 실습 과제\n\n### 과제 1 — 무료 환경 준비 (10분)\n\n설치가 부담되면 브라우저에서 바로 되는 것을 쓴다.\n\n- **DB Fiddle** (`https://www.db-fiddle.com`) — MySQL/PostgreSQL을 브라우저에서. 설치 불필요\n- **SQLite Online** (`https://sqliteonline.com`) — 즉시 실행\n- 로컬 설치를 원하면 **DBeaver Community + SQLite** 조합이 가장 가볍다\n\n아래 스키마를 만들고 데이터를 넣는다.\n\n```sql\nCREATE TABLE users (\n  user_id INT PRIMARY KEY,\n  email VARCHAR(100),\n  grade VARCHAR(20)\n);\n\nCREATE TABLE orders (\n  order_id VARCHAR(30) PRIMARY KEY,\n  user_id INT,\n  status VARCHAR(20),\n  total_amount INT,\n  discount_amount INT,\n  created_at DATETIME\n);\n\nCREATE TABLE payments (\n  payment_id INT PRIMARY KEY,\n  order_id VARCHAR(30),\n  amount INT,\n  paid_at DATETIME\n);\n\nINSERT INTO users VALUES\n  (1, 'a@test.com', 'VIP'), (2, 'b@test.com', 'NORMAL'), (3, NULL, 'DORMANT');\n\nINSERT INTO orders VALUES\n  ('ORD-001', 1, 'PAID',      9000,  1000, '2026-08-31 23:30:00'),\n  ('ORD-002', 2, 'PAID',     20000,     0, '2026-08-15 10:00:00'),\n  ('ORD-003', 2, 'CANCELLED', 5000,     0, '2026-08-16 11:00:00'),\n  ('ORD-004', 3, 'PAID',     15000,     0, '2026-08-17 12:00:00');\n\nINSERT INTO payments VALUES\n  (100, 'ORD-001', 9000,  '2026-08-31 23:31:00'),\n  (101, 'ORD-002', 20000, '2026-08-15 10:01:00');\n```\n\n### 과제 2 — 검증 쿼리 6개 작성 (15분)\n\n| # | 뽑을 것 |\n|---|---|\n| 1 | 8월에 생성된 주문 전체 — **8/31 데이터가 빠지지 않게** |\n| 2 | 사용자 이메일과 함께 주문 목록 조회 (JOIN) |\n| 3 | 상태가 PAID 인데 payments 에 기록이 없는 주문 (LEFT JOIN + IS NULL) |\n| 4 | 이메일이 NULL 인 사용자 |\n| 5 | 사용자별 총 결제금액 (CANCELLED 제외) |\n| 6 | 상태별 주문 건수와 금액 합계 |\n\n3번이 **실제 결함 하나를 잡아낸다.** 어떤 주문인지 확인하고, 이게 왜 문제인지 한 줄로 적는다.\n\n### 과제 3 — 함정 직접 겪어보기 (10분)\n\n아래를 실행하고 **결과가 왜 그런지** 설명을 메모에 적는다.\n\n```sql\n-- (1) 이건 왜 0건인가?\nSELECT * FROM users WHERE email = NULL;\n\n-- (2) BETWEEN 으로 8월을 조회하면 몇 건이 나오는가? 위 1번 답과 비교\nSELECT COUNT(*) FROM orders WHERE created_at BETWEEN '2026-08-01' AND '2026-08-31';\n\n-- (3) 이 합계가 맞는가? 왜 그런가?\nSELECT SUM(o.total_amount)\nFROM orders o\nLEFT JOIN payments p ON o.order_id = p.order_id;\n```\n\n### 과제 4 — AI가 만든 SQL 검증 (12분)\n\nAI 실습 도우미에 위 스키마를 그대로 주고 요청한다.\n\n> 이 스키마에서 \"2026년 8월에 결제 완료된 주문의 사용자별 총 결제금액\"을 구하는 쿼리를 작성하라.\n\n받은 쿼리를 **실행하기 전에 눈으로 검증**한다.\n\n| 확인 항목 | 결과 |\n|---|---|\n| 8/31 데이터가 포함되는 날짜 조건인가 (`BETWEEN` 함정) | |\n| CANCELLED 를 제외했는가 | |\n| JOIN으로 행이 중복되어 금액이 부풀려지지 않는가 | |\n| NULL 처리(사용자 정보 없는 주문)를 고려했는가 | |\n| 실제 존재하는 컬럼명만 썼는가 (환각) | |\n\n그다음 실행해서 **손으로 계산한 값과 비교**한다. 에러 없이 실행됐다고 맞는 게 아니다 — 이게 이 과제의 교훈이다.\n\n## 자가 체크리스트\n\n- [ ] QA가 SQL을 쓰는 세 가지 목적을 설명할 수 있다\n- [ ] \"프론트 문제인지 백엔드 문제인지\"를 DB 조회로 스스로 판단할 수 있다\n- [ ] `SELECT *` 대신 필요한 컬럼만 조회하고 LIMIT을 붙이는 습관이 있다\n- [ ] `= NULL` 이 동작하지 않는 이유와 `IS NULL` 을 안다\n- [ ] `NOT IN` 서브쿼리에 NULL이 섞이면 전체가 0건이 되는 함정을 안다\n- [ ] `BETWEEN` 으로 날짜 범위를 잡으면 마지막 날이 누락되는 이유를 설명할 수 있다\n- [ ] INNER JOIN과 LEFT JOIN의 차이를 설명하고 상황에 맞게 고를 수 있다\n- [ ] **LEFT JOIN + IS NULL** 로 \"있어야 하는데 없는 데이터\"를 찾을 수 있다\n- [ ] 1:N JOIN 후 SUM을 하면 금액이 부풀려지는 문제를 알고 있다\n- [ ] WHERE와 HAVING의 적용 시점 차이를 설명할 수 있다\n- [ ] MySQL과 MSSQL의 주요 문법 차이(LIMIT/TOP, NOW/GETDATE 등)를 안다\n- [ ] 운영 DB에서 읽기 전용 계정을 쓰고 UPDATE/DELETE를 실행하지 않는다\n- [ ] UPDATE/DELETE 전에 SELECT로 대상을 먼저 확인하는 절차를 지킨다\n- [ ] AI가 만든 SQL이 \"에러 없이 실행되지만 숫자가 틀린\" 경우를 검증할 수 있다\n\n## 참고 링크\n\n- [DB Fiddle](https://www.db-fiddle.com) — 브라우저에서 MySQL/PostgreSQL 즉시 실행. 무료\n- [SQLite Online](https://sqliteonline.com) — 설치 없이 SQL 연습\n- [DBeaver Community](https://dbeaver.io/) — 오픈소스 무료 DB 클라이언트\n- [MySQL 8.0 레퍼런스 — 함수](https://dev.mysql.com/doc/refman/8.0/en/functions.html) — 함수 존재 여부 확인용 (AI 환각 검증)\n- [SQL Server T-SQL 레퍼런스](https://learn.microsoft.com/ko-kr/sql/t-sql/language-reference) — MSSQL 문법 확인\n- [SQLBolt](https://sqlbolt.com/) — 브라우저에서 하는 무료 SQL 인터랙티브 튜토리얼\n","t2-l05":"---\nid: t2-l05\ntitle: SQL (2) — 데이터 정합성 검증 쿼리 패턴\nsummary: 화면으로는 절대 안 보이는 결함을 찾는 6가지 쿼리 패턴. 그리고 테스트 데이터를 안전하게 만드는 법.\nminutes: 20\norder: 5\ntags: [SQL, 데이터정합성, 테스트데이터, 검증쿼리]\n---\n\n## 개념 설명\n\n### 화면으로는 안 보이는 결함이 있다\n\n앞 레슨에서 LEFT JOIN + IS NULL 로 \"결제완료인데 결제 기록이 없는 주문\"을 찾았다. 이런 결함의 공통점은 **화면에서는 정상으로 보인다**는 것이다.\n\n- 주문 목록 화면은 orders 테이블만 읽으므로 payments 가 비어 있어도 \"결제완료\"로 표시된다\n- 사용자는 아무 이상을 못 느낀다\n- **월말 정산에서 금액이 안 맞을 때 비로소 발견된다**\n\nQA가 SQL을 쓰는 진짜 이유가 여기 있다. **기능 테스트를 아무리 잘해도 데이터 정합성 결함은 안 잡힌다.**\n\n아래 6가지 패턴을 익혀두면 어떤 도메인에서도 응용할 수 있다.\n\n### 패턴 1 — 고아 레코드 (있어야 할 짝이 없다)\n\n```sql\n-- 결제완료 주문인데 결제 기록이 없다\nSELECT o.order_id, o.status, o.total_amount, o.created_at\nFROM orders o\nLEFT JOIN payments p ON o.order_id = p.order_id\nWHERE o.status = 'PAID'\n  AND p.payment_id IS NULL;\n```\n\n```sql\n-- 반대 방향: 결제 기록은 있는데 주문이 사라졌다 (더 심각하다)\nSELECT p.payment_id, p.order_id, p.amount\nFROM payments p\nLEFT JOIN orders o ON p.order_id = o.order_id\nWHERE o.order_id IS NULL;\n```\n\n**두 방향을 다 봐야 한다.** 한쪽만 보면 절반만 찾는다.\n\n### 패턴 2 — 금액·수량 불일치 (계산이 안 맞는다)\n\n```sql\n-- 주문의 총액이 상품 금액 합계 - 할인액과 다르다\nSELECT\n  o.order_id,\n  o.total_amount                                    AS 저장된_총액,\n  SUM(oi.unit_price * oi.quantity)                  AS 상품합계,\n  o.discount_amount                                 AS 할인액,\n  SUM(oi.unit_price * oi.quantity) - o.discount_amount AS 계산된_총액\nFROM orders o\nJOIN order_items oi ON o.order_id = oi.order_id\nGROUP BY o.order_id, o.total_amount, o.discount_amount\nHAVING o.total_amount <> SUM(oi.unit_price * oi.quantity) - o.discount_amount;\n```\n\n```sql\n-- 결제 금액과 주문 금액이 다르다 (돈이 새는 지점)\nSELECT o.order_id, o.total_amount, p.amount, o.total_amount - p.amount AS 차액\nFROM orders o\nJOIN payments p ON o.order_id = p.order_id\nWHERE o.total_amount <> p.amount;\n```\n\n이 쿼리들의 결과가 **0건이어야 정상**이다. 배포 후에 한 번씩 돌려보면 조용히 새는 돈을 잡아낼 수 있다.\n\n### 패턴 3 — 중복 (한 번만 있어야 하는 게 여러 개)\n\n```sql\n-- 같은 주문에 결제가 두 번 기록됨 (중복 결제)\nSELECT order_id, COUNT(*) AS cnt, SUM(amount) AS 총결제액\nFROM payments\nGROUP BY order_id\nHAVING COUNT(*) > 1;\n```\n\n```sql\n-- 이메일 중복 가입 (unique 제약이 없는 경우)\nSELECT LOWER(TRIM(email)) AS normalized, COUNT(*) AS cnt\nFROM users\nWHERE email IS NOT NULL\nGROUP BY LOWER(TRIM(email))\nHAVING COUNT(*) > 1;\n```\n\n두 번째 쿼리에서 `LOWER(TRIM(...))` 을 쓴 이유가 중요하다. **`A@test.com` 과 `a@test.com ` 은 DB 입장에서 다른 값이지만 사용자 입장에서는 같은 계정**이다. 정규화해서 비교하지 않으면 중복을 못 찾는다.\n\n앞 레슨의 Idempotency-Key 이야기와 이어진다. 결제 API를 두 번 호출했을 때 이 쿼리가 1건을 반환해야 정상이다.\n\n### 패턴 4 — 상태 모순 (있을 수 없는 조합)\n\n```sql\n-- 취소됐는데 환불 기록이 없다\nSELECT o.order_id, o.status, o.cancelled_at\nFROM orders o\nLEFT JOIN refunds r ON o.order_id = r.order_id\nWHERE o.status = 'CANCELLED'\n  AND o.total_amount > 0\n  AND r.refund_id IS NULL;\n```\n\n```sql\n-- 배송 시작 시각이 주문 시각보다 빠르다 (시간 역전)\nSELECT order_id, created_at, shipped_at\nFROM orders\nWHERE shipped_at < created_at;\n```\n\n```sql\n-- 상태는 PAID 인데 결제 시각이 NULL\nSELECT order_id, status, paid_at\nFROM orders\nWHERE status = 'PAID' AND paid_at IS NULL;\n```\n\n**시간 역전 검사**는 어느 도메인에서나 유용하다. 타임존 처리 버그, 배치 처리 순서 오류, 서버 간 시계 불일치를 한 번에 잡아낸다.\n\n### 패턴 5 — 배포 전후 대조 (변화량 확인)\n\n트랙 1의 배포 후 검증에서 쓴다. **배포 전에 기준값을 찍어두는 게 핵심**이다.\n\n```sql\n-- 배포 직전에 실행해 결과를 캡처해 둔다\nSELECT\n  status,\n  COUNT(*)          AS 건수,\n  SUM(total_amount) AS 금액합계\nFROM orders\nWHERE created_at >= DATE_SUB(NOW(), INTERVAL 1 DAY)\nGROUP BY status;\n```\n\n배포 후 같은 쿼리를 돌려 **비율이 급변한 상태가 있는지** 본다. 특히 이런 신호를 찾는다.\n\n| 신호 | 의심할 것 |\n|---|---|\n| `FAILED` 비율 급증 | 결제 연동 문제 |\n| `PENDING` 이 쌓이고 안 줄어듦 | 후속 처리 배치가 안 도는 중 |\n| 전체 건수 급감 | 주문 자체가 안 들어옴 — 프론트가 깨졌을 가능성 |\n| 금액 합계만 이상 | 계산 로직 변경의 부작용 |\n\n세 번째가 트랙 1에서 말한 **\"에러는 없는데 전환율이 떨어진\"** 상황이다. 에러 로그로는 안 잡히고 이 쿼리로 잡힌다.\n\n### 패턴 6 — 기대값 대조 (내가 방금 한 행동의 결과 확인)\n\n기능 테스트를 하면서 **화면 확인과 DB 확인을 세트로** 하는 습관이다.\n\n```sql\n-- 방금 만든 주문이 의도대로 저장됐는가\nSELECT\n  order_id,\n  status,                                    -- PENDING 이어야 함\n  total_amount,                              -- 9000 이어야 함\n  discount_amount,                           -- 1000 이어야 함\n  coupon_code,                               -- 'WELCOME10' 이어야 함\n  created_at,\n  TIMESTAMPDIFF(SECOND, created_at, NOW()) AS 경과초   -- 방금 것이 맞는지\nFROM orders\nWHERE user_id = 12345\nORDER BY created_at DESC\nLIMIT 1;\n```\n\n**마지막 컬럼이 실무 팁이다.** 여러 사람이 같은 테스트 계정을 쓰는 환경에서, 조회된 게 내가 방금 만든 것인지 확인할 수 있다.\n\n### 테스트 데이터 만들기 — 안전하게\n\n특정 상태를 만들어야 테스트가 가능한 경우가 많다. \"재고 1개\", \"휴면 회원\", \"쿠폰 만료 직전\". 세 가지 방법이 있고 우선순위가 있다.\n\n| 방법 | 안전도 | 권장 |\n|---|---|---|\n| **1. API/UI로 정상 경로를 통해 만든다** | 높음 | **1순위.** 실제 흐름을 그대로 타므로 부수 데이터도 다 생긴다 |\n| 2. 관리자 기능으로 만든다 | 중간 | 2순위. 있으면 쓴다 |\n| 3. SQL로 직접 INSERT/UPDATE | 낮음 | **최후의 수단** |\n\n3번이 위험한 이유는 **부수 데이터가 안 생기기 때문**이다. UPDATE로 주문 상태만 CANCELLED로 바꾸면 환불 기록도, 재고 복구도, 이력 로그도 없다. 그 상태로 테스트하면 **실제와 다른 조건**을 테스트하게 되고, 최악의 경우 \"테스트에선 됐는데 운영에선 안 되는\" 상황을 만든다.\n\n그래도 3번을 써야 한다면 규칙을 지킨다.\n\n```sql\n-- 1. 트랜잭션으로 감싼다\nBEGIN;\n\n-- 2. 대상을 먼저 확인 (건수가 예상과 맞는가)\nSELECT order_id, status FROM orders WHERE order_id = 'ORD-TEST-001';\n\n-- 3. WHERE 를 반드시 PK 로 좁힌다\nUPDATE orders SET status = 'SHIPPED', shipped_at = NOW()\nWHERE order_id = 'ORD-TEST-001';\n\n-- 4. 결과 확인\nSELECT order_id, status, shipped_at FROM orders WHERE order_id = 'ORD-TEST-001';\n\n-- 5. 맞으면 COMMIT, 아니면 ROLLBACK\nCOMMIT;\n```\n\n그리고 **무엇을 왜 바꿨는지 기록으로 남긴다.** 나중에 \"이 데이터 왜 이래요?\"라는 질문이 반드시 나온다.\n\n**테스트 데이터 식별 규칙**을 팀에 만들어두면 좋다. `qa_` 접두어 계정, `ORD-TEST-` 접두어 주문번호 같은 것이다. 그러면 통계에서 제외하기도 쉽고, 정리하기도 쉽다.\n\n### 이 쿼리들을 자동화하기\n\n정합성 검증 쿼리는 **한 번 만들면 계속 쓴다.** 파일로 모아두고 배포 때마다 돌린다.\n\n```text\nsql/integrity/\n  01_orphan_payments.sql\n  02_amount_mismatch.sql\n  03_duplicate_payments.sql\n  04_status_contradiction.sql\n  05_time_reversal.sql\n```\n\n각 쿼리가 **0건을 반환해야 정상**이 되도록 통일해 두면, 나중에 \"전부 실행해서 0건이 아닌 게 있으면 실패\"로 자동화하기 쉽다. 트랙 3의 CI 연동에서 이걸 실제로 붙인다.\n\n## 왜 채용시장이 요구하는가\n\n- **\"SQL로 데이터 정합성 검증 경험\"** 은 시니어 QA 공고에 자주 등장한다. 조회할 줄 아는 것과 검증 쿼리를 설계할 줄 아는 것은 다른 수준으로 평가된다.\n- 면접 질문: **\"기능 테스트로는 못 잡는 결함의 예를 들어보세요.\"** 여기서 고아 레코드나 금액 불일치를 말하면 강한 답이 된다.\n- **정산·데이터 도메인(금융, 커머스, 물류)에서는 이 능력이 사실상 필수**다. 화면 테스트만 하는 QA는 그 도메인에서 역할이 제한된다.\n- **AI가 만든 검증 쿼리는 실행되지만 조용히 틀린다.** JOIN 중복으로 금액이 부풀려지거나, 한쪽 방향의 고아 레코드만 찾거나, NULL을 고려하지 않는다. 에러가 안 나기 때문에 **눈으로 검증할 줄 모르면 잘못된 \"0건 정상\"을 믿게 된다.** 이게 SQL 영역에서 AI 교차검증이 특히 중요한 이유다.\n\n## 실습 과제\n\n앞 레슨 과제 1의 스키마를 그대로 쓴다. 아래 데이터를 추가한다.\n\n```sql\nCREATE TABLE order_items (\n  item_id INT PRIMARY KEY,\n  order_id VARCHAR(30),\n  product_id INT,\n  unit_price INT,\n  quantity INT\n);\n\nINSERT INTO order_items VALUES\n  (1, 'ORD-001', 501, 5000, 2),\n  (2, 'ORD-002', 502, 10000, 2),\n  (3, 'ORD-003', 503, 5000, 1),\n  (4, 'ORD-004', 504, 7000, 2);\n\n-- 중복 결제와 시간 역전을 일부러 심어둔다\nINSERT INTO payments VALUES (102, 'ORD-002', 20000, '2026-08-15 10:02:00');\nINSERT INTO payments VALUES (103, 'ORD-999', 30000, '2026-08-18 09:00:00');\n```\n\n### 과제 1 — 6가지 패턴 전부 실행 (20분)\n\n각 패턴의 쿼리를 직접 작성해 실행하고, **발견한 이상 데이터를 표로 정리**한다.\n\n| 패턴 | 발견 건수 | 어떤 데이터인가 | 왜 문제인가 |\n|---|---|---|---|\n| 고아 레코드 (주문→결제) | | | |\n| 고아 레코드 (결제→주문) | | | |\n| 금액 불일치 | | | |\n| 중복 결제 | | | |\n| 상태 모순 | | | |\n| 시간 역전 | | | |\n\n**심어둔 결함이 최소 4개 있다.** 몇 개를 찾았는지 세어본다. (`ORD-001` 의 금액도 확인해 볼 것)\n\n### 과제 2 — 결함 리포트로 옮기기 (10분)\n\n과제 1에서 찾은 것 중 **가장 심각한 하나**를 골라 트랙 1의 형식으로 결함 리포트를 작성한다.\n\n포함할 것:\n- 재현 절차에 **검증 쿼리를 그대로** 넣기\n- 실제 결과에 쿼리 결과 표를 붙이기\n- **심각도 판단 근거** — 돈이 걸렸는가, 데이터가 유실되는가\n- 이 결함이 화면에서는 왜 안 보이는지 설명\n\n### 과제 3 — 정합성 쿼리 세트 만들기 (12분)\n\n본인이 아는 서비스 도메인 하나를 골라 **그 도메인의 정합성 검증 쿼리 5개**를 설계한다. (실행 못 해도 되고, 의사 쿼리여도 된다)\n\n예시 도메인과 검증 포인트:\n- 예약 서비스 → 같은 시간대 중복 예약, 취소됐는데 좌석이 안 풀린 것\n- 포인트 시스템 → 적립 합계 - 사용 합계 ≠ 현재 잔액\n- 구독 서비스 → 결제 실패했는데 이용 권한이 살아있는 계정\n\n**\"이 쿼리는 0건이어야 정상\"** 형태로 통일해서 쓴다.\n\n### 과제 4 — AI 생성 검증 쿼리 교차검증 (12분)\n\nAI 실습 도우미에 스키마 전체를 주고 요청한다.\n\n> 이 스키마에서 데이터 정합성을 검증하는 쿼리를 5개 작성하라. 각 쿼리는 문제가 없으면 0건을 반환해야 한다.\n\n받은 쿼리를 **실행 전에 손으로 검토**한다.\n\n| 확인 항목 | 결과 |\n|---|---|\n| 고아 레코드를 **양방향** 모두 확인했는가 | |\n| JOIN 중복으로 금액이 부풀려지지 않는가 | |\n| NULL 값을 고려했는가 (`NOT IN`, 비교 연산) | |\n| 날짜 비교에서 경계가 정확한가 | |\n| 존재하지 않는 컬럼·테이블·함수를 쓰지 않았는가 | |\n| \"0건이면 정상\" 규칙을 실제로 지켰는가 (반대로 짠 것은 없는가) | |\n\n마지막 항목을 꼭 본다. **AI가 \"정상 데이터를 찾는 쿼리\"를 만들어 놓고 0건 기준이라고 설명하는 경우가 있다.** 그대로 자동화에 넣으면 항상 실패하거나 항상 통과한다.\n\n그다음 실행해서, 내가 과제 1에서 찾은 4개 결함 중 **AI 쿼리가 몇 개를 잡아내는지** 센다.\n\n## 자가 체크리스트\n\n- [ ] 기능 테스트로는 잡히지 않는 데이터 정합성 결함의 예를 들 수 있다\n- [ ] 고아 레코드를 **양방향**으로 검사해야 하는 이유를 설명할 수 있다\n- [ ] 금액 불일치 검증 쿼리를 GROUP BY + HAVING 으로 작성할 수 있다\n- [ ] 중복 검사 시 `LOWER(TRIM())` 등으로 정규화해야 하는 이유를 안다\n- [ ] 상태 모순과 시간 역전 검사 쿼리를 작성할 수 있다\n- [ ] 배포 전에 기준값을 캡처해 두고 배포 후 대조하는 절차를 수행할 수 있다\n- [ ] 상태별 건수 급변에서 무엇을 의심해야 하는지 4가지 이상 안다\n- [ ] 기능 테스트 중 화면 확인과 DB 확인을 세트로 하는 습관이 있다\n- [ ] 테스트 데이터는 API/UI 정상 경로로 만드는 것이 1순위인 이유를 설명할 수 있다\n- [ ] SQL로 직접 데이터를 조작하면 부수 데이터가 누락된다는 위험을 안다\n- [ ] UPDATE 시 트랜잭션 + PK 조건 + 전후 확인 절차를 지킨다\n- [ ] 테스트 데이터에 식별 접두어를 붙여 통계에서 분리한다\n- [ ] 정합성 쿼리를 \"0건이면 정상\" 형태로 통일해 자동화 가능하게 만든다\n- [ ] AI가 만든 검증 쿼리가 조용히 틀리는 지점(JOIN 중복, 단방향 검사, NULL)을 짚어낼 수 있다\n\n## 참고 링크\n\n- [Use The Index, Luke!](https://use-the-index-luke.com/ko) — SQL 성능과 실행 계획. 한국어 번역 있음\n- [PostgreSQL 문서 — 조인 유형](https://www.postgresql.org/docs/current/queries-table-expressions.html) — JOIN 동작의 정확한 정의\n- [SQL Style Guide](https://www.sqlstyle.guide/) — 팀에서 공유할 쿼리를 읽기 좋게 쓰는 규칙\n- [DB Fiddle](https://www.db-fiddle.com) — 실습 환경\n","t2-l06":"---\nid: t2-l06\ntitle: 로그·모니터링 기반 원인 분석 — Datadog · Grafana\nsummary: \"안 돼요\"에서 \"이 요청이 이 시각에 이 이유로 실패했습니다\"까지. 로그를 읽고 대시보드에서 이상을 찾는 법.\nminutes: 20\norder: 6\ntags: [로그, 모니터링, Datadog, Grafana, 옵저버빌리티, TraceID]\n---\n\n## 개념 설명\n\n### QA가 로그를 봐야 하는 이유\n\n같은 결함을 발견해도 리포트의 가치가 완전히 달라진다.\n\n```text\n[약함] 결제가 가끔 실패해요\n[강함] 14:32:07 에 order-service 에서 PaymentGatewayTimeoutException 발생.\n       trace_id=7f3a9b2c. 외부 결제사 응답이 5초 타임아웃을 넘겼고,\n       재시도 없이 500 을 반환했습니다. 최근 1시간 동일 예외 23건.\n```\n\n두 번째 리포트는 **개발자가 재현할 필요조차 없다.** 원인이 이미 적혀 있다. 이런 리포트를 쓰는 QA는 팀에서 위치가 달라진다.\n\n그리고 트랙 1에서 다룬 배포 후 검증, Go/No-Go 판단의 근거가 전부 이 도구들에서 나온다.\n\n### 옵저버빌리티의 세 기둥\n\n| 기둥 | 무엇인가 | QA가 쓰는 상황 |\n|---|---|---|\n| **로그 (Logs)** | 시점별 이벤트 기록. 텍스트 | \"그때 무슨 일이 있었나\" 개별 사건 추적 |\n| **메트릭 (Metrics)** | 시간에 따른 숫자. 집계 | \"지금 정상인가\" 전체 상태 판단 |\n| **트레이스 (Traces)** | 요청 하나가 거친 서비스들의 경로 | \"어느 구간에서 느려졌나\" 병목 특정 |\n\n세 가지를 순서대로 쓴다. **메트릭으로 이상을 감지 → 트레이스로 구간 특정 → 로그로 원인 확인.**\n\n### 로그 읽는 법\n\n**로그 레벨**부터. 이걸 알아야 무엇을 무시하고 무엇을 봐야 하는지 판단한다.\n\n| 레벨 | 의미 | QA의 반응 |\n|---|---|---|\n| `ERROR` | 처리 실패. 사용자 영향 있음 | **무조건 확인** |\n| `WARN` | 이상하지만 처리는 됨 | 급증하면 확인 (재시도, 폴백 동작 중일 수 있음) |\n| `INFO` | 정상 흐름 기록 | 재현 경로 추적용 |\n| `DEBUG` | 개발용 상세 | 보통 운영엔 없음 |\n\n**구조화 로그(JSON)** 를 쓰는 팀이 많다. 이런 형태다.\n\n```json\n{\n  \"timestamp\": \"2026-08-15T14:32:07.412+09:00\",\n  \"level\": \"ERROR\",\n  \"service\": \"order-service\",\n  \"trace_id\": \"7f3a9b2c1d4e5f60\",\n  \"user_id\": 12345,\n  \"order_id\": \"ORD-20260815-0001\",\n  \"message\": \"Payment gateway timeout\",\n  \"exception\": \"PaymentGatewayTimeoutException\",\n  \"duration_ms\": 5031,\n  \"http_status\": 500\n}\n```\n\nQA가 여기서 뽑아 쓰는 필드는 정해져 있다.\n\n- **`trace_id`** — 이게 가장 중요하다. 뒤에서 따로 다룬다\n- `timestamp` — 결함 리포트에 초 단위까지 적는다\n- `service` — 어느 팀에 티켓을 보낼지 결정된다\n- `duration_ms` — 타임아웃인지 즉시 실패인지 구분\n- `exception` — 그대로 검색하면 같은 유형의 다른 사례가 나온다\n\n### trace_id — QA가 반드시 익혀야 할 개념\n\n요즘 서비스는 요청 하나가 여러 서비스를 거친다.\n\n```text\n[사용자] → api-gateway → order-service → payment-service → 외부 결제사\n                              ↓\n                        inventory-service\n```\n\n이때 각 서비스가 남기는 로그를 **하나의 요청으로 묶어주는 식별자**가 trace_id다. 이게 없으면 서비스 5개의 로그를 시각으로 눈대중해서 맞춰야 한다.\n\n**QA의 실전 활용법**\n\n1. 테스트 중 오류가 나면 **화면이나 응답 헤더에서 trace_id를 먼저 찾는다** (`X-Trace-Id`, `X-Request-Id` 같은 헤더로 내려오는 경우가 많다)\n2. 없으면 브라우저 개발자도구 Network 탭에서 실패한 요청의 응답 헤더 확인\n3. 그 값으로 로그를 검색하면 **그 요청이 거친 전 구간의 로그가 한 번에** 나온다\n4. 결함 리포트에 trace_id를 적는다\n\n**결함 리포트에 trace_id 한 줄이 들어가면 개발자의 조사 시간이 몇십 분에서 몇 분으로 줄어든다.** 앞 레슨의 curl 명령과 함께, QA가 붙일 수 있는 가장 값싼 증거다.\n\n### 로그 검색 문법\n\n도구마다 문법은 다르지만 개념은 같다.\n\n```text\n# Datadog 로그 검색\nservice:order-service status:error @trace_id:7f3a9b2c1d4e5f60\nservice:payment-service @duration_ms:>3000\n@http.status_code:5* -service:health-check\n\n# Grafana Loki (LogQL)\n{service=\"order-service\"} |= \"PaymentGatewayTimeout\"\n{service=\"order-service\"} | json | duration_ms > 3000\n\n# Kibana / OpenSearch (Lucene)\nservice:\"order-service\" AND level:ERROR AND NOT message:\"health\"\n```\n\n공통 패턴 네 가지만 알면 된다.\n\n| 하고 싶은 것 | 방법 |\n|---|---|\n| 특정 서비스의 에러만 | `service:X level:ERROR` |\n| 특정 요청 추적 | `trace_id:값` |\n| 느린 요청 찾기 | `duration_ms:>3000` |\n| 노이즈 제거 | `-service:health-check` (앞에 `-` 로 제외) |\n\n마지막이 실무에서 중요하다. 헬스체크·봇 트래픽을 빼지 않으면 진짜 문제가 묻힌다.\n\n### 메트릭 대시보드 — 무엇을 볼 것인가\n\nGoogle SRE의 **4가지 골든 시그널**이 기준이다. 트랙 1의 배포 후 검증과 직결된다.\n\n| 시그널 | 지표 | 이상 신호 |\n|---|---|---|\n| **Latency (지연)** | p50 / p95 / p99 응답시간 | p99만 튀면 특정 조건에서만 느림 |\n| **Traffic (처리량)** | RPS, 요청 수 | 급감 = 사용자가 도달 못 하는 중 |\n| **Errors (에러)** | 5xx 비율, 4xx 비율 | 배포 직후 급증 → 롤백 검토 |\n| **Saturation (포화)** | CPU, 메모리, 커넥션 풀 | 포화 직전이면 곧 지연·에러로 번진다 |\n\n**평균이 아니라 백분위수(percentile)를 봐야 하는 이유**를 이해하는 게 핵심이다.\n\n```text\n응답시간 100건: 95건이 100ms, 5건이 10초\n\n평균 = 595ms   → \"좀 느리네\" (문제를 놓친다)\np95  = 100ms   → 정상 구간\np99  = 10초    → 100명 중 1명은 10초를 기다린다 ← 실제 문제\n```\n\n**평균은 소수의 심각한 사례를 숨긴다.** 트랙 5(성능 테스트)에서 이 개념을 본격적으로 다룬다.\n\n또 하나 중요한 관점. **에러율이 0인데도 문제가 있을 수 있다.**\n\n| 상황 | 에러율 | 실제 문제 |\n|---|---|---|\n| 버튼이 화면 밖으로 밀림 | 0% | 아무도 클릭을 못 함 → 주문 수 급감 |\n| 검색 결과가 항상 0건 | 0% | 200 OK 로 빈 배열 반환 |\n| 결제 성공했는데 주문 미생성 | 0% | 양쪽 다 200 |\n\n그래서 **기술 지표만 보면 안 되고 비즈니스 지표를 함께 봐야 한다.** 주문 완료 수, 로그인 성공률, 검색 결과 0건 비율 같은 것들이다. QA가 대시보드에 이런 패널을 추가해달라고 요청할 수 있으면 좋다.\n\n### Datadog 과 Grafana — 무엇이 다른가\n\n| | Datadog | Grafana |\n|---|---|---|\n| 형태 | SaaS (호스팅형) | 오픈소스 + Grafana Cloud |\n| 데이터 소스 | 자체 에이전트로 수집 | Prometheus, Loki, Elasticsearch 등 **연결해서 씀** |\n| 강점 | 설치하면 바로 통합됨. APM·로그·메트릭 한 화면 | 무료, 커스터마이징 자유, 벤더 종속 없음 |\n| 비용 | 유료 (호스트 단위 과금) | OSS 무료 / Cloud 무료 티어 있음 |\n| 학습 | 개념 이해 위주 | **직접 만져볼 수 있다** |\n\n**학습 목적으로는 Grafana를 권한다.** 무료이고, `play.grafana.org` 라는 공개 데모 사이트에서 실제 대시보드를 바로 만져볼 수 있다.\n\nDatadog은 개인이 실습하기 어려우므로 **개념과 화면 구성을 아는 수준**으로 접근한다. 실무에서 Datadog을 쓰는 팀에 가더라도, Grafana에서 익힌 개념(패널, 쿼리, 시간 범위, 알림 임계치)이 그대로 통한다.\n\n### 알림(Alert) — QA가 관여할 지점\n\n알림 규칙은 보통 개발/SRE가 만들지만, **QA가 제안할 수 있는 알림**이 있다.\n\n```text\n□ 결제 실패율이 5분간 5% 초과\n□ 주문 생성 수가 지난주 같은 시간대 대비 50% 이하\n□ 특정 예외(PaymentGatewayTimeoutException)가 5분간 10건 초과\n□ p99 응답시간이 3초 초과 상태로 10분 지속\n```\n\n두 번째가 QA다운 제안이다. **에러가 아니라 \"일어나야 할 일이 안 일어나는 것\"을 감지**한다.\n\n알림 설계에서 조심할 것: **알림 피로(alert fatigue)**. 너무 많이 울리면 아무도 안 본다. 트랙 1의 \"롤백 기준을 숫자로\" 와 같은 원칙이다 — **행동할 수 있는 알림만 만든다.**\n\n### 실전 흐름 — 결함을 만났을 때\n\n```text\n1. 화면/응답에서 trace_id 확보 (없으면 정확한 시각 초 단위로 기록)\n2. 개발자도구 Network 탭 → 실패한 요청의 상태코드·응답 바디 확인\n3. 로그 검색: trace_id 또는 (service + 시각 범위 + level:ERROR)\n4. 예외 이름과 스택 확인 → 어느 서비스, 어느 구간인지 특정\n5. 메트릭 대시보드에서 같은 시각대의 에러율·지연 확인\n   → 나만의 문제인가, 전체 문제인가 판단\n6. 같은 예외의 최근 발생 건수 조회 → 재현율과 영향 범위 추정\n7. 결함 리포트 작성 (trace_id, 시각, 예외명, 발생 건수 포함)\n```\n\n5번이 중요하다. **\"나만 안 되는 것\"과 \"전체가 안 되는 것\"은 심각도가 완전히 다르다.**\n\n## 왜 채용시장이 요구하는가\n\n- 채용공고의 **\"로그 분석을 통한 이슈 원인 파악\"**, **\"모니터링 도구 활용 경험\"** 은 이제 흔한 항목이다. 특히 마이크로서비스 환경의 회사는 반드시 본다.\n- **원인 분석까지 하는 QA와 현상만 보고하는 QA의 차이**가 연차 대비 평가를 가른다. 면접에서 \"결함의 원인을 어떻게 파악하셨나요?\"에 로그·트레이스 이야기를 할 수 있으면 강하다.\n- **배포 후 검증을 실제로 수행하려면 대시보드를 읽을 줄 알아야 한다.** 트랙 1의 Go/No-Go와 롤백 판단이 여기에 의존한다.\n- **AI가 로그 분석을 도와주는 시대**지만, AI에게 로그를 붙여넣고 \"원인이 뭐야?\"라고 물으면 **그럴듯한 원인을 지어낸다.** 실제로는 로그에 없는 인과관계를 만들어내고, 존재하지 않는 예외 클래스명을 언급하기도 한다. 로그를 직접 읽을 수 있어야 그 답을 검증할 수 있다.\n\n## 실습 과제\n\n### 과제 1 — Grafana 공개 데모 둘러보기 (15분)\n\n`https://play.grafana.org` 는 로그인 없이 쓸 수 있는 Grafana 공식 데모다.\n\n1. 아무 대시보드나 열어 **패널 하나를 골라** 무슨 지표인지 파악\n2. **시간 범위를 바꿔본다** (최근 5분 / 6시간 / 7일) — 같은 데이터가 어떻게 다르게 보이는지\n3. 패널 제목 → Edit 또는 Inspect → **쿼리를 직접 본다.** 무엇을 어떻게 집계하고 있는가\n4. 그래프에서 **튀는 지점(spike)** 을 찾아 그 시각을 기록\n5. 메모에 적기: 이 대시보드에서 \"지금 서비스가 정상인가\"를 판단하려면 어느 패널 3개를 봐야 하는가\n\n### 과제 2 — 브라우저에서 trace_id 찾기 (10분)\n\n아무 웹서비스나 열고 개발자도구 → Network 탭에서:\n\n1. API 요청 하나를 골라 **응답 헤더 전체**를 본다\n2. `X-Request-Id`, `X-Trace-Id`, `X-Correlation-Id`, `traceparent` 중 있는 것을 찾는다\n3. 없다면: 이 서비스에서 결함을 발견했을 때 **개발자에게 무엇을 대신 줘야 하는가**를 적는다\n4. 요청을 **Copy as cURL** 로 복사해 본다 (결함 리포트 재현 절차용)\n\n### 과제 3 — 로그에서 원인 추론 (12분)\n\n아래 로그를 읽고 질문에 답한다.\n\n```json\n{\"ts\":\"2026-08-15T14:32:02.100+09:00\",\"level\":\"INFO\",\"service\":\"api-gateway\",\"trace_id\":\"7f3a9b2c\",\"msg\":\"POST /api/v1/orders\",\"user_id\":12345}\n{\"ts\":\"2026-08-15T14:32:02.180+09:00\",\"level\":\"INFO\",\"service\":\"order-service\",\"trace_id\":\"7f3a9b2c\",\"msg\":\"order created\",\"order_id\":\"ORD-0001\",\"status\":\"PENDING\"}\n{\"ts\":\"2026-08-15T14:32:02.240+09:00\",\"level\":\"INFO\",\"service\":\"inventory-service\",\"trace_id\":\"7f3a9b2c\",\"msg\":\"stock reserved\",\"product_id\":501,\"qty\":2}\n{\"ts\":\"2026-08-15T14:32:07.271+09:00\",\"level\":\"ERROR\",\"service\":\"payment-service\",\"trace_id\":\"7f3a9b2c\",\"msg\":\"Payment gateway timeout\",\"exception\":\"PaymentGatewayTimeoutException\",\"duration_ms\":5031}\n{\"ts\":\"2026-08-15T14:32:07.280+09:00\",\"level\":\"ERROR\",\"service\":\"order-service\",\"trace_id\":\"7f3a9b2c\",\"msg\":\"order creation failed\",\"order_id\":\"ORD-0001\",\"http_status\":500}\n```\n\n1. 사용자가 본 화면은 무엇이었을까?\n2. **주문 ORD-0001 은 지금 어떤 상태로 남아 있는가?** (로그에 명시되지 않았다 — 무엇을 확인해야 알 수 있는가)\n3. **예약된 재고 2개는 어떻게 됐는가?** 이게 왜 문제인가\n4. 이 로그에서 **가장 심각한 결함**은 타임아웃 자체인가, 아니면 다른 것인가\n5. 추가로 확인해야 할 것 3가지 (앞 레슨의 SQL 정합성 쿼리를 떠올려 볼 것)\n\n**힌트**: 3번이 트랙 2 전체를 관통하는 문제다. 보상 트랜잭션(compensating transaction)이 없으면 재고가 영원히 묶인다.\n\n### 과제 4 — 알림 규칙 설계 (8분)\n\n본인이 아는 서비스 하나를 골라 알림 규칙 5개를 설계한다.\n\n| # | 조건 | 임계치 | 왜 이 숫자인가 | 울리면 누가 무엇을 하나 |\n|---|---|---|---|---|\n| 1 | | | | |\n\n**마지막 열이 핵심이다.** 받고 나서 할 일이 없는 알림은 만들지 않는다. 5개 중 최소 1개는 \"에러가 아니라 일어나야 할 일이 안 일어나는 것\"을 감지하는 규칙으로 만든다.\n\n### 과제 5 — AI 로그 분석 교차검증 (10분)\n\nAI 실습 도우미에 과제 3의 로그를 그대로 붙여넣고 원인 분석을 요청한다.\n\n받은 답변을 **다음 기준으로 검증**한다.\n\n| 확인 항목 | 결과 |\n|---|---|\n| 로그에 **실제로 있는** 사실만 근거로 삼았는가 | |\n| 로그에 없는 인과관계를 지어내지 않았는가 | |\n| 재고 예약이 롤백되지 않은 문제를 짚었는가 | |\n| 주문 상태가 불확실하다는 점을 \"확인 필요\"로 남겼는가 | |\n| 존재하지 않는 예외 클래스나 서비스명을 언급하지 않았는가 | |\n\n**AI는 대체로 타임아웃을 원인으로 잘 짚는다. 그런데 \"예약된 재고가 어떻게 됐는지\"는 잘 묻지 않는다.** 로그에 명시되지 않은 것을 의심하는 게 사람의 몫이다.\n\n## 자가 체크리스트\n\n- [ ] 옵저버빌리티의 세 기둥(로그·메트릭·트레이스)과 각각을 쓰는 상황을 구분할 수 있다\n- [ ] 메트릭 → 트레이스 → 로그 순으로 좁혀가는 분석 흐름을 설명할 수 있다\n- [ ] 로그 레벨별로 무엇을 확인하고 무엇을 무시할지 판단할 수 있다\n- [ ] 구조화 로그에서 QA가 쓸 필드 5가지를 뽑아낼 수 있다\n- [ ] trace_id 의 역할을 설명하고, 응답 헤더나 개발자도구에서 찾을 수 있다\n- [ ] 결함 리포트에 trace_id·정확한 시각·예외명·발생 건수를 포함시킨다\n- [ ] 로그 검색에서 서비스 필터, 시간 범위, 제외 조건(`-`)을 조합할 수 있다\n- [ ] 4가지 골든 시그널(지연·처리량·에러·포화)을 나열하고 각각의 이상 신호를 안다\n- [ ] 평균 대신 p95/p99 를 봐야 하는 이유를 예시로 설명할 수 있다\n- [ ] 에러율 0%인데도 장애인 상황을 3가지 이상 들 수 있다\n- [ ] 기술 지표 외에 비즈니스 지표(주문 수, 로그인 성공률)를 함께 봐야 하는 이유를 안다\n- [ ] Datadog과 Grafana의 차이(SaaS/오픈소스, 수집/연결)를 설명할 수 있다\n- [ ] \"일어나야 할 일이 안 일어나는 것\"을 감지하는 알림을 설계할 수 있다\n- [ ] 알림 피로를 피하기 위해 행동 가능한 알림만 만든다는 원칙을 안다\n- [ ] AI 로그 분석에서 지어낸 인과관계와 누락된 관점을 짚어낼 수 있다\n\n## 참고 링크\n\n- [Grafana Play (공개 데모)](https://play.grafana.org) — 로그인 없이 실제 대시보드를 만져볼 수 있다. 무료\n- [Google SRE Book — Monitoring Distributed Systems](https://sre.google/sre-book/monitoring-distributed-systems/) — 4가지 골든 시그널의 출처\n- [OpenTelemetry 문서](https://opentelemetry.io/docs/concepts/) — trace_id, span 개념의 표준 정의\n- [Grafana Loki — LogQL](https://grafana.com/docs/loki/latest/query/) — 로그 쿼리 문법\n- [Datadog 로그 검색 문법](https://docs.datadoghq.com/logs/explorer/search_syntax/) — 실무에서 자주 쓰는 쿼리 패턴\n- [W3C Trace Context](https://www.w3.org/TR/trace-context/) — `traceparent` 헤더 표준\n"},"data":{"progress-snapshot":{"generatedAt":null,"totalLessons":0,"completedCount":0,"percent":0,"streak":{"current":0,"longest":0,"lastStudyDate":null},"nextLesson":null,"completedLessonIds":[],"weakItems":[]}}};
